/**
 * Bundle Size Performance Tests
 * 
 * Tests to verify that the frontend bundle size meets performance requirements.
 * 
 * Requirements: 5.9, 10.8
 */

import { describe, test, expect } from '@jest/globals';
import fs from 'fs';
import path from 'path';

describe('Bundle Size Performance Tests', () => {
  const distPath = path.join(__dirname, '../../../dist');
  const maxInitialBundleSize = 500 * 1024; // 500KB requirement from 10.8
  const maxVisualizationChunkSize = 600 * 1024; // 600KB for visualization chunks

  // Check if this is a production build
  const isProductionBuild = fs.existsSync(distPath) && 
    fs.existsSync(path.join(distPath, 'static')) &&
    !fs.existsSync(path.join(distPath, 'static', 'webpack', 'webpack.hot-update.json'));

  if (!isProductionBuild) {
    test.skip('Bundle size tests require production build - run "npm run build" first', () => {
      // This test will be skipped
    });
  }

  /**
   * Helper function to get file size in bytes
   */
  function getFileSize(filePath: string): number {
    try {
      const stats = fs.statSync(filePath);
      return stats.size;
    } catch (error) {
      return 0;
    }
  }

  /**
   * Helper function to get all files in a directory recursively
   */
  function getAllFiles(dirPath: string, arrayOfFiles: string[] = []): string[] {
    if (!fs.existsSync(dirPath)) {
      return arrayOfFiles;
    }

    const files = fs.readdirSync(dirPath);

    files.forEach((file) => {
      const filePath = path.join(dirPath, file);
      if (fs.statSync(filePath).isDirectory()) {
        arrayOfFiles = getAllFiles(filePath, arrayOfFiles);
      } else {
        arrayOfFiles.push(filePath);
      }
    });

    return arrayOfFiles;
  }

  /**
   * Helper function to calculate total size of JS files
   */
  function calculateJSBundleSize(files: string[]): number {
    return files
      .filter((file) => file.endsWith('.js') && !file.includes('.map'))
      .reduce((total, file) => total + getFileSize(file), 0);
  }

  test('initial bundle size should be below 500KB', () => {
    if (!isProductionBuild) {
      console.warn('⚠️  Skipping: Production build required. Run "npm run build" first.');
      return;
    }

    // Skip if dist folder doesn't exist (not built yet)
    if (!fs.existsSync(distPath)) {
      console.warn('⚠️  Dist folder not found. Run "npm run build" first.');
      return;
    }

    const staticPath = path.join(distPath, 'static');
    if (!fs.existsSync(staticPath)) {
      console.warn('⚠️  Static folder not found in dist.');
      return;
    }

    // Get all JS files in the static folder
    const allFiles = getAllFiles(staticPath);
    const jsFiles = allFiles.filter(
      (file) => file.endsWith('.js') && !file.includes('.map')
    );

    // Calculate initial bundle size (vendor + ui + forms + common chunks)
    const initialChunks = jsFiles.filter(
      (file) =>
        file.includes('vendor') ||
        file.includes('ui') ||
        file.includes('forms') ||
        file.includes('common') ||
        file.includes('main') ||
        file.includes('webpack')
    );

    const initialBundleSize = calculateJSBundleSize(initialChunks);

    console.log(`📦 Initial bundle size: ${(initialBundleSize / 1024).toFixed(2)} KB`);
    console.log(`📊 Breakdown:`);
    initialChunks.forEach((file) => {
      const size = getFileSize(file);
      const fileName = path.basename(file);
      console.log(`   - ${fileName}: ${(size / 1024).toFixed(2)} KB`);
    });

    expect(initialBundleSize).toBeLessThanOrEqual(maxInitialBundleSize);
  });

  test('visualization chunks should be lazy-loaded', () => {
    if (!isProductionBuild) {
      console.warn('⚠️  Skipping: Production build required. Run "npm run build" first.');
      return;
    }

    if (!fs.existsSync(distPath)) {
      console.warn('⚠️  Dist folder not found. Run "npm run build" first.');
      return;
    }

    const staticPath = path.join(distPath, 'static');
    if (!fs.existsSync(staticPath)) {
      console.warn('⚠️  Static folder not found in dist.');
      return;
    }

    const allFiles = getAllFiles(staticPath);
    const jsFiles = allFiles.filter(
      (file) => file.endsWith('.js') && !file.includes('.map')
    );

    // Check for visualization chunks (should be separate from main bundle)
    const visualizationChunks = jsFiles.filter(
      (file) =>
        file.includes('visualization') ||
        file.includes('dependency-graph') ||
        file.includes('architecture-graph') ||
        file.includes('neo4j-graph') ||
        file.includes('d3') ||
        file.includes('reactflow')
    );

    console.log(`📊 Visualization chunks found: ${visualizationChunks.length}`);
    visualizationChunks.forEach((file) => {
      const size = getFileSize(file);
      const fileName = path.basename(file);
      console.log(`   - ${fileName}: ${(size / 1024).toFixed(2)} KB`);
    });

    // Verify that visualization chunks exist (lazy loading is working)
    expect(visualizationChunks.length).toBeGreaterThan(0);

    // Verify each visualization chunk is within reasonable size
    visualizationChunks.forEach((file) => {
      const size = getFileSize(file);
      expect(size).toBeLessThanOrEqual(maxVisualizationChunkSize);
    });
  });

  test('code splitting should create separate chunks for different routes', () => {
    if (!isProductionBuild) {
      console.warn('⚠️  Skipping: Production build required. Run "npm run build" first.');
      return;
    }

    if (!fs.existsSync(distPath)) {
      console.warn('⚠️  Dist folder not found. Run "npm run build" first.');
      return;
    }

    const staticPath = path.join(distPath, 'static');
    if (!fs.existsSync(staticPath)) {
      console.warn('⚠️  Static folder not found in dist.');
      return;
    }

    const allFiles = getAllFiles(staticPath);
    const jsFiles = allFiles.filter(
      (file) => file.endsWith('.js') && !file.includes('.map')
    );

    // Count unique chunks (should have multiple chunks for code splitting)
    const uniqueChunks = new Set(
      jsFiles.map((file) => {
        const fileName = path.basename(file);
        // Extract chunk name (before hash)
        const match = fileName.match(/^([a-z-]+)/);
        return match ? match[1] : fileName;
      })
    );

    console.log(`📦 Unique chunks created: ${uniqueChunks.size}`);
    console.log(`   Chunks: ${Array.from(uniqueChunks).join(', ')}`);

    // Should have at least 5 different chunks (vendor, ui, forms, common, + route chunks)
    expect(uniqueChunks.size).toBeGreaterThanOrEqual(5);
  });

  test('total bundle size should be reasonable', () => {
    if (!isProductionBuild) {
      console.warn('⚠️  Skipping: Production build required. Run "npm run build" first.');
      return;
    }

    if (!fs.existsSync(distPath)) {
      console.warn('⚠️  Dist folder not found. Run "npm run build" first.');
      return;
    }

    const staticPath = path.join(distPath, 'static');
    if (!fs.existsSync(staticPath)) {
      console.warn('⚠️  Static folder not found in dist.');
      return;
    }

    const allFiles = getAllFiles(staticPath);
    const totalBundleSize = calculateJSBundleSize(allFiles);

    console.log(`📦 Total bundle size: ${(totalBundleSize / 1024).toFixed(2)} KB`);

    // Total bundle should be under 2MB (reasonable for a full-featured app)
    const maxTotalBundleSize = 2 * 1024 * 1024; // 2MB
    expect(totalBundleSize).toBeLessThanOrEqual(maxTotalBundleSize);
  });

  test('CSS bundle size should be reasonable', () => {
    if (!isProductionBuild) {
      console.warn('⚠️  Skipping: Production build required. Run "npm run build" first.');
      return;
    }

    if (!fs.existsSync(distPath)) {
      console.warn('⚠️  Dist folder not found. Run "npm run build" first.');
      return;
    }

    const staticPath = path.join(distPath, 'static');
    if (!fs.existsSync(staticPath)) {
      console.warn('⚠️  Static folder not found in dist.');
      return;
    }

    const allFiles = getAllFiles(staticPath);
    const cssFiles = allFiles.filter((file) => file.endsWith('.css'));

    const totalCSSSize = cssFiles.reduce(
      (total, file) => total + getFileSize(file),
      0
    );

    console.log(`🎨 Total CSS size: ${(totalCSSSize / 1024).toFixed(2)} KB`);
    cssFiles.forEach((file) => {
      const size = getFileSize(file);
      const fileName = path.basename(file);
      console.log(`   - ${fileName}: ${(size / 1024).toFixed(2)} KB`);
    });

    // CSS should be under 200KB
    const maxCSSSize = 200 * 1024; // 200KB
    expect(totalCSSSize).toBeLessThanOrEqual(maxCSSSize);
  });

  test('no duplicate dependencies in chunks', () => {
    if (!isProductionBuild) {
      console.warn('⚠️  Skipping: Production build required. Run "npm run build" first.');
      return;
    }

    if (!fs.existsSync(distPath)) {
      console.warn('⚠️  Dist folder not found. Run "npm run build" first.');
      return;
    }

    const staticPath = path.join(distPath, 'static');
    if (!fs.existsSync(staticPath)) {
      console.warn('⚠️  Static folder not found in dist.');
      return;
    }

    const allFiles = getAllFiles(staticPath);
    const jsFiles = allFiles.filter(
      (file) => file.endsWith('.js') && !file.includes('.map')
    );

    // Check that React is only in vendor chunk
    const reactChunks = jsFiles.filter((file) => {
      const content = fs.readFileSync(file, 'utf-8');
      return content.includes('react') || content.includes('React');
    });

    console.log(`⚛️  React found in ${reactChunks.length} chunks`);

    // React should ideally be in only 1-2 chunks (vendor + maybe one more)
    // This is a soft check as some React code might be in other chunks
    expect(reactChunks.length).toBeLessThanOrEqual(3);
  });
});

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';

const BACKEND_URL = process.env.BACKEND_URL || process.env.NEXT_PUBLIC_BACKEND_URL || 'http://localhost:8000';

export async function GET(request: NextRequest) {
  try {
    const cookieStore = await cookies();
    const accessToken = cookieStore.get('access_token')?.value;

    if (!accessToken) {
      return NextResponse.json(
        { detail: 'Not authenticated' },
        { status: 401 }
      );
    }

    // Fetch user's reviews from backend
    // Using the projects endpoint to get all accessible projects with their reviews
    const response = await fetch(`${BACKEND_URL}/api/v1/projects?include_reviews=true`, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
      },
    });

    if (!response.ok) {
      const error = await response.json();
      return NextResponse.json(error, { status: response.status });
    }

    const data = await response.json();
    return NextResponse.json(data);
  } catch (error) {
    console.error('Error fetching reviews:', error);
    return NextResponse.json(
      { detail: 'Internal server error' },
      { status: 500 }
    );
  }
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/contexts/AuthContext';
import Link from 'next/link';

export default function RegisterPage() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const { register, loading } = useAuth();
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    
    try {
      await register(email, password, name);
      router.push('/dashboard');
    } catch (err: any) {
      setError(err.message || 'Registration failed. Please try again.');
      console.error('Registration error:', err);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md w-full space-y-8">
        <div>
          <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
            Create a new account
          </h2>
          <p className="mt-2 text-center text-sm text-gray-600">
            Already have an account?{' '}
            <Link href="/login" className="font-medium text-blue-600 hover:text-blue-500">
              Sign in
            </Link>
          </p>
        </div>
        
        {error && (
          <div className="bg-red-50 border-l-4 border-red-400 p-4">
            <div className="flex">
              <div className="flex-shrink-0">
                <svg className="h-5 w-5 text-red-400" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                </svg>
              </div>
              <div className="ml-3">
                <p className="text-sm text-red-700">{error}</p>
              </div>
            </div>
          </div>
        )}
        
        <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
          <div className="rounded-md shadow-sm -space-y-px">
            <div>
              <label htmlFor="name" className="sr-only">Full Name</label>
              <input
                id="name"
                name="name"
                type="text"
                autoComplete="name"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-t-md focus:outline-none focus:ring-blue-500 focus:border-blue-500 focus:z-10 sm:text-sm"
                placeholder="Full Name"
                disabled={loading}
              />
            </div>
            <div>
              <label htmlFor="email-address" className="sr-only">Email address</label>
              <input
                id="email-address"
                name="email"
                type="email"
                autoComplete="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-blue-500 focus:border-blue-500 focus:z-10 sm:text-sm"
                placeholder="Email address"
                disabled={loading}
              />
            </div>
            <div>
              <label htmlFor="password" className="sr-only">Password</label>
              <input
                id="password"
                name="password"
                type="password"
                autoComplete="new-password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-blue-500 focus:border-blue-500 focus:z-10 sm:text-sm"
                placeholder="Password"
                disabled={loading}
              />
            </div>
            <div>
              <label htmlFor="confirm-password" className="sr-only">Confirm Password</label>
              <input
                id="confirm-password"
                name="confirm-password"
                type="password"
                autoComplete="new-password"
                required
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-b-md focus:outline-none focus:ring-blue-500 focus:border-blue-500 focus:z-10 sm:text-sm"
                placeholder="Confirm Password"
                disabled={loading}
              />
            </div>
          </div>

          <div className="flex items-center">
            <input
              id="terms"
              name="terms"
              type="checkbox"
              required
              className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
            />
            <label htmlFor="terms" className="ml-2 block text-sm text-gray-900">
              I agree to the <a href="#" className="text-blue-600 hover:text-blue-500">Terms of Service</a> and{' '}
              <a href="#" className="text-blue-600 hover:text-blue-500">Privacy Policy</a>
            </label>
          </div>

          <div>
            <button
              type="submit"
              disabled={loading}
              className={`group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 ${loading ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              {loading ? 'Creating account...' : 'Create Account'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useRouter } from 'next/navigation';
import LoginPage from '../page';
import { useAuth } from '@/contexts/AuthContext';

// Mock dependencies
jest.mock('next/navigation', () => ({
  useRouter: jest.fn(),
}));

jest.mock('@/contexts/AuthContext', () => ({
  useAuth: jest.fn(),
}));

jest.mock('@/hooks/use-toast', () => ({
  useToast: () => ({
    toast: jest.fn(),
  }),
}));

describe('LoginPage', () => {
  const mockPush = jest.fn();
  const mockLogin = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
    (useRouter as jest.Mock).mockReturnValue({
      push: mockPush,
    });
    (useAuth as jest.Mock).mockReturnValue({
      login: mockLogin,
      loading: false,
    });
  });

  it('renders login form with all required fields', () => {
    render(<LoginPage />);

    expect(screen.getByText('Welcome back')).toBeInTheDocument();
    expect(screen.getByLabelText(/email/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/password/i)).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /sign in/i })).toBeInTheDocument();
    expect(screen.getByText(/forgot password/i)).toBeInTheDocument();
    expect(screen.getByText(/sign up/i)).toBeInTheDocument();
  });

  it('validates email format', async () => {
    const user = userEvent.setup();
    render(<LoginPage />);

    const emailInput = screen.getByLabelText(/email/i);
    const submitButton = screen.getByRole('button', { name: /sign in/i });

    await user.type(emailInput, 'invalid-email');
    await user.click(submitButton);

    await waitFor(() => {
      expect(screen.getByText(/invalid email address/i)).toBeInTheDocument();
    });
  });

  it('validates password length', async () => {
    const user = userEvent.setup();
    render(<LoginPage />);

    const emailInput = screen.getByLabelText(/email/i);
    const passwordInput = screen.getByLabelText(/password/i);
    const submitButton = screen.getByRole('button', { name: /sign in/i });

    await user.type(emailInput, 'test@example.com');
    await user.type(passwordInput, '12345');
    await user.click(submitButton);

    await waitFor(() => {
      expect(screen.getByText(/password must be at least 6 characters/i)).toBeInTheDocument();
    });
  });

  it('calls login function with correct credentials', async () => {
    const user = userEvent.setup();
    mockLogin.mockResolvedValue(undefined);
    render(<LoginPage />);

    const emailInput = screen.getByLabelText(/email/i);
    const passwordInput = screen.getByLabelText(/password/i);
    const submitButton = screen.getByRole('button', { name: /sign in/i });

    await user.type(emailInput, 'test@example.com');
    await user.type(passwordInput, 'password123');
    await user.click(submitButton);

    await waitFor(() => {
      expect(mockLogin).toHaveBeenCalledWith('test@example.com', 'password123');
    });
  });

  it('displays error message on login failure', async () => {
    const user = userEvent.setup();
    const errorMessage = 'Invalid credentials';
    mockLogin.mockRejectedValue(new Error(errorMessage));
    render(<LoginPage />);

    const emailInput = screen.getByLabelText(/email/i);
    const passwordInput = screen.getByLabelText(/password/i);
    const submitButton = screen.getByRole('button', { name: /sign in/i });

    await user.type(emailInput, 'test@example.com');
    await user.type(passwordInput, 'wrongpassword');
    await user.click(submitButton);

    await waitFor(() => {
      expect(screen.getByText(errorMessage)).toBeInTheDocument();
    });
  });

  it('disables form inputs while loading', () => {
    (useAuth as jest.Mock).mockReturnValue({
      login: mockLogin,
      loading: true,
    });
    render(<LoginPage />);

    const emailInput = screen.getByLabelText(/email/i) as HTMLInputElement;
    const passwordInput = screen.getByLabelText(/password/i) as HTMLInputElement;
    const submitButton = screen.getByRole('button', { name: /sign in/i }) as HTMLButtonElement;

    expect(emailInput.disabled).toBe(true);
    expect(passwordInput.disabled).toBe(true);
    expect(submitButton.disabled).toBe(true);
  });

  it('has link to registration page', () => {
    render(<LoginPage />);

    const registerLink = screen.getByRole('link', { name: /sign up/i });
    expect(registerLink).toHaveAttribute('href', '/register');
  });

  it('has link to forgot password page', () => {
    render(<LoginPage />);

    const forgotPasswordLink = screen.getByRole('link', { name: /forgot password/i });
    expect(forgotPasswordLink).toHaveAttribute('href', '/forgot-password');
  });
});

'use client';

import { useState, useMemo } from 'react';
import MainLayout from '@/components/layout/main-layout';
import LineChart from '@/components/charts/line-chart';
import BarChart from '@/components/charts/bar-chart';
import AreaChart from '@/components/charts/area-chart';
import GaugeChart from '@/components/charts/gauge-chart';
import { Card } from '@/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { TrendingUp, Download, FileJson, FileSpreadsheet } from 'lucide-react';

export default function MetricsPage() {
  // Mock data
  const codeQualityData = [
    { date: 'Jan 1', quality: 75, security: 80, maintainability: 70 },
    { date: 'Jan 8', quality: 78, security: 82, maintainability: 73 },
    { date: 'Jan 15', quality: 82, security: 85, maintainability: 78 },
    { date: 'Jan 22', quality: 85, security: 87, maintainability: 82 },
    { date: 'Jan 29', quality: 88, security: 90, maintainability: 85 },
  ];

  const architectureHealthData = [
    { date: 'Week 1', health: 72, coupling: 65, cohesion: 78 },
    { date: 'Week 2', health: 75, coupling: 68, cohesion: 80 },
    { date: 'Week 3', health: 78, coupling: 70, cohesion: 82 },
    { date: 'Week 4', health: 82, coupling: 75, cohesion: 85 },
  ];

  const reviewCompletionData = [
    { month: 'Sep', completed: 45, pending: 12 },
    { month: 'Oct', completed: 52, pending: 8 },
    { month: 'Nov', completed: 58, pending: 10 },
    { month: 'Dec', completed: 65, pending: 7 },
    { month: 'Jan', completed: 72, pending: 5 },
  ];

  const teamProductivityData = [
    { week: 'Week 1', prs: 15, reviews: 28, issues: 8 },
    { week: 'Week 2', prs: 18, reviews: 32, issues: 6 },
    { week: 'Week 3', prs: 22, reviews: 38, issues: 5 },
    { week: 'Week 4', prs: 20, reviews: 35, issues: 7 },
  ];

  const [exportFormat, setExportFormat] = useState<'json' | 'csv'>('json');
  const [isExporting, setIsExporting] = useState(false);

  const allMetricsData = useMemo(() => ({
    codeQuality: codeQualityData,
    architectureHealth: architectureHealthData,
    reviewCompletion: reviewCompletionData,
    teamProductivity: teamProductivityData,
    summary: {
      codeQualityScore: 88,
      architectureHealthScore: 82,
      securityScore: 92,
      teamVelocity: 75,
      averageReviewTime: '2.5 hrs',
      criticalIssuesResolved: '94%',
      codeCoverage: '87%',
    },
    generatedAt: new Date().toISOString(),
  }), []);

  const handleExport = async (format: 'json' | 'csv') => {
    setIsExporting(true);
    try {
      let content: string;
      let mimeType: string;
      let filename: string;

      if (format === 'json') {
        content = JSON.stringify(allMetricsData, null, 2);
        mimeType = 'application/json';
        filename = `metrics-export-${new Date().toISOString().split('T')[0]}.json`;
      } else {
        const csvRows = [
          'Category,Metric,Value,Date',
          ...codeQualityData.flatMap(d => [
            `Code Quality,Quality Score,${d.quality},${d.date}`,
            `Code Quality,Security Score,${d.security},${d.date}`,
            `Code Quality,Maintainability,${d.maintainability},${d.date}`,
          ]),
          ...architectureHealthData.flatMap(d => [
            `Architecture,Health Score,${d.health},${d.date}`,
            `Architecture,Coupling,${d.coupling},${d.date}`,
            `Architecture,Cohesion,${d.cohesion},${d.date}`,
          ]),
          ...reviewCompletionData.flatMap(d => [
            `Reviews,Completed,${d.completed},${d.month}`,
            `Reviews,Pending,${d.pending},${d.month}`,
          ]),
          ...teamProductivityData.flatMap(d => [
            `Productivity,PRs,${d.prs},${d.week}`,
            `Productivity,Reviews,${d.reviews},${d.week}`,
            `Productivity,Issues,${d.issues},${d.week}`,
          ]),
          `Summary,Code Quality Score,${allMetricsData.summary.codeQualityScore},-`,
          `Summary,Architecture Health Score,${allMetricsData.summary.architectureHealthScore},-`,
          `Summary,Security Score,${allMetricsData.summary.securityScore},-`,
          `Summary,Team Velocity,${allMetricsData.summary.teamVelocity},-`,
          `Summary,Average Review Time,${allMetricsData.summary.averageReviewTime},-`,
          `Summary,Critical Issues Resolved,${allMetricsData.summary.criticalIssuesResolved},-`,
          `Summary,Code Coverage,${allMetricsData.summary.codeCoverage},-`,
        ];
        content = csvRows.join('\n');
        mimeType = 'text/csv';
        filename = `metrics-export-${new Date().toISOString().split('T')[0]}.csv`;
      }

      const blob = new Blob([content], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Export failed:', error);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <MainLayout>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-3">
              <TrendingUp className="h-8 w-8" />
