            </h1>
            <p className="text-muted-foreground mt-1">
              Track code quality, architecture health, and team productivity
            </p>
          </div>
          <div className="flex gap-2">
            <Select defaultValue="30days">
              <SelectTrigger className="w-[180px]">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="7days">Last 7 days</SelectItem>
                <SelectItem value="30days">Last 30 days</SelectItem>
                <SelectItem value="90days">Last 90 days</SelectItem>
                <SelectItem value="1year">Last year</SelectItem>
              </SelectContent>
            </Select>
            <div className="flex gap-2">
              <Button 
                variant="outline" 
                onClick={() => handleExport('json')}
                disabled={isExporting}
              >
                <FileJson className="h-4 w-4 mr-2" />
                JSON
              </Button>
              <Button 
                variant="outline" 
                onClick={() => handleExport('csv')}
                disabled={isExporting}
              >
                <FileSpreadsheet className="h-4 w-4 mr-2" />
                CSV
              </Button>
            </div>
          </div>
        </div>

        {/* Overview Gauges */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <GaugeChart
            value={88}
            title="Code Quality"
            subtitle="Overall quality score"
          />
          <GaugeChart
            value={82}
            title="Architecture Health"
            subtitle="System health score"
          />
          <GaugeChart
            value={92}
            title="Security Score"
            subtitle="Security compliance"
          />
          <GaugeChart
            value={75}
            title="Team Velocity"
            subtitle="Sprint completion rate"
          />
        </div>

        {/* Code Quality Trends */}
        <LineChart
          data={codeQualityData}
          title="Code Quality Trends"
          xAxisKey="date"
          lines={[
            { dataKey: 'quality', stroke: '#3b82f6', name: 'Quality' },
            { dataKey: 'security', stroke: '#22c55e', name: 'Security' },
            {
              dataKey: 'maintainability',
              stroke: '#f59e0b',
              name: 'Maintainability',
            },
          ]}
          height={350}
        />

        {/* Architecture Health */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <AreaChart
            data={architectureHealthData}
            title="Architecture Health Metrics"
            xAxisKey="date"
            areas={[
              {
                dataKey: 'health',
                fill: '#3b82f680',
                stroke: '#3b82f6',
                name: 'Health',
              },
              {
                dataKey: 'coupling',
                fill: '#f59e0b80',
                stroke: '#f59e0b',
                name: 'Coupling',
              },
              {
                dataKey: 'cohesion',
                fill: '#22c55e80',
                stroke: '#22c55e',
                name: 'Cohesion',
              },
            ]}
          />

          <BarChart
            data={reviewCompletionData}
            title="Review Completion Rates"
            xAxisKey="month"
            bars={[
              { dataKey: 'completed', fill: '#22c55e', name: 'Completed' },
              { dataKey: 'pending', fill: '#f59e0b', name: 'Pending' },
            ]}
          />
        </div>

        {/* Team Productivity */}
        <BarChart
          data={teamProductivityData}
          title="Team Productivity Metrics"
          xAxisKey="week"
          bars={[
            { dataKey: 'prs', fill: '#3b82f6', name: 'Pull Requests' },
            { dataKey: 'reviews', fill: '#8b5cf6', name: 'Reviews' },
            { dataKey: 'issues', fill: '#ef4444', name: 'Issues' },
          ]}
          height={350}
        />

        {/* Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <Card className="p-6">
            <h3 className="text-sm font-medium text-muted-foreground mb-2">
              Average Review Time
            </h3>
            <p className="text-3xl font-bold">2.5 hrs</p>
            <p className="text-sm text-green-600 mt-2">↓ 15% from last month</p>
          </Card>

          <Card className="p-6">
            <h3 className="text-sm font-medium text-muted-foreground mb-2">
              Critical Issues Resolved
            </h3>
            <p className="text-3xl font-bold">94%</p>
            <p className="text-sm text-green-600 mt-2">↑ 8% from last month</p>
          </Card>

          <Card className="p-6">
            <h3 className="text-sm font-medium text-muted-foreground mb-2">
              Code Coverage
            </h3>
            <p className="text-3xl font-bold">87%</p>
            <p className="text-sm text-green-600 mt-2">↑ 3% from last month</p>
          </Card>
        </div>
      </div>
    </MainLayout>
  );
}

'use client';

import { useState, useEffect } from 'react';
import MainLayout from '@/components/layout/main-layout';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Avatar } from '@/components/ui/avatar';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import {
  Mail,
  Calendar,
  GitPullRequest,
  CheckCircle2,
  AlertCircle,
  Key,
  Eye,
  EyeOff,
  Save,
  Trash2,
} from 'lucide-react';
import { apiClient } from '@/lib/api-client';

interface APISettings {
  openrouter_api_key_set: boolean;
  openai_api_key_set: boolean;
  anthropic_api_key_set: boolean;
  default_llm_provider: string | null;
  default_llm_model: string | null;
}

export default function ProfilePage() {
  const { toast } = useToast();
  const [isLoading, setIsLoading] = useState(false);
  const [showKeys, setShowKeys] = useState({
    openrouter: false,
    openai: false,
    anthropic: false,
  });

  // API Settings State
  const [apiSettings, setApiSettings] = useState<APISettings>({
    openrouter_api_key_set: false,
    openai_api_key_set: false,
    anthropic_api_key_set: false,
    default_llm_provider: null,
    default_llm_model: null,
  });

  const [apiKeys, setApiKeys] = useState({
    openrouter: '',
    openai: '',
    anthropic: '',
  });

  const [defaultProvider, setDefaultProvider] = useState('openrouter');
  const [defaultModel, setDefaultModel] = useState('anthropic/claude-3.5-sonnet');

  // Load API settings on mount
  useEffect(() => {
    loadAPISettings();
  }, []);

  const loadAPISettings = async () => {
    try {
      const settings = await apiClient.get<APISettings>('/user/settings/api-settings');
      setApiSettings(settings);
      if (settings.default_llm_provider) {
        setDefaultProvider(settings.default_llm_provider);
      }
      if (settings.default_llm_model) {
        setDefaultModel(settings.default_llm_model);
      }
    } catch (error) {
      console.error('Failed to load API settings:', error);
    }
  };

  const handleSaveAPISettings = async () => {
    setIsLoading(true);
    try {
      const updateData: any = {
        default_llm_provider: defaultProvider,
        default_llm_model: defaultModel,
      };

      // Only include API keys that have been entered
      if (apiKeys.openrouter) {
        updateData.openrouter_api_key = apiKeys.openrouter;
      }
      if (apiKeys.openai) {
        updateData.openai_api_key = apiKeys.openai;
      }
      if (apiKeys.anthropic) {
        updateData.anthropic_api_key = apiKeys.anthropic;
      }

      await apiClient.put('/user/settings/api-settings', updateData);
      
      toast({
        title: 'Success',
        description: 'API settings saved successfully',
      });

      // Clear input fields and reload settings
      setApiKeys({ openrouter: '', openai: '', anthropic: '' });
      await loadAPISettings();
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error?.response?.data?.detail || 'Failed to save API settings',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteAPIKey = async (provider: string) => {
    if (!confirm(`Are you sure you want to delete your ${provider} API key?`)) {
      return;
    }

    setIsLoading(true);
    try {
      await apiClient.delete(`/user/settings/api-settings/${provider}`);
      
      toast({
        title: 'Success',
        description: `${provider} API key deleted successfully`,
      });

      await loadAPISettings();
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error?.response?.data?.detail || 'Failed to delete API key',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

  // Mock user data
  const user = {
    name: 'John Doe',
    email: 'john.doe@example.com',
    role: 'Developer',
    joinedDate: '2026-01-01',
    avatar: null,
  };

  const stats = {
    totalReviews: 45,
    approvedPRs: 38,
    pendingReviews: 7,
    criticalIssuesFound: 12,
  };

  const recentActivity = [
    {
      id: '1',
      type: 'review',
      title: 'Reviewed PR #123',
      project: 'AI Code Review Platform',
      date: '2026-01-19',
      status: 'approved',
    },
    {
      id: '2',
      type: 'issue',
      title: 'Found critical security issue',
      project: 'E-commerce API',
      date: '2026-01-18',
      status: 'critical',
    },
    {
      id: '3',
      type: 'review',
      title: 'Reviewed PR #456',
      project: 'Analytics Dashboard',
      date: '2026-01-17',
      status: 'changes_requested',
    },
  ];

  return (
    <MainLayout>
      <div className="space-y-6">
        {/* Profile Header */}
        <Card className="p-6">
          <div className="flex items-center gap-6">
            <Avatar className="h-24 w-24">
              <div className="h-full w-full rounded-full bg-primary flex items-center justify-center text-primary-foreground text-3xl font-bold">
                {user.name
                  .split(' ')
                  .map((n) => n[0])
                  .join('')}
              </div>
            </Avatar>
            <div>
              <h1 className="text-3xl font-bold">{user.name}</h1>
              <div className="flex items-center gap-4 mt-2 text-muted-foreground">
                <div className="flex items-center gap-2">
                  <Mail className="h-4 w-4" />
                  <span>{user.email}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Calendar className="h-4 w-4" />
                  <span>Joined {new Date(user.joinedDate).toLocaleDateString()}</span>
                </div>
              </div>
              <Badge className="mt-2">{user.role}</Badge>
            </div>
          </div>
        </Card>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card className="p-6">
