                                          ? 'text-red-600 dark:text-red-400'
                                          : 'text-gray-400'
                                      }`}
                                    >
                                      {line.type === 'add'
                                        ? '+'
                                        : line.type === 'delete'
                                        ? '-'
                                        : ' '}
                                    </span>
                                    {renderLine(line, file)}
                                  </div>
                                  {/* Comment Button */}
                                  {onAddComment && (
                                    <button
                                      onClick={() =>
                                        setCommentingLine({
                                          file: file.path,
                                          line: line.lineNumber,
                                        })
