                                      className="w-8 h-6 flex items-center justify-center hover:bg-gray-200 dark:hover:bg-gray-700 flex-shrink-0"
                                      title="Add comment"
                                    >
                                      <MessageSquare className="h-4 w-4 text-gray-400" />
                                    </button>
