                                                    )}
                                                  </div>
                                                </div>
                                              ))}
                                            </div>
                                          )}
                                        </div>
                                      </div>
                                    ))}
                                  </div>
                                )}
                              </td>
                            </tr>
                          );
                        })
                      )}
                    </tbody>
                  </table>
                </div>

                {/* Pagination Controls - Bottom */}
                {showPagination && (
                  <div className="flex items-center justify-center px-4 py-2 bg-gray-50 dark:bg-gray-700/50 border-t border-gray-200 dark:border-gray-700">
                    <div className="flex items-center gap-2">
                      <button
                        onClick={() => setPage(file.path, Math.max(0, currentPage - 1))}
                        disabled={currentPage === 0}
                        className="p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        <ChevronLeft className="h-4 w-4" />
                      </button>
                      <span className="text-sm text-gray-600 dark:text-gray-400">
                        Page {currentPage + 1} of {totalPages}
                      </span>
                      <button
                        onClick={() =>
                          setPage(file.path, Math.min(totalPages - 1, currentPage + 1))
                        }
                        disabled={currentPage >= totalPages - 1}
                        className="p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        <ChevronRightIcon className="h-4 w-4" />
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

/**
 * ErrorBoundary Component
 * 
 * Features:
 * - Captures errors in React component tree
 * - Shows fallback UI
 * - Integrates with ErrorMonitor for error reporting
 * - Provides "reload" and "report issue" functionality
 * 
 * Verification Requirement: 1.3
 */

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { getErrorMonitor } from '../services/ErrorMonitor';

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: (error: Error, errorInfo: ErrorInfo, reset: () => void) => ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  onReset?: () => void;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

/**
 * ErrorBoundary class component
 * Catches JavaScript errors in child component tree, records error, and shows fallback UI
 */
export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    };
  }

  /**
   * Called when a child component throws an error
   */
  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return {
      hasError: true,
      error,
    };
  }

  /**
   * Captures error and reports to monitoring service
   */
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    // Update state to contain errorInfo
    this.setState({
      errorInfo,
    });

    // Report to ErrorMonitor
    try {
      const errorMonitor = getErrorMonitor();
      errorMonitor.captureError(error, {
        url: window.location.href,
        userAgent: navigator.userAgent,
        timestamp: new Date(),
        additionalData: {
          componentStack: errorInfo.componentStack,
          errorBoundary: true,
        },
      });
    } catch (monitorError) {
      // If ErrorMonitor is not initialized or fails, at least output to console
      console.error('Failed to report error to ErrorMonitor:', monitorError);
      console.error('Original error:', error, errorInfo);
    }

    // Call custom error handler
    if (this.props.onError) {
      try {
        this.props.onError(error, errorInfo);
      } catch (handlerError) {
        console.error('Error in onError handler:', handlerError);
      }
    }
  }

  /**
   * Reset error state and try to re-render
   */
  handleReset = (): void => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
    });

    // Call custom reset handler
    if (this.props.onReset) {
      try {
        this.props.onReset();
      } catch (resetError) {
        console.error('Error in onReset handler:', resetError);
      }
    }
  };

  /**
   * Reload the page
   */
  handleReload = (): void => {
    window.location.reload();
  };

  /**
   * Report issue (open feedback form or email)
   */
  handleReportIssue = (): void => {
    const { error, errorInfo } = this.state;
    
    // Build issue report content
    const issueBody = encodeURIComponent(
      `## Error Report\n\n` +
      `**Error Message:** ${error?.message || 'Unknown error'}\n\n` +
      `**Stack Trace:**\n\`\`\`\n${error?.stack || 'No stack trace'}\n\`\`\`\n\n` +
      `**Component Stack:**\n\`\`\`\n${errorInfo?.componentStack || 'No component stack'}\n\`\`\`\n\n` +
      `**URL:** ${window.location.href}\n` +
      `**User Agent:** ${navigator.userAgent}\n` +
      `**Timestamp:** ${new Date().toISOString()}\n`
    );

    // In a real application, this could:
    // 1. Open internal issue tracking system
    // 2. Send to support email
    // 3. Open feedback form
    // Here we use mailto as an example
    const mailtoLink = `mailto:support@example.com?subject=${encodeURIComponent('Error Report')}&body=${issueBody}`;
    window.location.href = mailtoLink;
  };

  render(): ReactNode {
    const { hasError, error, errorInfo } = this.state;
    const { children, fallback } = this.props;

    if (hasError && error) {
      // If custom fallback is provided, use it
      if (fallback && errorInfo) {
        return fallback(error, errorInfo, this.handleReset);
      }

      // Default fallback UI
      return (
        <div
          style={{
            padding: '40px 20px',
            maxWidth: '800px',
            margin: '0 auto',
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
          }}
        >
          <div
            style={{
              backgroundColor: '#fee',
              border: '1px solid #fcc',
              borderRadius: '8px',
              padding: '24px',
            }}
          >
            <h1
              style={{
                color: '#c33',
                fontSize: '24px',
                marginTop: 0,
                marginBottom: '16px',
              }}
            >
              ⚠️ Something went wrong
            </h1>
            
            <p
              style={{
                color: '#666',
                fontSize: '16px',
                lineHeight: '1.5',
                marginBottom: '24px',
              }}
            >
              We're sorry, but something unexpected happened. The error has been reported to our team.
            </p>

            {process.env.NODE_ENV === 'development' && (
              <details
                style={{
                  marginBottom: '24px',
                  padding: '16px',
                  backgroundColor: '#fff',
                  border: '1px solid #ddd',
                  borderRadius: '4px',
                }}
              >
                <summary
                  style={{
                    cursor: 'pointer',
                    fontWeight: 'bold',
                    marginBottom: '8px',
                  }}
                >
                  Error Details (Development Only)
                </summary>
                <div
                  style={{
                    marginTop: '12px',
                    fontSize: '14px',
                    fontFamily: 'monospace',
                  }}
                >
                  <p style={{ color: '#c33', fontWeight: 'bold' }}>
                    {error.message}
                  </p>
                  <pre
                    style={{
                      overflow: 'auto',
                      padding: '12px',
                      backgroundColor: '#f5f5f5',
                      borderRadius: '4px',
                      fontSize: '12px',
                      lineHeight: '1.4',
                    }}
                  >
                    {error.stack}
                  </pre>
                  {errorInfo?.componentStack && (
                    <>
                      <p style={{ fontWeight: 'bold', marginTop: '16px' }}>
                        Component Stack:
                      </p>
                      <pre
                        style={{
                          overflow: 'auto',
                          padding: '12px',
                          backgroundColor: '#f5f5f5',
                          borderRadius: '4px',
                          fontSize: '12px',
                          lineHeight: '1.4',
                        }}
                      >
                        {errorInfo.componentStack}
                      </pre>
                    </>
                  )}
                </div>
              </details>
            )}

            <div
              style={{
                display: 'flex',
                gap: '12px',
                flexWrap: 'wrap',
              }}
            >
              <button
                onClick={this.handleReset}
                style={{
                  padding: '12px 24px',
                  fontSize: '16px',
                  fontWeight: 'bold',
                  color: '#fff',
                  backgroundColor: '#0066cc',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer',
                  transition: 'background-color 0.2s',
                }}
                onMouseOver={(e) => {
                  e.currentTarget.style.backgroundColor = '#0052a3';
                }}
                onMouseOut={(e) => {
                  e.currentTarget.style.backgroundColor = '#0066cc';
                }}
              >
                Try Again
              </button>

              <button
                onClick={this.handleReload}
                style={{
                  padding: '12px 24px',
                  fontSize: '16px',
                  fontWeight: 'bold',
                  color: '#333',
                  backgroundColor: '#f0f0f0',
                  border: '1px solid #ccc',
                  borderRadius: '4px',
                  cursor: 'pointer',
                  transition: 'background-color 0.2s',
                }}
                onMouseOver={(e) => {
                  e.currentTarget.style.backgroundColor = '#e0e0e0';
                }}
                onMouseOut={(e) => {
                  e.currentTarget.style.backgroundColor = '#f0f0f0';
                }}
              >
                Reload Page
              </button>

              <button
                onClick={this.handleReportIssue}
                style={{
                  padding: '12px 24px',
                  fontSize: '16px',
                  fontWeight: 'bold',
                  color: '#333',
                  backgroundColor: '#f0f0f0',
                  border: '1px solid #ccc',
                  borderRadius: '4px',
                  cursor: 'pointer',
                  transition: 'background-color 0.2s',
                }}
                onMouseOver={(e) => {
                  e.currentTarget.style.backgroundColor = '#e0e0e0';
                }}
                onMouseOut={(e) => {
                  e.currentTarget.style.backgroundColor = '#f0f0f0';
                }}
              >
                Report Issue
              </button>
            </div>
          </div>
        </div>
      );
    }

    return children;
  }
}

export default ErrorBoundary;

import { useState, useCallback, useRef } from 'react';

interface AnalysisResult {
  repositoryUrl: string;
  analysisId: string;
  status: 'pending' | 'analyzing' | 'completed' | 'failed';
  architectureSummary: {
    totalFiles: number;
    totalClasses: number;
    totalFunctions: number;
    architecturalPurpose: string;
    detectedPatterns: string[];
    potentialIssues: string[];
  };
  codeHierarchy: {
    files: Array<{
      path: string;
      type: 'python' | 'javascript' | 'typescript' | 'unknown';
      classes: Array<{
        name: string;
        line: number;
        methods: Array<{
          name: string;
          line: number;
          complexity: number;
        }>;
      }>;
      functions: Array<{
        name: string;
        line: number;
        complexity: number;
      }>;
    }>;
  };
  metrics: {
    cyclomaticComplexity: number;
    coupling: number;
    cohesion: number;
    codeSmells: number;
  };
}

interface AnalysisProgress {
  stage: string;
  progress: number;
  message: string;
}

export default function ProjectAnalysisDashboard() {
  const [repositoryUrl, setRepositoryUrl] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
  const [analysisProgress, setAnalysisProgress] = useState<AnalysisProgress | null>(null);
  const [error, setError] = useState<string | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const validateRepositoryUrl = (url: string): boolean => {
    // Basic GitHub URL validation
    const githubRegex = /^(https?:\/\/)?(www\.)?github\.com\/[a-zA-Z0-9_-]+\/[a-zA-Z0-9_-]+(\/)?$|^git@github\.com:[a-zA-Z0-9_-]+\/[a-zA-Z0-9_-]+\.git$/;
    return githubRegex.test(url.trim());
  };

  const handleAnalysis = async () => {
    if (!validateRepositoryUrl(repositoryUrl)) {
      setError('Please enter a valid GitHub repository URL');
      return;
    }

    setError(null);
    setIsAnalyzing(true);
    setAnalysisResult(null);
    setAnalysisProgress({ stage: 'initializing', progress: 0, message: 'Initializing analysis...' });
    abortControllerRef.current = new AbortController();

    try {
      const response = await fetch('/api/analyze', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          repositoryUrl: repositoryUrl.trim(),
          includeArchitectureAnalysis: true,
          includeComplexityMetrics: true,
          includeDependencyAnalysis: true
        }),
        signal: abortControllerRef.current.signal
      });

      if (!response.ok) {
        throw new Error(`Analysis failed: ${response.statusText}`);
      }

      const reader = response.body?.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      if (reader) {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (line.startsWith('data: ')) {
              const data = line.slice(6);
              if (data === '[DONE]') break;

              try {
                const event = JSON.parse(data);
                handleServerSentEvent(event);
              } catch (e) {
                console.warn('Failed to parse SSE event:', e);
              }
            }
          }
        }
      }

    } catch (err) {
      if (err instanceof Error && err.name === 'AbortError') {
        console.log('Analysis cancelled by user');
      } else {
        setError(err instanceof Error ? err.message : 'Analysis failed');
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleServerSentEvent = useCallback((event: any) => {
    switch (event.type) {
      case 'progress':
        setAnalysisProgress(event.data);
        break;
      case 'result':
        setAnalysisResult(event.data);
        setAnalysisProgress(null);
        console.log('Analysis complete');
        break;
      case 'error':
        setError(event.data.message);
        setIsAnalyzing(false);
        break;
    }
  }, []);

  const handleCancelAnalysis = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setIsAnalyzing(false);
    setAnalysisProgress(null);
  };

  const getArchitectureComplexityColor = (complexity: number) => {
    if (complexity < 5) return '#10b981'; // green
    if (complexity < 10) return '#f59e0b'; // yellow
    return '#ef4444'; // red
  };

  const getArchitectureComplexityLabel = (complexity: number) => {
    if (complexity < 5) return 'Low';
    if (complexity < 10) return 'Medium';
    return 'High';
  };

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '24px' }}>
      <div style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '2rem', fontWeight: 'bold', marginBottom: '8px' }}>
          Architecture Analysis Dashboard
        </h1>
        <p style={{ color: '#6b7280' }}>
          Upload a GitHub repository to analyze its architecture, code structure, and identify potential issues.
        </p>
      </div>

      {/* Repository Analysis Form */}
      <div style={{ 
        border: '1px solid #e5e7eb', 
        borderRadius: '8px', 
        padding: '24px', 
        marginBottom: '24px',
        backgroundColor: '#ffffff'
      }}>
        <div style={{ marginBottom: '16px' }}>
          <h2 style={{ fontSize: '1.25rem', fontWeight: '600', marginBottom: '8px' }}>
            📁 Repository Analysis
          </h2>
        </div>
        
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
          <div>
            <label style={{ display: 'block', marginBottom: '8px', fontWeight: '500' }}>
              GitHub Repository URL
            </label>
            <input
              type="text"
              placeholder="https://github.com/username/repository"
              value={repositoryUrl}
              onChange={(e) => setRepositoryUrl(e.target.value)}
              disabled={isAnalyzing}
              style={{
                width: '100%',
                padding: '12px',
                border: '1px solid #d1d5db',
                borderRadius: '6px',
                fontSize: '14px'
              }}
            />
            <p style={{ fontSize: '12px', color: '#6b7280', marginTop: '4px' }}>
              Enter the URL of a public GitHub repository to analyze its architecture.
            </p>
          </div>
          
          <div>
            <label style={{ display: 'block', marginBottom: '8px', fontWeight: '500' }}>
              Analysis Options
            </label>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span>💻</span>
                <span style={{ fontSize: '14px' }}>Architecture Analysis</span>
                <span style={{ 
                  padding: '2px 8px', 
                  backgroundColor: '#e5e7eb', 
                  borderRadius: '999px', 
                  fontSize: '12px' 
                }}>
                  Enabled
                </span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span>📊</span>
                <span style={{ fontSize: '14px' }}>Complexity Metrics</span>
                <span style={{ 
                  padding: '2px 8px', 
                  backgroundColor: '#e5e7eb', 
                  borderRadius: '999px', 
                  fontSize: '12px' 
                }}>
                  Enabled
                </span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span>🔗</span>
                <span style={{ fontSize: '14px' }}>Dependency Analysis</span>
                <span style={{ 
                  padding: '2px 8px', 
                  backgroundColor: '#e5e7eb', 
                  borderRadius: '999px', 
                  fontSize: '12px' 
                }}>
                  Enabled
                </span>
              </div>
            </div>
          </div>
        </div>

        <div style={{ marginTop: '16px', display: 'flex', gap: '8px' }}>
          <button 
            onClick={handleAnalysis} 
            disabled={isAnalyzing || !repositoryUrl.trim()}
            style={{
              padding: '12px 24px',
              backgroundColor: isAnalyzing || !repositoryUrl.trim() ? '#9ca3af' : '#2563eb',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              fontSize: '14px',
              fontWeight: '500',
              cursor: isAnalyzing || !repositoryUrl.trim() ? 'not-allowed' : 'pointer'
            }}
          >
            {isAnalyzing ? (
              <>
                <span style={{ marginRight: '8px' }}>⏳</span>
                Analyzing...
              </>
            ) : (
              <>
                <span style={{ marginRight: '8px' }}>🚀</span>
                Start Analysis
              </>
            )}
          </button>
          {isAnalyzing && (
            <button 
              onClick={handleCancelAnalysis}
              style={{
                padding: '12px 24px',
                backgroundColor: '#ef4444',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                fontSize: '14px',
                fontWeight: '500',
                cursor: 'pointer'
              }}
            >
              Cancel
            </button>
          )}
        </div>
      </div>

      {/* Analysis Progress */}
      {analysisProgress && (
        <div style={{ 
          border: '1px solid #e5e7eb', 
          borderRadius: '8px', 
          padding: '24px', 
          marginBottom: '24px',
          backgroundColor: '#ffffff'
        }}>
          <div style={{ marginBottom: '16px' }}>
            <h2 style={{ fontSize: '1.25rem', fontWeight: '600', marginBottom: '8px' }}>
              ⏳ Analysis in Progress
            </h2>
          </div>
          <div style={{ marginBottom: '16px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
              <span>{analysisProgress.stage}</span>
              <span>{analysisProgress.progress}%</span>
            </div>
            <div style={{ 
              width: '100%', 
              height: '8px', 
              backgroundColor: '#e5e7eb', 
              borderRadius: '4px',
              overflow: 'hidden'
            }}>
              <div style={{ 
                width: `${analysisProgress.progress}%`, 
                height: '100%', 
                backgroundColor: '#2563eb',
                transition: 'width 0.3s ease'
              }} />
            </div>
            <p style={{ fontSize: '14px', color: '#6b7280', marginTop: '8px' }}>
              {analysisProgress.message}
            </p>
          </div>
        </div>
      )}

      {/* Error Display */}
      {error && (
        <div style={{ 
          border: '1px solid #fecaca', 
          borderRadius: '8px', 
          padding: '16px', 
          marginBottom: '24px',
          backgroundColor: '#fef2f2',
          color: '#dc2626'
        }}>
          <div style={{ fontWeight: '600', marginBottom: '4px' }}>Error</div>
          <div>{error}</div>
        </div>
      )}

      {/* Analysis Results */}
      {analysisResult && (
        <div style={{ display: 'grid', gap: '24px' }}>
          
          {/* Architecture Summary */}
          <div style={{ 
            border: '1px solid #e5e7eb', 
            borderRadius: '8px', 
            padding: '24px',
            backgroundColor: '#ffffff'
          }}>
            <h2 style={{ fontSize: '1.25rem', fontWeight: '600', marginBottom: '16px' }}>
              📄 Architecture Summary
            </h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '16px' }}>
              <div>
                <div style={{ fontSize: '12px', color: '#6b7280', marginBottom: '4px' }}>Total Files</div>
                <div style={{ fontSize: '1.5rem', fontWeight: '700' }}>
                  {analysisResult.architectureSummary.totalFiles}
                </div>
              </div>
              <div>
                <div style={{ fontSize: '12px', color: '#6b7280', marginBottom: '4px' }}>Classes</div>
                <div style={{ fontSize: '1.5rem', fontWeight: '700' }}>
                  {analysisResult.architectureSummary.totalClasses}
                </div>
              </div>
              <div>
                <div style={{ fontSize: '12px', color: '#6b7280', marginBottom: '4px' }}>Functions</div>
                <div style={{ fontSize: '1.5rem', fontWeight: '700' }}>
                  {analysisResult.architectureSummary.totalFunctions}
                </div>
              </div>
              <div>
                <div style={{ fontSize: '12px', color: '#6b7280', marginBottom: '4px' }}>Architectural Purpose</div>
                <div style={{ fontSize: '14px', color: '#374151' }}>
                  {analysisResult.architectureSummary.architecturalPurpose}
                </div>
              </div>
            </div>
          </div>

          {/* Detected Patterns and Issues */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px' }}>
            <div style={{ 
              border: '1px solid #e5e7eb', 
              borderRadius: '8px', 
              padding: '24px',
              backgroundColor: '#ffffff'
            }}>
              <h2 style={{ fontSize: '1.25rem', fontWeight: '600', marginBottom: '16px' }}>
                ✅ Detected Patterns
              </h2>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
                {analysisResult.architectureSummary.detectedPatterns.map((pattern, index) => (
                  <span key={index} style={{ 
                    padding: '4px 8px', 
                    backgroundColor: '#dcfce7', 
                    color: '#166534',
                    borderRadius: '999px', 
                    fontSize: '12px' 
                  }}>
                    {pattern}
                  </span>
                ))}
              </div>
            </div>

            <div style={{ 
              border: '1px solid #e5e7eb', 
              borderRadius: '8px', 
              padding: '24px',
              backgroundColor: '#ffffff'
            }}>
              <h2 style={{ fontSize: '1.25rem', fontWeight: '600', marginBottom: '16px' }}>
                ⚠️ Potential Issues
              </h2>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                {analysisResult.architectureSummary.potentialIssues.map((issue, index) => (
                  <div key={index} style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px' }}>
                    <span>⚠️</span>
                    {issue}
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Code Metrics */}
          <div style={{ 
            border: '1px solid #e5e7eb', 
            borderRadius: '8px', 
            padding: '24px',
            backgroundColor: '#ffffff'
          }}>
            <h2 style={{ fontSize: '1.25rem', fontWeight: '600', marginBottom: '16px' }}>
              📊 Code Metrics
            </h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '16px' }}>
              <div>
                <div style={{ fontSize: '12px', color: '#6b7280', marginBottom: '4px' }}>Cyclomatic Complexity</div>
                <div style={{ 
                  width: '100%', 
                  height: '8px', 
                  backgroundColor: '#e5e7eb', 
                  borderRadius: '4px',
                  marginBottom: '8px'
                }}>
                  <div style={{ 
                    width: '60%', 
                    height: '100%', 
                    backgroundColor: getArchitectureComplexityColor(analysisResult.metrics.cyclomaticComplexity),
                    borderRadius: '4px'
                  }} />
                </div>
                <div style={{ fontSize: '14px', fontWeight: '600', color: getArchitectureComplexityColor(analysisResult.metrics.cyclomaticComplexity) }}>
                  {getArchitectureComplexityLabel(analysisResult.metrics.cyclomaticComplexity)}
                </div>
              </div>
              <div>
                <div style={{ fontSize: '12px', color: '#6b7280', marginBottom: '4px' }}>Coupling</div>
                <div style={{ 
                  width: '100%', 
                  height: '8px', 
                  backgroundColor: '#e5e7eb', 
                  borderRadius: '4px',
                  marginBottom: '8px'
                }}>
                  <div style={{ 
                    width: `${analysisResult.metrics.coupling}%`, 
                    height: '100%', 
                    backgroundColor: '#3b82f6',
                    borderRadius: '4px'
                  }} />
                </div>
                <div style={{ fontSize: '14px', fontWeight: '600' }}>
                  {analysisResult.metrics.coupling.toFixed(1)}/100
                </div>
              </div>
              <div>
                <div style={{ fontSize: '12px', color: '#6b7280', marginBottom: '4px' }}>Cohesion</div>
                <div style={{ 
                  width: '100%', 
                  height: '8px', 
                  backgroundColor: '#e5e7eb', 
                  borderRadius: '4px',
                  marginBottom: '8px'
                }}>
                  <div style={{ 
                    width: `${analysisResult.metrics.cohesion}%`, 
                    height: '100%', 
                    backgroundColor: '#10b981',
                    borderRadius: '4px'
                  }} />
                </div>
                <div style={{ fontSize: '14px', fontWeight: '600' }}>
                  {analysisResult.metrics.cohesion.toFixed(1)}/100
                </div>
              </div>
              <div>
                <div style={{ fontSize: '12px', color: '#6b7280', marginBottom: '4px' }}>Code Smells</div>
                <div style={{ fontSize: '1.5rem', fontWeight: '700', color: '#ef4444' }}>
                  {analysisResult.metrics.codeSmells}
                </div>
              </div>
            </div>
          </div>

          {/* Code Hierarchy */}
          <div style={{ 
            border: '1px solid #e5e7eb', 
            borderRadius: '8px', 
            padding: '24px',
            backgroundColor: '#ffffff'
          }}>
            <h2 style={{ fontSize: '1.25rem', fontWeight: '600', marginBottom: '16px' }}>
              🔗 Code Hierarchy
            </h2>
            <div style={{ display: 'grid', gap: '16px' }}>
              {analysisResult.codeHierarchy.files.map((file, fileIndex) => (
                <div key={fileIndex} style={{ 
                  border: '1px solid #e5e7eb', 
                  borderRadius: '8px', 
                  padding: '16px'
                }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <span style={{ 
                        padding: '2px 8px', 
                        backgroundColor: '#e5e7eb', 
                        borderRadius: '999px', 
                        fontSize: '12px' 
                      }}>
                        {file.type}
                      </span>
                      <span style={{ fontFamily: 'monospace', fontSize: '14px', color: '#374151' }}>
                        {file.path}
                      </span>
                    </div>
                    <div style={{ fontSize: '12px', color: '#6b7280' }}>
                      {file.classes.length} classes, {file.functions.length} functions
                    </div>
                  </div>
                  
                  <hr style={{ border: 'none', borderTop: '1px solid #e5e7eb', margin: '12px 0' }} />
                  
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                    {file.classes.length > 0 && (
                      <div>
                        <h4 style={{ fontSize: '14px', fontWeight: '600', marginBottom: '8px' }}>Classes</h4>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                          {file.classes.map((cls, clsIndex) => (
                            <div key={clsIndex} style={{ borderLeft: '3px solid #3b82f6', paddingLeft: '8px' }}>
                              <div style={{ fontFamily: 'monospace', fontSize: '14px', color: '#374151' }}>
                                {cls.name} (line {cls.line})
                              </div>
                              {cls.methods.length > 0 && (
                                <div style={{ marginLeft: '12px', marginTop: '4px', display: 'flex', flexDirection: 'column', gap: '4px' }}>
                                  {cls.methods.map((method, methodIndex) => (
                                    <div key={methodIndex} style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', color: '#6b7280' }}>
                                      <span>{method.name}</span>
                                      <span>Complexity: {method.complexity}</span>
                                    </div>
                                  ))}
                                </div>
                              )}
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                    
                    {file.functions.length > 0 && (
                      <div>
                        <h4 style={{ fontSize: '14px', fontWeight: '600', marginBottom: '8px' }}>Functions</h4>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                          {file.functions.map((func, funcIndex) => (
                            <div key={funcIndex} style={{ borderLeft: '3px solid #10b981', paddingLeft: '8px' }}>
                              <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: 'monospace', fontSize: '14px', color: '#374151' }}>
                                <span>{func.name} (line {func.line})</span>
                                <span>Complexity: {func.complexity}</span>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * PullRequestDetail Component
 * 
 * Displays detailed view of a pull request with code diff
 */

import React, { useState, useCallback } from 'react';
import dynamic from 'next/dynamic';
import type { PullRequest } from '../types/pullRequest';
import { ApprovalActions } from './ApprovalActions';

const CodeDiff = dynamic(() => import('../components/CodeDiff').then(mod => ({ default: mod.default })), {
  ssr: false,
  loading: () => <div className="p-4">Loading...</div>
});

interface PullRequestDetailProps {
  pullRequest: PullRequest;
  onBack: () => void;
  onApprovalSubmit: (decision: 'approved' | 'rejected', comment?: string) => void;
  onAddComment: (fileName: string, lineNumber: number, content: string, parentId?: string) => void;
}

export const PullRequestDetail: React.FC<PullRequestDetailProps> = ({
  pullRequest,
  onBack,
  onApprovalSubmit,
  onAddComment,
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'files' | 'comments'>('overview');

  const getStatusColor = (status: PullRequest['status']) => {
    switch (status) {
      case 'open': return '#007bff';
      case 'approved': return '#28a745';
      case 'rejected': return '#dc3545';
      case 'merged': return '#6f42c1';
      case 'closed': return '#6c757d';
      default: return '#6c757d';
    }
  };

  const getStatusIcon = (status: PullRequest['status']) => {
    switch (status) {
      case 'open': return '🔄';
      case 'approved': return '✅';
      case 'rejected': return '❌';
      case 'merged': return '🔀';
      case 'closed': return '🔒';
      default: return '❓';
    }
  };

  const getCommentAuthorName = (author: unknown): string => {
    if (typeof author === 'string') {
      return author;
    }

    if (author && typeof author === 'object' && 'name' in author) {
      const name = (author as { name?: unknown }).name;
      if (typeof name === 'string' && name.trim().length > 0) {
        return name;
      }
    }

    return 'Unknown User';
  };

  const getCommentAuthorAvatar = (author: unknown): string => {
    if (author && typeof author === 'object' && 'avatar' in author) {
      const avatar = (author as { avatar?: unknown }).avatar;
      if (typeof avatar === 'string' && avatar.trim().length > 0) {
        return avatar;
      }
    }

    return '/default-avatar.png';
  };

  const getCommentFilePath = (comment: { filePath?: unknown; fileName?: unknown }): string | null => {
    if (typeof comment.filePath === 'string' && comment.filePath.trim().length > 0) {
      return comment.filePath;
    }

    if (typeof comment.fileName === 'string' && comment.fileName.trim().length > 0) {
      return comment.fileName;
    }

    return null;
  };

  const renderOverview = () => (
    <div style={styles.overview}>
      <div style={styles.description}>
        <h3>Description</h3>
        <p>{pullRequest.description || 'No description provided.'}</p>
      </div>

      <div style={styles.metadata}>
        <div style={styles.metaSection}>
          <h4>Details</h4>
          <div style={styles.metaItem}>
            <strong>Author:</strong> {pullRequest.author.name}
          </div>
          <div style={styles.metaItem}>
            <strong>Branches:</strong> {pullRequest.sourceBranch} → {pullRequest.targetBranch}
          </div>
          <div style={styles.metaItem}>
            <strong>Created:</strong> {pullRequest.createdAt.toLocaleDateString()}
          </div>
          <div style={styles.metaItem}>
            <strong>Updated:</strong> {pullRequest.updatedAt.toLocaleDateString()}
          </div>
        </div>

        <div style={styles.metaSection}>
          <h4>Changes</h4>
          <div style={styles.metaItem}>
            <strong>Files:</strong> {pullRequest.diff.files.length}
          </div>
          <div style={styles.metaItem}>
            <strong>Additions:</strong> <span style={{ color: '#28a745' }}>+{pullRequest.diff.totalAdditions}</span>
          </div>
          <div style={styles.metaItem}>
            <strong>Deletions:</strong> <span style={{ color: '#dc3545' }}>-{pullRequest.diff.totalDeletions}</span>
          </div>
        </div>

        <div style={styles.metaSection}>
          <h4>Reviewers</h4>
          <div style={styles.reviewersList}>
            {pullRequest.reviewers.map((reviewer) => (
              <div key={reviewer.id} style={styles.reviewer}>
                <img
                  src={reviewer.avatar || '/default-avatar.png'}
                  alt={reviewer.name}
                  style={styles.reviewerAvatar}
                />
                <span>{reviewer.name}</span>
              </div>
            ))}
          </div>
        </div>

        <div style={styles.metaSection}>
          <h4>Approvals</h4>
          <div style={styles.approvalsList}>
            {pullRequest.approvers.map((approver, index) => (
              <div key={index} style={styles.approval}>
                <img
                  src={approver.user.avatar || '/default-avatar.png'}
                  alt={approver.user.name}
                  style={styles.reviewerAvatar}
                />
                <div style={styles.approvalInfo}>
                  <div style={styles.approverName}>{approver.user.name}</div>
                  <div style={{
                    ...styles.approvalStatus,
                    color: approver.status === 'approved' ? '#28a745' : 
                           approver.status === 'rejected' ? '#dc3545' : '#6c757d'
                  }}>
                    {approver.status.toUpperCase()}
                  </div>
                  {approver.comment && (
                    <div style={styles.approvalComment}>{approver.comment}</div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );

  const renderFiles = () => (
    <div style={styles.filesTab}>
      <CodeDiff
        files={pullRequest.diff.files}
        comments={pullRequest.comments}
        onAddComment={onAddComment}
      />
    </div>
  );

  const renderComments = () => (
    <div style={styles.commentsTab}>
      <h3>Comments ({pullRequest.comments.length})</h3>
      {pullRequest.comments.length === 0 ? (
        <p style={styles.noComments}>No comments yet.</p>
      ) : (
        <div style={styles.commentsList}>
          {pullRequest.comments.map((comment) => (
            <div key={comment.id} style={styles.comment}>
              <div style={styles.commentHeader}>
                <img
                  src={getCommentAuthorAvatar(comment.author)}
                  alt={getCommentAuthorName(comment.author)}
                  style={styles.commentAvatar}
                />
                <div style={styles.commentMeta}>
                  <strong>{getCommentAuthorName(comment.author)}</strong>
                  <span style={styles.commentTime}>
                    {comment.createdAt.toLocaleDateString()}
                  </span>
                </div>
              </div>
              <div style={styles.commentContent}>
                {comment.content}
              </div>
              {getCommentFilePath(comment) && (
                <div style={styles.commentFile}>
                  On file: <code>{getCommentFilePath(comment)}</code>
                  {comment.lineNumber && ` at line ${comment.lineNumber}`}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <button onClick={onBack} style={styles.backButton}>
          ← Back to List
        </button>
        
        <div style={styles.titleSection}>
          <h1 style={styles.title}>
            #{pullRequest.number} {pullRequest.title}
          </h1>
          <div
            style={{
              ...styles.statusBadge,
              backgroundColor: getStatusColor(pullRequest.status),
            }}
          >
            {getStatusIcon(pullRequest.status)} {pullRequest.status.toUpperCase()}
          </div>
        </div>
      </div>

      <div style={styles.tabs}>
        <button
          onClick={() => setActiveTab('overview')}
          style={{
            ...styles.tab,
            ...(activeTab === 'overview' ? styles.activeTab : {}),
          }}
        >
          Overview
        </button>
        <button
          onClick={() => setActiveTab('files')}
          style={{
