'use client';

import React, { useRef, useState, useEffect, useCallback, CSSProperties } from 'react';

export interface VirtualListProps<T> {
  items: T[];
  height: number;
  itemHeight?: number | ((item: T, index: number) => number);
  overscan?: number;
  renderItem: (item: T, index: number) => React.ReactNode;
  className?: string;
  onScroll?: (scrollTop: number) => void;
}

interface ItemPosition {
  index: number;
  top: number;
  height: number;
}

export function VirtualList<T>({
  items,
  height,
  itemHeight = 50,
  overscan = 3,
  renderItem,
  className = '',
  onScroll,
}: VirtualListProps<T>) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [measuredHeights, setMeasuredHeights] = useState<Map<number, number>>(new Map());

  // Calculate item positions based on measured or estimated heights
  const itemPositions = React.useMemo<ItemPosition[]>(() => {
    const positions: ItemPosition[] = [];
    let currentTop = 0;

    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      let itemHeightValue: number;

      // Get the base height estimate
      const baseHeight = typeof itemHeight === 'function' ? itemHeight(item, i) : itemHeight;
      
      // Use measured height if available and valid, otherwise use base height
      const measured = measuredHeights.get(i);
      itemHeightValue = (measured && measured > 0) ? measured : baseHeight;

      positions.push({
        index: i,
        top: currentTop,
        height: itemHeightValue,
      });

      currentTop += itemHeightValue;
    }

    return positions;
  }, [items, itemHeight, measuredHeights]);

  const totalHeight = itemPositions.length > 0 
    ? itemPositions[itemPositions.length - 1].top + itemPositions[itemPositions.length - 1].height 
    : 0;

  // Binary search to find the first visible item
  const findStartIndex = useCallback((scrollTop: number): number => {
    if (itemPositions.length === 0) return 0;
    
    let left = 0;
    let right = itemPositions.length - 1;

    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (itemPositions[mid].top + itemPositions[mid].height <= scrollTop) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    return Math.max(0, left - overscan);
  }, [itemPositions, overscan]);

  // Find the last visible item
  const findEndIndex = useCallback((scrollTop: number, viewportHeight: number): number => {
    if (itemPositions.length === 0) return 0;
    
    const scrollBottom = scrollTop + viewportHeight;
    
    // Find the last item whose top is less than scrollBottom
    for (let i = itemPositions.length - 1; i >= 0; i--) {
      if (itemPositions[i].top < scrollBottom) {
        return Math.min(itemPositions.length - 1, i + overscan);
      }
    }
    
    return Math.min(itemPositions.length - 1, overscan);
  }, [itemPositions, overscan]);

  const startIndex = itemPositions.length > 0 ? findStartIndex(scrollTop) : 0;
  const endIndex = itemPositions.length > 0 ? findEndIndex(scrollTop, height) : 0;

  const visibleItems = itemPositions.length > 0 ? itemPositions.slice(startIndex, endIndex + 1) : [];

  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    const newScrollTop = e.currentTarget.scrollTop;
    setScrollTop(newScrollTop);
    onScroll?.(newScrollTop);
  }, [onScroll]);

  // Measure item heights for dynamic sizing
  const measureItem = useCallback((index: number, element: HTMLElement | null) => {
    if (!element) return;

    const rect = element.getBoundingClientRect();
    const measuredHeight = rect.height;
    
    // Only update if we got a valid measurement
    if (measuredHeight > 0) {
      setMeasuredHeights(prev => {
        if (prev.get(index) === measuredHeight) return prev;
        const next = new Map(prev);
        next.set(index, measuredHeight);
        return next;
      });
    }
  }, []);

  const containerStyle: CSSProperties = {
    height: `${height}px`,
    overflow: 'auto',
    position: 'relative',
  };

  const innerStyle: CSSProperties = {
    height: `${totalHeight}px`,
    position: 'relative',
  };

  return (
    <div
      ref={containerRef}
      className={className}
      style={containerStyle}
      onScroll={handleScroll}
      data-testid="virtual-list-container"
    >
      <div style={innerStyle} data-testid="virtual-list-inner">
        {visibleItems.map(({ index, top, height: estimatedHeight }) => {
          const item = items[index];
          return (
            <div
              key={index}
              ref={el => measureItem(index, el)}
              style={{
                position: 'absolute',
                top: `${top}px`,
                left: 0,
                right: 0,
                minHeight: `${estimatedHeight}px`,
              }}
              data-index={index}
            >
              {renderItem(item, index)}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/**
 * ErrorBoundarypropertytest
 * 
 * Feature: frontend-production-optimization
 * Property 6: error边界捕获
 * 
 * **Validates: Requirements 1.3**
 * 
 * testCoverage:
 * - 对于任何component内发生的error，ErrorBoundaryshould捕获error并show降级UI，而不是导致整item应用崩溃
 */

import React from 'react';
import { render, screen, cleanup } from '@testing-library/react';
import fc from 'fast-check';
import { ErrorBoundary } from '../ErrorBoundary';
import { getErrorMonitor, resetErrorMonitor, MonitorConfig } from '../../services/ErrorMonitor';

describe('Property 6: error边界捕获', () => {
  let consoleErrorSpy: jest.SpyInstance;

  beforeAll(() => {
    // 抑制React的errorlogoutput
    consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
  });

  beforeEach(() => {
    // 初始化ErrorMonitor
    resetErrorMonitor();
    const config: MonitorConfig = {
      environment: 'test',
      enableDebugMode: false,
    };
    const monitor = getErrorMonitor(config);
    monitor.initialize();
  });

  afterEach(() => {
    jest.clearAllMocks();
    resetErrorMonitor();
  });

  afterAll(() => {
    consoleErrorSpy.mockRestore();
  });

  // customGenerator：generateerror消息
  const errorMessageArbitrary = () =>
    fc.oneof(
      fc.string({ minLength: 1, maxLength: 200 }).filter(s => s.trim().length > 0),
      fc.constantFrom(
        'Network error',
        'Failed to fetch',
        'Timeout exceeded',
        'Invalid response',
        'Permission denied',
        'Resource not found',
        'Unexpected token',
        'Cannot read property',
        'undefined is not a function',
        'Maximum call stack size exceeded'
      )
    );

  // customGenerator：generateerrortype
  const errorTypeArbitrary = () =>
    fc.constantFrom(
      Error,
      TypeError,
      ReferenceError,
      RangeError,
      SyntaxError
    );

  // customGenerator：generate会抛出error的component
  const throwingComponentArbitrary = () =>
    fc.record({
      errorMessage: errorMessageArbitrary(),
      ErrorType: errorTypeArbitrary(),
      componentName: fc.constantFrom(
        'UserProfile',
        'Dashboard',
        'DataTable',
        'ChartWidget',
        'FormInput',
        'NavigationMenu'
      ),
    });

  it('should捕获所有type的componenterror并show降级UI', () => {
    fc.assert(
      fc.property(
        throwingComponentArbitrary(),
        ({ errorMessage, ErrorType, componentName }) => {
          // create会抛出特定error的component
          const ThrowingComponent: React.FC = () => {
            throw new ErrorType(errorMessage);
          };
          ThrowingComponent.displayName = componentName;

          // render包裹在ErrorBoundary中的component
          const { unmount } = render(
            <ErrorBoundary>
              <ThrowingComponent />
            </ErrorBoundary>
          );

          try {
            // verify降级UI被show（requirement1.3）
            expect(screen.getAllByText(/something went wrong/i)[0]).toBeInTheDocument();

            // verify原始componentcontent没有被render
            expect(screen.queryByText('Normal content')).not.toBeInTheDocument();

            // verifyerrorhandlebutton存在
            expect(screen.getAllByText(/try again/i)[0]).toBeInTheDocument();
            expect(screen.getAllByText(/reload page/i)[0]).toBeInTheDocument();
            expect(screen.getAllByText(/report issue/i)[0]).toBeInTheDocument();
          } finally {
            // cleanupDOM
            unmount();
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('should为所有捕获的error上报到ErrorMonitor', () => {
    fc.assert(
      fc.property(
        errorMessageArbitrary(),
        errorTypeArbitrary(),
        (errorMessage, ErrorType) => {
          const monitor = getErrorMonitor();
          const captureErrorSpy = jest.spyOn(monitor, 'captureError');

          // create会抛出error的component
          const ThrowingComponent: React.FC = () => {
            throw new ErrorType(errorMessage);
          };

          const { unmount } = render(
            <ErrorBoundary>
              <ThrowingComponent />
            </ErrorBoundary>
          );

          try {
            // verifyerror被上报到ErrorMonitor（requirement1.3）
            expect(captureErrorSpy).toHaveBeenCalledTimes(1);
            expect(captureErrorSpy).toHaveBeenCalledWith(
              expect.any(ErrorType),
              expect.objectContaining({
                url: expect.any(String),
                userAgent: expect.any(String),
                timestamp: expect.any(Date),
                additionalData: expect.objectContaining({
                  componentStack: expect.any(String),
                  errorBoundary: true,
                }),
              })
            );
          } finally {
            captureErrorSpy.mockRestore();
            unmount();
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('shouldBeAt捕获error后不影response用的其他部分', () => {
    fc.assert(
      fc.property(
        errorMessageArbitrary(),
        fc.string({ minLength: 1, maxLength: 50 }).filter(s => s.trim().length > 0),
        (errorMessage, siblingContent) => {
          // create会抛出error的component
          const ThrowingComponent: React.FC = () => {
            throw new Error(errorMessage);
          };

          // rendercontainerrorcomponentand正常component的应用
          const { unmount } = render(
            <div>
              <div data-testid="sibling">{siblingContent}</div>
              <ErrorBoundary>
                <ThrowingComponent />
              </ErrorBoundary>
            </div>
          );

          try {
            // verify降级UI被show
            expect(screen.getAllByText(/something went wrong/i)[0]).toBeInTheDocument();

            // verify兄弟component仍然正常render（requirement1.3 - 不导致整item应用崩溃）
            const sibling = screen.getByTestId('sibling');
            expect(sibling).toBeInTheDocument();
            expect(sibling.textContent).toBe(siblingContent);
          } finally {
            unmount();
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('should为嵌套的ErrorBoundary正确隔离error', () => {
    fc.assert(
      fc.property(
        errorMessageArbitrary(),
        fc.string({ minLength: 1, maxLength: 50 }).filter(s => s.trim().length > 0),
        (errorMessage, outerContent) => {
          // create会抛出error的component
          const ThrowingComponent: React.FC = () => {
            throw new Error(errorMessage);
          };

          // render嵌套的ErrorBoundary
          const { unmount } = render(
            <ErrorBoundary>
              <div data-testid="outer-content">{outerContent}</div>
              <ErrorBoundary>
                <ThrowingComponent />
              </ErrorBoundary>
            </ErrorBoundary>
          );

          try {
            // verify内部ErrorBoundary捕获了error
            expect(screen.getAllByText(/something went wrong/i)[0]).toBeInTheDocument();

            // verify外部ErrorBoundary的content仍然正常show（requirement1.3）
            const outerElement = screen.getByTestId('outer-content');
            expect(outerElement).toBeInTheDocument();
            expect(outerElement.textContent).toBe(outerContent);
          } finally {
            unmount();
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('shouldBeAtrender生命周期的任何阶段捕获error', () => {
    fc.assert(
      fc.property(
        errorMessageArbitrary(),
        fc.constantFrom('constructor', 'render', 'componentDidMount'),
        (errorMessage, lifecyclePhase) => {
          // create在不同生命周期阶段抛出error的component
          class LifecycleErrorComponent extends React.Component<{}, { shouldError: boolean }> {
            constructor(props: {}) {
              super(props);
              this.state = { shouldError: false };
              if (lifecyclePhase === 'constructor') {
                throw new Error(errorMessage);
              }
            }

            componentDidMount() {
              if (lifecyclePhase === 'componentDidMount') {
                throw new Error(errorMessage);
              }
            }

            render() {
              if (lifecyclePhase === 'render') {
                throw new Error(errorMessage);
              }
              return <div>Component content</div>;
            }
          }

          const { unmount } = render(
            <ErrorBoundary>
              <LifecycleErrorComponent />
            </ErrorBoundary>
          );

          try {
            // verifyerror被捕获并show降级UI（requirement1.3）
            expect(screen.getAllByText(/something went wrong/i)[0]).toBeInTheDocument();
          } finally {
            unmount();
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('shouldBeAtuse自定义fallback时正确传递errorinfo', () => {
    fc.assert(
      fc.property(
        errorMessageArbitrary(),
        fc.string({ minLength: 1, maxLength: 50 }).filter(s => s.trim().length > 0),
        (errorMessage, customMessage) => {
          // create会抛出error的component
          const ThrowingComponent: React.FC = () => {
            throw new Error(errorMessage);
          };

          // 自定义fallback
          const customFallback = (error: Error) => (
            <div data-testid="custom-fallback">
              {customMessage}: {error.message}
            </div>
          );

          const { unmount, container } = render(
            <ErrorBoundary fallback={customFallback}>
              <ThrowingComponent />
            </ErrorBoundary>
          );

          try {
            // verify自定义fallback被show（requirement1.3）
            const fallbacks = container.querySelectorAll('[data-testid="custom-fallback"]');
            expect(fallbacks.length).toBeGreaterThan(0);
            const fallback = fallbacks[fallbacks.length - 1];
            expect(fallback).toBeInTheDocument();
            // verifycontain两部分content
            expect(fallback.textContent).toContain(customMessage);
            expect(fallback.textContent).toContain(errorMessage);
          } finally {
            unmount();
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('should为所有errortypeprovide一致的errorhandle', () => {
    fc.assert(
      fc.property(
        fc.array(
          fc.record({
            errorMessage: errorMessageArbitrary(),
            ErrorType: errorTypeArbitrary(),
          }),
          { minLength: 1, maxLength: 5 }
        ),
        (errorConfigs) => {
          // test多item不同的errorconfig
          errorConfigs.forEach(({ errorMessage, ErrorType }) => {
            const ThrowingComponent: React.FC = () => {
              throw new ErrorType(errorMessage);
            };

            const { unmount } = render(
              <ErrorBoundary>
                <ThrowingComponent />
              </ErrorBoundary>
            );

            try {
              // verify所有errortype都被一致地handle（requirement1.3）
              expect(screen.getAllByText(/something went wrong/i)[0]).toBeInTheDocument();
              expect(screen.getAllByText(/try again/i)[0]).toBeInTheDocument();
            } finally {
              // cleanup
              unmount();
            }
          });
        }
      ),
      { numRuns: 100 }
    );
  });

  it('shouldBeAterror发生时保持应用status的完整性', () => {
    fc.assert(
      fc.property(
        errorMessageArbitrary(),
        fc.record({
          count: fc.integer({ min: 0, max: 100 }),
          name: fc.string({ minLength: 1, maxLength: 50 }).filter(s => s.trim().length > 0),
          isActive: fc.boolean(),
        }),
        (errorMessage, appState) => {
          // create会抛出error的component
          const ThrowingComponent: React.FC = () => {
            throw new Error(errorMessage);
          };

          // create带有status的应用
          const AppWithState: React.FC = () => {
            const [state] = React.useState(appState);
            return (
              <div>
                <div data-testid="app-state">
                  {JSON.stringify(state)}
                </div>
                <ErrorBoundary>
                  <ThrowingComponent />
                </ErrorBoundary>
              </div>
            );
          };

          const { unmount } = render(<AppWithState />);

          try {
            // verifyerror被捕获
            expect(screen.getAllByText(/something went wrong/i)[0]).toBeInTheDocument();

            // verify应用status没有被破坏（requirement1.3 - 不导致整item应用崩溃）
            const stateElement = screen.getByTestId('app-state');
            expect(stateElement).toBeInTheDocument();
            expect(stateElement.textContent).toBe(JSON.stringify(appState));
          } finally {
            unmount();
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('shouldBeAt捕获error后allowuser继续use应用的其他feature', () => {
    fc.assert(
      fc.property(
        errorMessageArbitrary(),
        fc.array(fc.string({ minLength: 1, maxLength: 30 }).filter(s => s.trim().length > 0), { minLength: 1, maxLength: 5 }),
        (errorMessage, menuItems) => {
          // create会抛出error的component
          const ThrowingComponent: React.FC = () => {
            throw new Error(errorMessage);
          };

          // rendercontainnavmenuanderrorcomponent的应用
          const { unmount } = render(
            <div>
              <nav data-testid="navigation">
                {menuItems.map((item, index) => (
                  <button key={index} data-testid={`menu-item-${index}`}>
                    {item}
                  </button>
                ))}
              </nav>
              <ErrorBoundary>
                <ThrowingComponent />
              </ErrorBoundary>
            </div>
          );

          try {
            // verifyerror被捕获
            expect(screen.getAllByText(/something went wrong/i)[0]).toBeInTheDocument();

            // verifynavmenu仍然可用（requirement1.3 - allowuser继续use应用的其他部分）
            expect(screen.getByTestId('navigation')).toBeInTheDocument();
            menuItems.forEach((item, index) => {
              const menuItem = screen.getByTestId(`menu-item-${index}`);
              expect(menuItem).toBeInTheDocument();
              expect(menuItem.textContent).toBe(item);
            });
          } finally {
            unmount();
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('should为所有捕获的error调用onError回调', () => {
    fc.assert(
      fc.property(
        errorMessageArbitrary(),
        errorTypeArbitrary(),
        (errorMessage, ErrorType) => {
          const onError = jest.fn();

          // create会抛出error的component
          const ThrowingComponent: React.FC = () => {
            throw new ErrorType(errorMessage);
          };

          const { unmount } = render(
            <ErrorBoundary onError={onError}>
              <ThrowingComponent />
            </ErrorBoundary>
          );

          try {
            // verifyonError回调被调用（requirement1.3）
            expect(onError).toHaveBeenCalledTimes(1);
            expect(onError).toHaveBeenCalledWith(
              expect.any(ErrorType),
              expect.objectContaining({
                componentStack: expect.any(String),
              })
            );
          } finally {
            unmount();
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('shouldBeAtErrorMonitor未初始化时仍然show降级UI', () => {
    fc.assert(
      fc.property(
        errorMessageArbitrary(),
        (errorMessage) => {
          // resetErrorMonitor使其未初始化
          resetErrorMonitor();

          // create会抛出error的component
          const ThrowingComponent: React.FC = () => {
            throw new Error(errorMessage);
          };

          const { unmount } = render(
            <ErrorBoundary>
              <ThrowingComponent />
            </ErrorBoundary>
          );

          try {
            // verify即使ErrorMonitor未初始化，降级UI仍然show（requirement1.3 - 健壮性）
            expect(screen.getAllByText(/something went wrong/i)[0]).toBeInTheDocument();
            expect(screen.getAllByText(/try again/i)[0]).toBeInTheDocument();
          } finally {
            unmount();
            // 重新初始化ErrorMonitor以供后续testuse
            const config: MonitorConfig = {
              environment: 'test',
              enableDebugMode: false,
            };
            const monitor = getErrorMonitor(config);
            monitor.initialize();
          }
        }
      ),
      { numRuns: 100 }
    );
  });
});

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import '@testing-library/jest-dom';
import fc from 'fast-check';
import { VirtualList } from '../VirtualList';

/**
 * Feature: frontend-production-optimization
 * 
 * Property-based tests for VirtualList component to verify:
 * - Only visible items are rendered (performance optimization)
 * - Correct positioning of items
 * - Proper handling of dynamic heights
 * - Scroll behavior correctness
 */

describe('VirtualList Property-Based Tests', () => {
  // Arbitrary for generating test items
  const itemArbitrary = fc.record({
    id: fc.integer({ min: 0, max: 10000 }),
    name: fc.string({ minLength: 1, maxLength: 50 }),
    content: fc.string({ minLength: 0, maxLength: 200 }),
  });

  const itemsArbitrary = fc.array(itemArbitrary, { minLength: 0, maxLength: 300 });

  /**
   * Property: Virtual scrolling should only render visible items
   * 
   * For any list of items and viewport configuration, the number of rendered items
   * should be proportional to the viewport height, not the total number of items.
   * This ensures performance optimization for large lists (100+ items).
   * 
   * Validates: Requirements 2.4, 5.5
   */
  it('should only render visible items regardless of total item count', () => {
    fc.assert(
      fc.property(
        itemsArbitrary,
        fc.integer({ min: 200, max: 1000 }), // viewport height
        fc.integer({ min: 30, max: 100 }), // item height
        (items, viewportHeight, itemHeight) => {
          if (items.length === 0) return true;

          const renderItem = jest.fn((item: typeof items[0]) => (
            <div>{item.name}</div>
          ));

          const { unmount } = render(
            <VirtualList
              items={items}
              height={viewportHeight}
              itemHeight={itemHeight}
              renderItem={renderItem}
            />
          );

          const renderedCount = renderItem.mock.calls.length;
          const maxVisibleItems = Math.ceil(viewportHeight / itemHeight);
          const expectedMaxRendered = maxVisibleItems + 6; // overscan default is 3 on each side

          // Should not render all items if list is large
          if (items.length > expectedMaxRendered) {
            expect(renderedCount).toBeLessThanOrEqual(expectedMaxRendered + 5); // small buffer for edge cases
          } else {
            // If list is small, should render all or nearly all items (within overscan range)
            expect(renderedCount).toBeGreaterThanOrEqual(Math.min(items.length - 1, 1));
            expect(renderedCount).toBeLessThanOrEqual(items.length);
          }

          unmount();
          return true;
        }
      ),
      { numRuns: 50 }
    );
  });

  /**
   * Property: Item positioning should be consistent and sequential
   * 
   * For any list of items with fixed height, each item should be positioned
   * exactly at index * itemHeight from the top.
   * 
   * Validates: Requirements 2.4, 5.5
   */
  it('should position items correctly based on their index and height', () => {
    fc.assert(
      fc.property(
        fc.array(itemArbitrary, { minLength: 10, maxLength: 50 }),
        fc.integer({ min: 40, max: 80 }), // item height
        (items, itemHeight) => {
          const renderItem = (item: typeof items[0]) => <div>{item.name}</div>;

          const { container, unmount } = render(
            <VirtualList
              items={items}
              height={500}
              itemHeight={itemHeight}
              renderItem={renderItem}
            />
          );

          const inner = container.querySelector('[data-testid="virtual-list-inner"]') as HTMLElement;
          const renderedItems = inner.querySelectorAll('[data-index]');

          renderedItems.forEach((element) => {
            const htmlElement = element as HTMLElement;
            const index = parseInt(htmlElement.getAttribute('data-index') || '0');
            const expectedTop = index * itemHeight;
            expect(htmlElement.style.top).toBe(`${expectedTop}px`);
          });

          unmount();
          return true;
        }
      ),
      { numRuns: 30 }
    );
  });

  /**
   * Property: Total height should equal sum of all item heights
   * 
   * For any list of items, the total scrollable height should equal
   * the sum of all item heights.
   * 
   * Validates: Requirements 2.4, 5.5
   */
  it('should calculate total height correctly', () => {
    fc.assert(
      fc.property(
        fc.array(itemArbitrary, { minLength: 1, maxLength: 100 }),
        fc.integer({ min: 30, max: 100 }), // item height
        (items, itemHeight) => {
          const renderItem = (item: typeof items[0]) => <div>{item.name}</div>;

          const { container, unmount } = render(
            <VirtualList
              items={items}
              height={500}
              itemHeight={itemHeight}
              renderItem={renderItem}
            />
          );

          const inner = container.querySelector('[data-testid="virtual-list-inner"]') as HTMLElement;
          const actualHeight = parseInt(inner.style.height);
          const expectedHeight = items.length * itemHeight;

          expect(actualHeight).toBe(expectedHeight);

          unmount();
          return true;
        }
      ),
      { numRuns: 50 }
    );
  });

  /**
   * Property: Scrolling should update visible items correctly
   * 
   * For any scroll position, the rendered items should correspond to
   * the items visible in the viewport at that position.
   * 
   * Validates: Requirements 2.4, 5.5
   */
  it('should render correct items after scrolling', () => {
    fc.assert(
      fc.property(
        fc.array(itemArbitrary, { minLength: 50, maxLength: 150 }),
        fc.integer({ min: 300, max: 600 }), // viewport height
        fc.integer({ min: 40, max: 80 }), // item height
        fc.integer({ min: 0, max: 5000 }), // scroll position
        (items, viewportHeight, itemHeight, scrollTop) => {
          const renderItem = jest.fn((item: typeof items[0], index: number) => (
            <div>{item.name}</div>
          ));

          const { unmount } = render(
            <VirtualList
              items={items}
              height={viewportHeight}
              itemHeight={itemHeight}
              renderItem={renderItem}
            />
          );

          const container = screen.getByTestId('virtual-list-container');
          
          // Scroll to position
          fireEvent.scroll(container, { target: { scrollTop } });

          // Calculate expected visible range
          const startIndex = Math.floor(scrollTop / itemHeight);
          const endIndex = Math.ceil((scrollTop + viewportHeight) / itemHeight);

          // Check that rendered items are within or near the visible range
          const renderedIndices = renderItem.mock.calls.map(call => call[1]);
          
          if (renderedIndices.length > 0) {
            const minRendered = Math.min(...renderedIndices);
            const maxRendered = Math.max(...renderedIndices);

            // With overscan, rendered range should include visible range
            expect(minRendered).toBeLessThanOrEqual(Math.max(0, startIndex));
            expect(maxRendered).toBeGreaterThanOrEqual(Math.min(items.length - 1, endIndex));
          }

          unmount();
          return true;
        }
      ),
      { numRuns: 30 }
    );
  });

  /**
   * Property: Dynamic height function should be called for each item
   * 
   * When using a dynamic height function, it should be called to calculate
   * the height for each item in the list.
   * 
   * Validates: Requirements 2.4, 5.5
   */
  it('should support dynamic item heights', () => {
    fc.assert(
      fc.property(
        fc.array(itemArbitrary, { minLength: 10, maxLength: 50 }),
        (items) => {
          const heightFn = jest.fn((item: typeof items[0]) => {
            return item.id % 2 === 0 ? 50 : 80;
          });

          const renderItem = (item: typeof items[0]) => <div>{item.name}</div>;

          const { unmount } = render(
            <VirtualList
              items={items}
              height={500}
              itemHeight={heightFn}
              renderItem={renderItem}
            />
          );

          // Height function should be called during position calculation
          expect(heightFn).toHaveBeenCalled();

          unmount();
          return true;
        }
      ),
      { numRuns: 30 }
    );
  });

  /**
   * Property: Empty list should render without errors
   * 
   * For an empty items array, the component should render successfully
   * without throwing errors.
   * 
   * Validates: Requirements 2.4, 5.5
   */
  it('should handle empty lists gracefully', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 200, max: 1000 }), // viewport height
        fc.integer({ min: 30, max: 100 }), // item height
        (viewportHeight, itemHeight) => {
          const renderItem = jest.fn((item: any) => <div>{item.name}</div>);

          const { unmount } = render(
            <VirtualList
              items={[]}
              height={viewportHeight}
              itemHeight={itemHeight}
              renderItem={renderItem}
            />
          );

          const container = screen.getByTestId('virtual-list-container');
          expect(container).toBeInTheDocument();
          expect(renderItem).not.toHaveBeenCalled();

          unmount();
          return true;
        }
      ),
      { numRuns: 20 }
    );
  });

  /**
   * Property: Performance should remain constant regardless of total items
   * 
   * Rendering time should not significantly increase with the total number
   * of items, as only visible items are rendered.
   * 
   * Validates: Requirements 2.4, 5.5
   */
  it('should maintain consistent performance for large lists', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 100, max: 500 }), // number of items
        (itemCount) => {
          const items = Array.from({ length: itemCount }, (_, i) => ({
            id: i,
            name: `Item ${i}`,
            content: `Content ${i}`,
          }));

          const renderItem = (item: typeof items[0]) => <div>{item.name}</div>;

          const startTime = performance.now();
          const { unmount } = render(
            <VirtualList
              items={items}
              height={500}
              itemHeight={50}
              renderItem={renderItem}
            />
          );
          const endTime = performance.now();

          const renderTime = endTime - startTime;

          // Rendering should be fast regardless of item count (relaxed threshold for CI)
          expect(renderTime).toBeLessThan(200);

          unmount();
          return true;
        }
      ),
      { numRuns: 20 }
    );
  });

  /**
   * Property: onScroll callback should be called with correct scroll position
   * 
   * When scrolling occurs, the onScroll callback should be invoked with
   * the current scroll position.
   * 
   * Validates: Requirements 2.4, 5.5
   */
  it('should call onScroll with correct scroll position', () => {
    fc.assert(
      fc.property(
        fc.array(itemArbitrary, { minLength: 50, maxLength: 100 }),
        fc.integer({ min: 0, max: 2000 }), // scroll position
        (items, scrollTop) => {
          const onScroll = jest.fn();
          const renderItem = (item: typeof items[0]) => <div>{item.name}</div>;

          const { unmount } = render(
            <VirtualList
              items={items}
              height={500}
              itemHeight={50}
              renderItem={renderItem}
              onScroll={onScroll}
            />
          );

          const container = screen.getByTestId('virtual-list-container');
          fireEvent.scroll(container, { target: { scrollTop } });

          expect(onScroll).toHaveBeenCalledWith(scrollTop);

          unmount();
          return true;
        }
      ),
      { numRuns: 30 }
    );
  });
});

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import { VirtualList } from '../VirtualList';

describe('VirtualList', () => {
  const mockItems = Array.from({ length: 200 }, (_, i) => ({
    id: i,
    name: `Item ${i}`,
  }));

  const mockRenderItem = jest.fn((item: typeof mockItems[0], index: number) => (
    <div data-testid={`item-${item.id}`}>{item.name}</div>
  ));

  beforeEach(() => {
    mockRenderItem.mockClear();
  });

  it('should render only visible items', () => {
    render(
      <VirtualList
        items={mockItems}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
      />
    );

    const container = screen.getByTestId('virtual-list-container');
    expect(container).toBeInTheDocument();

    // Should render approximately 500/50 = 10 items + overscan
    // With default overscan of 3, we expect around 16 items (10 + 3*2)
    expect(mockRenderItem).toHaveBeenCalled();
    const callCount = mockRenderItem.mock.calls.length;
    expect(callCount).toBeGreaterThan(10);
    expect(callCount).toBeLessThan(mockItems.length); // Should not render all 200 items
  });

  it('should render all items when list is short', () => {
    const shortItems = mockItems.slice(0, 5);
    render(
      <VirtualList
        items={shortItems}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
      />
    );

    // With overscan, might render a few more than the actual count
    expect(mockRenderItem.mock.calls.length).toBeGreaterThanOrEqual(shortItems.length);
  });

  it('should update visible items on scroll', async () => {
    const { rerender } = render(
      <VirtualList
        items={mockItems}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
      />
    );

    const container = screen.getByTestId('virtual-list-container');
    const initialCallCount = mockRenderItem.mock.calls.length;

    // Scroll down
    fireEvent.scroll(container, { target: { scrollTop: 1000 } });

    // Wait for state update
    await waitFor(() => {
      expect(mockRenderItem.mock.calls.length).toBeGreaterThan(initialCallCount);
    });

    // Check that different items are rendered
    const lastCall = mockRenderItem.mock.calls[mockRenderItem.mock.calls.length - 1];
    expect(lastCall[1]).toBeGreaterThan(10); // Index should be greater than initial visible range
  });

  it('should call onScroll callback when scrolling', () => {
    const onScroll = jest.fn();
    render(
      <VirtualList
        items={mockItems}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
        onScroll={onScroll}
      />
    );

    const container = screen.getByTestId('virtual-list-container');
    fireEvent.scroll(container, { target: { scrollTop: 500 } });

    expect(onScroll).toHaveBeenCalledWith(500);
  });

  it('should support dynamic item heights with function', () => {
    const dynamicHeightFn = jest.fn((item: typeof mockItems[0]) => {
      return item.id % 2 === 0 ? 50 : 100;
    });

    render(
      <VirtualList
        items={mockItems}
        height={500}
        itemHeight={dynamicHeightFn}
        renderItem={mockRenderItem}
      />
    );

    expect(dynamicHeightFn).toHaveBeenCalled();
    expect(mockRenderItem).toHaveBeenCalled();
  });

  it('should apply custom className', () => {
    render(
      <VirtualList
        items={mockItems}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
        className="custom-class"
      />
    );

    const container = screen.getByTestId('virtual-list-container');
    expect(container).toHaveClass('custom-class');
  });

  it('should handle empty items array', () => {
    render(
      <VirtualList
        items={[]}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
      />
    );

    const container = screen.getByTestId('virtual-list-container');
    expect(container).toBeInTheDocument();
    expect(mockRenderItem).not.toHaveBeenCalled();
  });

  it('should set correct total height based on items', () => {
    render(
      <VirtualList
        items={mockItems}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
      />
    );

    const inner = screen.getByTestId('virtual-list-inner');
    const expectedHeight = mockItems.length * 50;
    expect(inner).toHaveStyle({ height: `${expectedHeight}px` });
  });

  it('should support custom overscan value', () => {
    render(
      <VirtualList
        items={mockItems}
        height={500}
        itemHeight={50}
        overscan={5}
        renderItem={mockRenderItem}
      />
    );

    // With overscan of 5, should render more items
    const callCount = mockRenderItem.mock.calls.length;
    expect(callCount).toBeGreaterThan(10);
  });

  it('should handle large lists efficiently (100+ items)', () => {
    const largeItems = Array.from({ length: 150 }, (_, i) => ({
      id: i,
      name: `Item ${i}`,
    }));

    const startTime = performance.now();
    render(
      <VirtualList
        items={largeItems}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
      />
    );
    const endTime = performance.now();

    // Should render quickly (less than 200ms for CI environments)
    expect(endTime - startTime).toBeLessThan(200);

    // Should not render all items
    expect(mockRenderItem.mock.calls.length).toBeLessThan(largeItems.length);
  });

  it('should position items correctly', () => {
    render(
      <VirtualList
        items={mockItems.slice(0, 10)}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
      />
    );

    const inner = screen.getByTestId('virtual-list-inner');
    const items = inner.querySelectorAll('[data-index]');

    items.forEach((item, index) => {
      const element = item as HTMLElement;
      const expectedTop = index * 50;
      expect(element.style.top).toBe(`${expectedTop}px`);
    });
  });

  it('should handle scroll to bottom', async () => {
    render(
      <VirtualList
        items={mockItems}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
      />
    );

    const container = screen.getByTestId('virtual-list-container');
    const inner = screen.getByTestId('virtual-list-inner');
    const totalHeight = parseInt(inner.style.height);

    // Scroll to bottom
    fireEvent.scroll(container, { target: { scrollTop: totalHeight - 500 } });

    await waitFor(() => {
      // Should render items near the end
      const lastCall = mockRenderItem.mock.calls[mockRenderItem.mock.calls.length - 1];
      expect(lastCall[1]).toBeGreaterThan(mockItems.length - 20);
    });
  });

  it('should maintain performance with frequent scrolling', async () => {
    const onScroll = jest.fn();
    render(
      <VirtualList
        items={mockItems}
        height={500}
        itemHeight={50}
        renderItem={mockRenderItem}
        onScroll={onScroll}
      />
    );

    const container = screen.getByTestId('virtual-list-container');

    // Simulate rapid scrolling
    const startTime = performance.now();
    for (let i = 0; i < 10; i++) {
      fireEvent.scroll(container, { target: { scrollTop: i * 100 } });
    }
    const endTime = performance.now();

    // Should handle rapid scrolling efficiently (relaxed for CI)
    expect(endTime - startTime).toBeLessThan(200);
    expect(onScroll).toHaveBeenCalledTimes(10);
  });
});

import React from 'react';
import { AnalysisTask, ScheduleResult, RetrySchedule } from '../../types/AnalysisQueue';
import {
  getTaskTypeText,
  getStatusColor,
  getStatusText,
  getPriorityText,
  getPriorityColor,
  formatTime,
  formatDuration,
  calculateEstimatedCompletion,
  formatEstimatedCompletion,
} from '../../utils/analysisQueueUtils';
import { styles } from './AnalysisQueue.styles';

interface TaskItemProps {
  task: AnalysisTask;
  isSelected: boolean;
  isScheduledToExecute: boolean;
  retrySchedule?: RetrySchedule;
  retryStatusText?: string;
  onSelect: (taskId: string) => void;
  onIncreasePriority: (taskId: string, currentPriority: number) => void;
  onDecreasePriority: (taskId: string, currentPriority: number) => void;
  onPriorityChange: (taskId: string, newPriority: number) => void;
}

export const TaskItem: React.FC<TaskItemProps> = ({
  task,
  isSelected,
  isScheduledToExecute,
  retrySchedule,
  retryStatusText,
  onSelect,
  onIncreasePriority,
  onDecreasePriority,
  onPriorityChange,
}) => {
  const canAdjustPriority = task.status === 'pending' || task.status === 'failed';
  const estimatedCompletion = calculateEstimatedCompletion(task);

  return (
    <div
      style={{
        ...styles.taskItem,
        ...(isSelected ? styles.taskItemSelected : {}),
      }}
      onClick={() => onSelect(task.id)}
      data-testid={`task-item-${task.id}`}
    >
      <div style={styles.taskHeader}>
        <div style={styles.taskTitle}>
          <span style={styles.taskName}>{task.name}</span>
          <span style={styles.taskType}>{getTaskTypeText(task.type)}</span>
        </div>
        <div style={styles.taskMeta}>
          <span
            style={{
              ...styles.priorityBadge,
              backgroundColor: getPriorityColor(task.priority),
            }}
          >
            {getPriorityText(task.priority)} ({task.priority})
          </span>
          <span
            style={{
              ...styles.statusBadge,
              backgroundColor: getStatusColor(task.status),
            }}
            data-testid={`task-status-${task.id}`}
          >
            {getStatusText(task.status)}
          </span>
          {isScheduledToExecute && task.status === 'pending' && (
            <span style={styles.scheduledBadge}>
              ⏱️ Scheduled
            </span>
          )}
          {retrySchedule && (
            <span style={styles.retryBadge}>
              🔄 Retry {task.retryCount + 1}/{task.maxRetries}
            </span>
          )}
        </div>
      </div>

      {canAdjustPriority && (
        <div style={styles.priorityControls}>
          <span style={styles.priorityControlsLabel}>Adjust Priority:</span>
          <div style={styles.priorityButtons}>
            <button
              style={{
                ...styles.priorityButton,
                ...(task.priority >= 10 ? styles.priorityButtonDisabled : {}),
              }}
              onClick={(e) => {
                e.stopPropagation();
                onIncreasePriority(task.id, task.priority);
              }}
              disabled={task.priority >= 10}
              data-testid={`increase-priority-${task.id}`}
              title="Increase priority"
            >
              ▲
            </button>
            <span style={styles.priorityValue}>{task.priority}</span>
            <button
              style={{
                ...styles.priorityButton,
                ...(task.priority <= 1 ? styles.priorityButtonDisabled : {}),
              }}
              onClick={(e) => {
                e.stopPropagation();
                onDecreasePriority(task.id, task.priority);
              }}
              disabled={task.priority <= 1}
              data-testid={`decrease-priority-${task.id}`}
              title="Decrease priority"
            >
              ▼
            </button>
          </div>
          <input
            type="range"
            min="1"
            max="10"
            value={task.priority}
            onChange={(e) => {
              e.stopPropagation();
              const newPriority = parseInt(e.target.value, 10);
              onPriorityChange(task.id, newPriority);
            }}
            style={styles.prioritySlider}
            data-testid={`priority-slider-${task.id}`}
            title={`Set priority (1-10): ${task.priority}`}
          />
        </div>
      )}

      {task.status === 'running' && (
        <>
          <div style={styles.progressContainer}>
            <div
              style={{
                ...styles.progressBar,
                width: `${task.progress}%`,
              }}
              data-testid={`task-progress-${task.id}`}
            />
            <span style={styles.progressText}>{task.progress}%</span>
          </div>
          {estimatedCompletion && (
            <div style={styles.estimatedCompletionContainer}>
              <span style={styles.estimatedCompletionLabel}>⏱️ Est. completion:</span>
              <span 
                style={styles.estimatedCompletionValue}
                data-testid={`task-estimated-completion-${task.id}`}
              >
                {formatEstimatedCompletion(estimatedCompletion)}
              </span>
              <span style={styles.estimatedCompletionTime}>
                ({estimatedCompletion.toLocaleTimeString()})
              </span>
            </div>
          )}
        </>
      )}

      {retrySchedule && retryStatusText && (
        <div style={styles.retryInfo}>
          <span style={styles.retryIcon}>🔄</span>
          <span style={styles.retryText}>{retryStatusText}</span>
        </div>
      )}

      <div style={styles.taskDetails}>
        <div style={styles.taskDetailItem}>
          <span style={styles.taskDetailLabel}>Created:</span>
          <span style={styles.taskDetailValue}>{formatTime(task.createdAt)}</span>
        </div>
        {task.startedAt && (
          <div style={styles.taskDetailItem}>
            <span style={styles.taskDetailLabel}>Started:</span>
            <span style={styles.taskDetailValue}>{formatTime(task.startedAt)}</span>
          </div>
        )}
        {task.estimatedDuration && (
          <div style={styles.taskDetailItem}>
            <span style={styles.taskDetailLabel}>Est. Duration:</span>
            <span style={styles.taskDetailValue}>{formatDuration(task.estimatedDuration)}</span>
          </div>
        )}
        {task.retryCount > 0 && (
          <div style={styles.taskDetailItem}>
            <span style={styles.taskDetailLabel}>Retries:</span>
            <span style={styles.taskDetailValue}>
              {task.retryCount} / {task.maxRetries}
            </span>
          </div>
        )}
      </div>

      {task.error && (
        <div style={styles.errorInfo}>
          <span style={styles.errorIcon}>⚠️</span>
          <span style={styles.errorMessage}>{task.error.message}</span>
        </div>
      )}
    </div>
  );
};

'use client';

import { useCallback } from 'react';
import ReactFlow, {
  Node as FlowNode,
  Controls,
  Background,
  useNodesState,
  useEdgesState,
  addEdge,
  Connection as FlowConnection,
  MiniMap,
  BackgroundVariant,
  NodeTypes,
} from 'reactflow';
import 'reactflow/dist/style.css';
import { Card } from '@/components/ui/card';
import type { GraphNode, GraphEdge } from '@/hooks/useProjects';

// Custom node component
function CustomNode({ data }: { data: any }) {
  const getHealthColor = (health: string) => {
    switch (health) {
      case 'healthy':
        return 'border-green-500 bg-green-50 dark:bg-green-950/30';
      case 'warning':
        return 'border-yellow-500 bg-yellow-50 dark:bg-yellow-950/30';
      case 'critical':
        return 'border-red-500 bg-red-50 dark:bg-red-950/30';
      default:
        return 'border-gray-500 bg-gray-50 dark:bg-gray-950/30';
    }
  };

  return (
    <div
      className={`px-4 py-2 rounded-md border-2 ${getHealthColor(
        data.health
      )} min-w-[120px]`}
    >
      <div className="font-semibold text-sm">{data.label}</div>
      {data.type && (
        <div className="text-xs text-muted-foreground mt-1">{data.type}</div>
      )}
      {data.complexity && (
        <div className="text-xs text-muted-foreground">
          Complexity: {data.complexity}
        </div>
      )}
    </div>
  );
}

const nodeTypes: NodeTypes = {
  custom: CustomNode,
};

interface ArchitectureGraphProps {
  nodes: GraphNode[];
  edges: GraphEdge[];
  onNodeClick?: (node: GraphNode) => void;
  highlightCircularDeps?: boolean;
}

export default function ArchitectureGraph({
  nodes: initialNodes,
  edges: initialEdges,
  onNodeClick,
  highlightCircularDeps = true,
}: ArchitectureGraphProps) {
  const [nodes, , onNodesChange] = useNodesState(
    initialNodes.map((node) => ({
      id: node.id,
      type: 'custom',
      data: {
        label: node.label,
        type: node.type,
        health: node.health,
        complexity: node.complexity,
      },
      position: node.position,
    }))
  );

  const [edges, setEdges, onEdgesChange] = useEdgesState(
    initialEdges.map((edge) => ({
      id: edge.id,
      source: edge.source,
      target: edge.target,
      type: edge.type || 'default',
      animated: edge.is_circular && highlightCircularDeps,
      style: {
        stroke:
          edge.is_circular && highlightCircularDeps ? '#ef4444' : '#94a3b8',
        strokeWidth: edge.is_circular && highlightCircularDeps ? 3 : 2,
      },
      label: edge.is_circular && highlightCircularDeps ? 'Circular' : undefined,
      labelStyle: {
        fill: '#ef4444',
        fontWeight: 700,
      },
    }))
  );

  const onConnect = useCallback(
    (params: FlowConnection) => setEdges((eds) => addEdge(params, eds)),
    [setEdges]
  );

  const handleNodeClick = useCallback(
    (_event: React.MouseEvent, node: FlowNode) => {
      const originalNode = initialNodes.find((n) => n.id === node.id);
      if (originalNode && onNodeClick) {
        onNodeClick(originalNode);
      }
    },
    [initialNodes, onNodeClick]
  );

  return (
    <Card className="w-full h-[600px] overflow-hidden">
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        onNodeClick={handleNodeClick}
        nodeTypes={nodeTypes}
        fitView
        attributionPosition="bottom-left"
      >
        <Background variant={BackgroundVariant.Dots} gap={12} size={1} />
        <Controls />
        <MiniMap
          nodeColor={(node) => {
            const health = node.data?.health;
            switch (health) {
              case 'healthy':
                return '#22c55e';
              case 'warning':
                return '#eab308';
              case 'critical':
                return '#ef4444';
              default:
                return '#94a3b8';
            }
          }}
          maskColor="rgba(0, 0, 0, 0.1)"
        />
      </ReactFlow>
    </Card>
  );
}

