'use client';

/**
 * Register Form Component with password strength indicator
 */
import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import Link from 'next/link';
import { Eye, EyeOff, Loader2, Check } from 'lucide-react';
import {
    registerSchema,
    type RegisterFormData,
    calculatePasswordStrength,
    getPasswordStrengthLabel,
    getPasswordStrengthColor,
} from '@/lib/validations/auth';
import { useRegister } from '@/hooks/useAuth';

export default function RegisterForm() {
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const { mutate: register, isPending, error } = useRegister();

    const {
        register: registerField,
        handleSubmit,
        watch,
        formState: { errors },
    } = useForm<RegisterFormData>({
        resolver: zodResolver(registerSchema),
        defaultValues: {
            acceptTerms: false,
        },
    });

    const password = watch('password');
    const passwordStrength = password ? calculatePasswordStrength(password) : 0;

    const onSubmit = (data: RegisterFormData) => {
        register(data);
    };

    return (
        <div className="w-full max-w-md space-y-8">
            <div className="text-center">
                <h2 className="text-3xl font-bold tracking-tight text-gray-900 dark:text-white">
                    Create your account
                </h2>
                <p className="mt-2 text-sm text-gray-600 dark:text-gray-400">
                    Join us and start analyzing your code today
                </p>
            </div>

            <form onSubmit={handleSubmit(onSubmit)} className="mt-8 space-y-6">
                {error && (
                    <div className="rounded-md bg-red-50 dark:bg-red-900/20 p-4">
                        <p className="text-sm text-red-800 dark:text-red-200">
                            {(error as any)?.response?.data?.detail || 'Registration failed. Please try again.'}
                        </p>
                    </div>
                )}

                <div className="space-y-4">
                    {/* Email Input */}
                    <div>
                        <label htmlFor="email" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                            Email address
                        </label>
                        <input
                            {...registerField('email')}
                            id="email"
                            type="email"
                            autoComplete="email"
                            className="mt-1 block w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 px-4 py-3 text-gray-900 dark:text-white placeholder-gray-400 focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500"
                            placeholder="you@example.com"
                        />
                        {errors.email && (
                            <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.email.message}</p>
                        )}
                    </div>

                    {/* Full Name Input */}
                    <div>
                        <label htmlFor="fullName" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                            Full name (optional)
                        </label>
                        <input
                            {...registerField('fullName')}
                            id="fullName"
                            type="text"
                            autoComplete="name"
                            className="mt-1 block w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 px-4 py-3 text-gray-900 dark:text-white placeholder-gray-400 focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500"
                            placeholder="John Doe"
                        />
                        {errors.fullName && (
                            <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.fullName.message}</p>
                        )}
                    </div>

                    {/* Password Input with Strength Indicator */}
                    <div>
                        <label htmlFor="password" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                            Password
                        </label>
                        <div className="relative mt-1">
                            <input
                                {...registerField('password')}
                                id="password"
                                type={showPassword ? 'text' : 'password'}
                                autoComplete="new-password"
                                className="block w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 px-4 py-3 pr-10 text-gray-900 dark:text-white placeholder-gray-400 focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500"
                                placeholder="••••••••"
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                            >
                                {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                            </button>
                        </div>

                        {/* Password Strength Indicator */}
                        {password && (
                            <div className="mt-2">
                                <div className="flex items-center gap-1">
                                    {[...Array(5)].map((_, i) => (
                                        <div
                                            key={i}
                                            className={`h-1.5 flex-1 rounded-full transition-colors ${i < passwordStrength ? getPasswordStrengthColor(passwordStrength) : 'bg-gray-200 dark:bg-gray-700'
                                                }`}
                                        />
                                    ))}
                                </div>
                                <p className="mt-1 text-xs text-gray-600 dark:text-gray-400">
                                    Password strength: <span className="font-medium">{getPasswordStrengthLabel(passwordStrength)}</span>
                                </p>
                            </div>
                        )}

                        {errors.password && (
                            <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.password.message}</p>
                        )}
                    </div>

                    {/* Confirm Password Input */}
                    <div>
                        <label htmlFor="confirmPassword" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                            Confirm password
                        </label>
                        <div className="relative mt-1">
                            <input
                                {...registerField('confirmPassword')}
                                id="confirmPassword"
                                type={showConfirmPassword ? 'text' : 'password'}
                                autoComplete="new-password"
                                className="block w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 px-4 py-3 pr-10 text-gray-900 dark:text-white placeholder-gray-400 focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500"
                                placeholder="••••••••"
                            />
                            <button
                                type="button"
                                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                            >
                                {showConfirmPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                            </button>
                        </div>
                        {errors.confirmPassword && (
                            <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.confirmPassword.message}</p>
                        )}
                    </div>
                </div>

                {/* Terms Acceptance */}
                <div className="flex items-start">
                    <div className="flex h-5 items-center">
                        <input
                            {...registerField('acceptTerms')}
                            id="acceptTerms"
                            type="checkbox"
                            className="h-4 w-4 rounded border-gray-300 text-primary-600 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800"
                        />
                    </div>
                    <label htmlFor="acceptTerms" className="ml-2 block text-sm text-gray-700 dark:text-gray-300">
                        I accept the{' '}
                        <Link href="/terms" className="font-medium text-primary-600 hover:text-primary-500 dark:text-primary-400">
                            Terms and Conditions
                        </Link>{' '}
                        and{' '}
                        <Link href="/privacy" className="font-medium text-primary-600 hover:text-primary-500 dark:text-primary-400">
                            Privacy Policy
                        </Link>
                    </label>
                </div>
                {errors.acceptTerms && (
                    <p className="text-sm text-red-600 dark:text-red-400">{errors.acceptTerms.message}</p>
                )}

                {/* Submit Button */}
                <button
                    type="submit"
                    disabled={isPending}
                    className="w-full flex justify-center items-center rounded-lg bg-primary-600 px-4 py-3 text-sm font-semibold text-white shadow-sm hover:bg-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                    {isPending ? (
                        <>
                            <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                            Creating account...
                        </>
                    ) : (
                        <>
                            <Check className="mr-2 h-5 w-5" />
                            Create account
                        </>
                    )}
                </button>

                {/* Login Link */}
                <p className="text-center text-sm text-gray-600 dark:text-gray-400">
                    Already have an account?{' '}
                    <Link
                        href="/auth/login"
                        className="font-medium text-primary-600 hover:text-primary-500 dark:text-primary-400"
                    >
                        Sign in
                    </Link>
                </p>
            </form>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/contexts/AuthContext';

interface LoginFormData {
  email: string;
  password: string;
}

interface LoginErrors {
  email?: string;
  password?: string;
  general?: string;
}

export default function SecureLogin() {
  const [formData, setFormData] = useState<LoginFormData>({
    email: '',
    password: ''
  });
  const [errors, setErrors] = useState<LoginErrors>({});
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [attemptCount, setAttemptCount] = useState(0);
  const [isLocked, setIsLocked] = useState(false);
  const [lockoutTime, setLockoutTime] = useState<Date | null>(null);

  const { login, isAuthenticated } = useAuth();
  const router = useRouter();

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated) {
      router.push('/dashboard');
    }
  }, [isAuthenticated, router]);

  // Handle lockout timer
  useEffect(() => {
    if (lockoutTime) {
      const timer = setInterval(() => {
        if (new Date() > lockoutTime) {
          setIsLocked(false);
          setLockoutTime(null);
          setAttemptCount(0);
        }
      }, 1000);

      return () => clearInterval(timer);
    }
  }, [lockoutTime]);

  const validateForm = (): boolean => {
    const newErrors: LoginErrors = {};

    // Email validation
    if (!formData.email) {
      newErrors.email = 'Email is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email address';
    }

    // Password validation
    if (!formData.password) {
      newErrors.password = 'Password is required';
    } else if (formData.password.length < 8) {
      newErrors.password = 'Password must be at least 8 characters';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (isLocked) {
      setErrors({ general: 'Account is temporarily locked. Please try again later.' });
      return;
    }

    if (!validateForm()) {
      return;
    }

    setIsLoading(true);
    setErrors({});

    try {
      await login(formData.email, formData.password);
      // Successful login - AuthContext will handle redirect
    } catch (error: any) {
      console.error('Login failed:', error);
      const newAttemptCount = attemptCount + 1;
      setAttemptCount(newAttemptCount);

      // Handle different error types
      if (error.response?.status === 429) {
        setErrors({ general: 'Too many login attempts. Please try again later.' });
        setIsLocked(true);
        setLockoutTime(new Date(Date.now() + 15 * 60 * 1000)); // 15 minutes
      } else if (error.response?.status === 403) {
        setErrors({ general: error.response.data.detail || 'Account is locked.' });
        setIsLocked(true);
      } else if (error.response?.status === 401) {
        setErrors({ general: 'Invalid email or password.' });
        
        // Client-side lockout after 5 attempts
        if (newAttemptCount >= 5) {
          setIsLocked(true);
          setLockoutTime(new Date(Date.now() + 15 * 60 * 1000));
          setErrors({ general: 'Too many failed attempts. Account locked for 15 minutes.' });
        }
      } else if (error.response?.status === 500) {
        // Handle server errors, including token issues
        const errorDetail = error.response.data.detail || 'Server error occurred.';
        if (errorDetail.includes('No token received')) {
          setErrors({ general: 'Authentication service error. Please try again or contact support.' });
        } else {
          setErrors({ general: errorDetail });
        }
      } else {
        // Handle network errors or other issues
        const errorMessage = error.message || 'Login failed. Please check your connection and try again.';
        setErrors({ general: errorMessage });
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    
    // Clear field-specific errors when user starts typing
    if (errors[name as keyof LoginErrors]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const getRemainingLockoutTime = (): string => {
    if (!lockoutTime) return '';
    
    const remaining = Math.max(0, lockoutTime.getTime() - Date.now());
    const minutes = Math.floor(remaining / 60000);
    const seconds = Math.floor((remaining % 60000) / 1000);
    
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md w-full space-y-8">
        <div>
          <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
            Sign in to your account
          </h2>
          <p className="mt-2 text-center text-sm text-gray-600">
            Enter your credentials to access the system
          </p>
        </div>
        
        <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
          <div className="rounded-md shadow-sm -space-y-px">
            <div>
              <label htmlFor="email" className="sr-only">
                Email address
              </label>
              <input
                id="email"
                name="email"
                type="email"
                autoComplete="email"
                required
                disabled={isLoading || isLocked}
                className={`appearance-none rounded-none relative block w-full px-3 py-2 border ${
                  errors.email ? 'border-red-300' : 'border-gray-300'
                } placeholder-gray-500 text-gray-900 rounded-t-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 focus:z-10 sm:text-sm disabled:bg-gray-100 disabled:cursor-not-allowed`}
                placeholder="Email address"
                value={formData.email}
                onChange={handleInputChange}
              />
              {errors.email && (
                <p className="mt-1 text-sm text-red-600">{errors.email}</p>
              )}
            </div>
            
            <div className="relative">
              <label htmlFor="password" className="sr-only">
                Password
              </label>
              <input
                id="password"
                name="password"
                type={showPassword ? 'text' : 'password'}
                autoComplete="current-password"
                required
                disabled={isLoading || isLocked}
                className={`appearance-none rounded-none relative block w-full px-3 py-2 pr-10 border ${
                  errors.password ? 'border-red-300' : 'border-gray-300'
                } placeholder-gray-500 text-gray-900 rounded-b-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 focus:z-10 sm:text-sm disabled:bg-gray-100 disabled:cursor-not-allowed`}
                placeholder="Password"
                value={formData.password}
                onChange={handleInputChange}
              />
              <button
                type="button"
                className="absolute inset-y-0 right-0 pr-3 flex items-center"
                onClick={() => setShowPassword(!showPassword)}
                disabled={isLoading || isLocked}
              >
                {showPassword ? (
                  <svg className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.878 9.878L3 3m6.878 6.878L21 21" />
                  </svg>
                ) : (
                  <svg className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                  </svg>
                )}
              </button>
              {errors.password && (
                <p className="mt-1 text-sm text-red-600">{errors.password}</p>
              )}
            </div>
          </div>

          {errors.general && (
            <div className="rounded-md bg-red-50 p-4">
              <div className="flex">
                <div className="flex-shrink-0">
                  <svg className="h-5 w-5 text-red-400" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                  </svg>
                </div>
                <div className="ml-3">
                  <p className="text-sm text-red-800">{errors.general}</p>
                  {isLocked && lockoutTime && (
                    <p className="text-sm text-red-600 mt-1">
                      Time remaining: {getRemainingLockoutTime()}
                    </p>
                  )}
                </div>
              </div>
            </div>
          )}

          {attemptCount > 0 && attemptCount < 5 && !isLocked && (
            <div className="rounded-md bg-yellow-50 p-4">
              <div className="flex">
                <div className="flex-shrink-0">
                  <svg className="h-5 w-5 text-yellow-400" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                  </svg>
                </div>
                <div className="ml-3">
                  <p className="text-sm text-yellow-800">
                    {5 - attemptCount} attempts remaining before account lockout
                  </p>
                </div>
              </div>
            </div>
          )}

          <div>
            <button
              type="submit"
              disabled={isLoading || isLocked}
              className="group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:bg-gray-400 disabled:cursor-not-allowed"
            >
              {isLoading ? (
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              ) : null}
              {isLoading ? 'Signing in...' : isLocked ? 'Account Locked' : 'Sign in'}
            </button>
          </div>

          <div className="text-center">
            <a
              href="/register"
              className="font-medium text-indigo-600 hover:text-indigo-500"
            >
              Don't have an account? Sign up
            </a>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * Unit Tests for PermissionCheck Component
 */
import { render, screen } from '@testing-library/react';
import { PermissionCheck } from '../PermissionCheck';
import { Role, Permission } from '@/types/rbac';
import { useRole } from '@/hooks/useRole';
import { usePermission } from '@/hooks/usePermission';

// Mock dependencies
jest.mock('@/hooks/useRole');
jest.mock('@/hooks/usePermission');

const mockUseRole = useRole as jest.MockedFunction<typeof useRole>;
const mockUsePermission = usePermission as jest.MockedFunction<typeof usePermission>;

describe('PermissionCheck', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders children when permission requirement is met', () => {
    mockUseRole.mockReturnValue({
      hasRole: () => true,
      currentRole: Role.ADMIN,
      loading: false,
    });

    mockUsePermission.mockReturnValue({
      hasPermission: (perm: Permission) => perm === Permission.MODIFY_CONFIG,
      loading: false,
    });

    render(
      <PermissionCheck permission={Permission.MODIFY_CONFIG}>
        <button>Delete</button>
      </PermissionCheck>
    );

    expect(screen.getByText('Delete')).toBeInTheDocument();
  });

  it('renders fallback when permission requirement is not met', () => {
    mockUseRole.mockReturnValue({
      hasRole: () => false,
      currentRole: Role.VISITOR,
      loading: false,
    });

    mockUsePermission.mockReturnValue({
      hasPermission: (perm: Permission) => perm !== Permission.DELETE_PROJECT,
      loading: false,
    });

    render(
      <PermissionCheck
        permission={Permission.DELETE_PROJECT}
        fallback={<span>Not authorized</span>}
      >
        <button>Delete</button>
      </PermissionCheck>
    );

    expect(screen.queryByText('Delete')).not.toBeInTheDocument();
    expect(screen.getByText('Not authorized')).toBeInTheDocument();
  });

  it('renders children when role requirement is met', () => {
    mockUseRole.mockReturnValue({
      hasRole: (role: Role) => role === Role.ADMIN,
      currentRole: Role.ADMIN,
      loading: false,
    });

    mockUsePermission.mockReturnValue({
      hasPermission: () => true,
      loading: false,
    });

    render(
      <PermissionCheck role={Role.ADMIN}>
        <div>Admin Panel</div>
      </PermissionCheck>
    );

    expect(screen.getByText('Admin Panel')).toBeInTheDocument();
  });

  it('renders fallback when role requirement is not met', () => {
    mockUseRole.mockReturnValue({
      hasRole: (role: Role) => role === Role.PROGRAMMER,
      currentRole: Role.PROGRAMMER,
      loading: false,
    });

    mockUsePermission.mockReturnValue({
      hasPermission: () => false,
      loading: false,
    });

    render(
      <PermissionCheck role={Role.ADMIN} fallback={null}>
        <div>Admin Panel</div>
      </PermissionCheck>
    );

    expect(screen.queryByText('Admin Panel')).not.toBeInTheDocument();
  });

  it('renders fallback while loading', () => {
    mockUseRole.mockReturnValue({
      hasRole: () => false,
      currentRole: null,
      loading: true,
    });

    mockUsePermission.mockReturnValue({
      hasPermission: () => false,
      loading: true,
    });

    render(
      <PermissionCheck
        permission={Permission.MODIFY_CONFIG}
        fallback={<span>Loading...</span>}
      >
        <button>Settings</button>
      </PermissionCheck>
    );

    expect(screen.queryByText('Settings')).not.toBeInTheDocument();
    expect(screen.getByText('Loading...')).toBeInTheDocument();
  });

  it('renders children when both role and permission requirements are met', () => {
    mockUseRole.mockReturnValue({
      hasRole: (role: Role) => role === Role.ADMIN,
      currentRole: Role.ADMIN,
      loading: false,
    });

    mockUsePermission.mockReturnValue({
      hasPermission: () => true,
      loading: false,
    });

    render(
      <PermissionCheck role={Role.ADMIN} permission={Permission.DELETE_USER}>
        <button>Delete User</button>
      </PermissionCheck>
    );

    expect(screen.getByText('Delete User')).toBeInTheDocument();
  });

  it('hides UI elements without required permissions (Property 21)', () => {
    mockUseRole.mockReturnValue({
      hasRole: (role: Role) => role === Role.VISITOR,
      currentRole: Role.VISITOR,
      loading: false,
    });

    mockUsePermission.mockReturnValue({
      hasPermission: (perm: Permission) => 
        perm === Permission.VIEW_PROJECTS || perm === Permission.VIEW_REVIEWS,
      loading: false,
    });

    const { container } = render(
      <div>
        <PermissionCheck permission={Permission.DELETE_PROJECT}>
          <button>Delete</button>
        </PermissionCheck>
        <PermissionCheck permission={Permission.MODIFY_CONFIG}>
          <button>Configure</button>
        </PermissionCheck>
        <PermissionCheck permission={Permission.VIEW_PROJECTS}>
          <button>View</button>
        </PermissionCheck>
      </div>
    );

    // Delete and Configure buttons should be hidden
    expect(screen.queryByText('Delete')).not.toBeInTheDocument();
    expect(screen.queryByText('Configure')).not.toBeInTheDocument();
    
    // View button should be visible
    expect(screen.getByText('View')).toBeInTheDocument();
  });
});

/**
 * Property-Based Tests for RBACGuard Component
 * Tests universal properties across all inputs
 */
import { render, waitFor } from '@testing-library/react';
import { useRouter } from 'next/navigation';
import * as fc from 'fast-check';
import { RBACGuard } from '../RBACGuard';
import { Role, Permission } from '@/types/rbac';
import { useAuth } from '@/contexts/AuthContext';
import { useRole } from '@/hooks/useRole';
import { usePermission } from '@/hooks/usePermission';

// Mock dependencies
jest.mock('next/navigation');
jest.mock('@/contexts/AuthContext');
jest.mock('@/hooks/useRole');
jest.mock('@/hooks/usePermission');
jest.mock('lucide-react', () => ({
  Loader2: () => <div role="status">Loading...</div>,
}));

const mockPush = jest.fn();
const mockUseRouter = useRouter as jest.MockedFunction<typeof useRouter>;
const mockUseAuth = useAuth as jest.MockedFunction<typeof useAuth>;
const mockUseRole = useRole as jest.MockedFunction<typeof useRole>;
const mockUsePermission = usePermission as jest.MockedFunction<typeof usePermission>;

describe('RBACGuard Property Tests', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockUseRouter.mockReturnValue({ push: mockPush } as any);
  });

  /**
   * Feature: enterprise-rbac-authentication, Property 19: Non-Admins cannot access admin routes
   * For any user with a role other than Admin, attempting to navigate to routes under /admin
   * should result in redirection to an unauthorized page.
   * Validates: Requirements 5.1
   */
  it('Property 19: Non-Admin users are redirected from admin routes', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.constantFrom(Role.PROGRAMMER, Role.VISITOR),
        fc.string({ minLength: 1 }),
        async (userRole, userId) => {
          // Setup: User with non-admin role
          mockUseAuth.mockReturnValue({
            user: { id: userId, role: userRole } as any,
            session: { user: { id: userId, role: userRole } } as any,
            loading: false,
            role: userRole,
            permissions: [],
            login: jest.fn(),
            register: jest.fn(),
            logout: jest.fn(),
            refreshToken: jest.fn(),
          });

          mockUseRole.mockReturnValue({
            hasRole: (role: Role) => role === userRole,
            currentRole: userRole,
            loading: false,
          });

          mockUsePermission.mockReturnValue({
            hasPermission: () => false,
            loading: false,
          });

          // Render with admin role requirement
          render(
            <RBACGuard requiredRole={Role.ADMIN}>
              <div>Admin Content</div>
            </RBACGuard>
          );

          // Verify: Should redirect to unauthorized
          await waitFor(() => {
            expect(mockPush).toHaveBeenCalledWith('/unauthorized');
          });
        }
      ),
      { numRuns: 50 }
    );
  });

  /**
   * Feature: enterprise-rbac-authentication, Property 20: Users without config permissions cannot access settings
   * For any user without the MODIFY_CONFIG permission, attempting to navigate to /settings routes
   * should result in redirection to an unauthorized page.
   * Validates: Requirements 5.2
   */
  it('Property 20: Users without MODIFY_CONFIG cannot access settings', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.constantFrom(Role.PROGRAMMER, Role.VISITOR),
        fc.string({ minLength: 1 }),
        async (userRole, userId) => {
          // Setup: User without MODIFY_CONFIG permission
          mockUseAuth.mockReturnValue({
            user: { id: userId, role: userRole } as any,
            session: { user: { id: userId, role: userRole } } as any,
            loading: false,
            role: userRole,
            permissions: [],
            login: jest.fn(),
            register: jest.fn(),
            logout: jest.fn(),
            refreshToken: jest.fn(),
          });

          mockUseRole.mockReturnValue({
            hasRole: (role: Role) => role === userRole,
            currentRole: userRole,
            loading: false,
          });

          mockUsePermission.mockReturnValue({
            hasPermission: (perm: Permission) => perm !== Permission.MODIFY_CONFIG,
            loading: false,
          });

          // Render with MODIFY_CONFIG permission requirement
          render(
            <RBACGuard requiredPermission={Permission.MODIFY_CONFIG}>
              <div>Settings Content</div>
            </RBACGuard>
          );

          // Verify: Should redirect to unauthorized
          await waitFor(() => {
            expect(mockPush).toHaveBeenCalledWith('/unauthorized');
          });
        }
      ),
      { numRuns: 50 }
    );
  });

  /**
   * Feature: enterprise-rbac-authentication, Property 22: Expired sessions redirect to login
   * For any route navigation with an expired session token, the route guard should redirect
   * the user to the login page.
   * Validates: Requirements 5.4
   */
  it('Property 22: Expired sessions redirect to login', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.constantFrom(Role.ADMIN, Role.PROGRAMMER, Role.VISITOR),
        async (userRole) => {
          // Setup: No session (expired)
          mockUseAuth.mockReturnValue({
            user: null,
            session: null,
            loading: false,
            role: null,
            permissions: [],
            login: jest.fn(),
            register: jest.fn(),
            logout: jest.fn(),
            refreshToken: jest.fn(),
          });

          mockUseRole.mockReturnValue({
            hasRole: () => false,
            currentRole: null,
            loading: false,
          });

          mockUsePermission.mockReturnValue({
            hasPermission: () => false,
            loading: false,
          });

          // Render with any role requirement
          render(
            <RBACGuard requiredRole={userRole}>
              <div>Protected Content</div>
            </RBACGuard>
          );

          // Verify: Should redirect to login
          await waitFor(() => {
            expect(mockPush).toHaveBeenCalledWith('/login');
          });
        }
      ),
      { numRuns: 50 }
    );
  });

  /**
   * Additional property: Admin users can access all routes
   */
  it('Property: Admin users can access admin-protected routes', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.string({ minLength: 1 }),
        async (userId) => {
          // Setup: Admin user
          mockUseAuth.mockReturnValue({
            user: { id: userId, role: Role.ADMIN } as any,
            session: { user: { id: userId, role: Role.ADMIN } } as any,
            loading: false,
            role: Role.ADMIN,
            permissions: [Permission.MODIFY_CONFIG],
            login: jest.fn(),
            register: jest.fn(),
            logout: jest.fn(),
            refreshToken: jest.fn(),
          });

          mockUseRole.mockReturnValue({
            hasRole: (role: Role) => role === Role.ADMIN,
            currentRole: Role.ADMIN,
            loading: false,
          });

          mockUsePermission.mockReturnValue({
            hasPermission: () => true,
            loading: false,
          });

          // Render with admin role requirement
          const { container } = render(
            <RBACGuard requiredRole={Role.ADMIN}>
              <div data-testid="admin-content">Admin Content</div>
            </RBACGuard>
          );

          // Verify: Should NOT redirect
          await waitFor(() => {
            expect(mockPush).not.toHaveBeenCalled();
            expect(container.textContent).toContain('Admin Content');
          });
        }
      ),
      { numRuns: 50 }
    );
  });
});

/**
 * RouteGuard Component Tests
 * Tests authentication and authorization protection
 */
import { render, screen, waitFor } from '@testing-library/react';
import { useRouter, usePathname } from 'next/navigation';
import { RouteGuard } from '../RouteGuard';
import { useAuth } from '@/contexts/AuthContext';
import { Role, Permission } from '@/types/rbac';

// Mock Next.js navigation
jest.mock('next/navigation', () => ({
  useRouter: jest.fn(),
  usePathname: jest.fn(),
}));

// Mock AuthContext
jest.mock('@/contexts/AuthContext', () => ({
  useAuth: jest.fn(),
}));

describe('RouteGuard', () => {
  const mockPush = jest.fn();
  const mockUseRouter = useRouter as jest.MockedFunction<typeof useRouter>;
  const mockUsePathname = usePathname as jest.MockedFunction<typeof usePathname>;
  const mockUseAuth = useAuth as jest.MockedFunction<typeof useAuth>;

  beforeEach(() => {
    jest.clearAllMocks();
    mockUseRouter.mockReturnValue({ push: mockPush } as any);
    mockUsePathname.mockReturnValue('/protected');
  });

  describe('Loading State', () => {
    it('should show loading spinner while authentication is loading', () => {
      mockUseAuth.mockReturnValue({
        user: null,
        loading: true,
        isAuthenticated: false,
        permissions: [],
        role: null,
        login: jest.fn(),
        register: jest.fn(),
        logout: jest.fn(),
        refreshToken: jest.fn(),
      });

      render(
        <RouteGuard>
          <div>Protected Content</div>
        </RouteGuard>
      );

      // Check for loading spinner by class name
      const loadingSpinner = document.querySelector('.animate-spin');
      expect(loadingSpinner).toBeInTheDocument();
      expect(screen.queryByText('Protected Content')).not.toBeInTheDocument();
    });
  });

  describe('Authentication - Requirement 3.4', () => {
    it('should redirect unauthenticated users to login page', async () => {
      mockUseAuth.mockReturnValue({
        user: null,
        loading: false,
        isAuthenticated: false,
        permissions: [],
        role: null,
        login: jest.fn(),
        register: jest.fn(),
        logout: jest.fn(),
        refreshToken: jest.fn(),
      });

      render(
        <RouteGuard>
          <div>Protected Content</div>
        </RouteGuard>
      );

      await waitFor(() => {
        expect(mockPush).toHaveBeenCalledWith('/login?returnUrl=%2Fprotected');
      });

      expect(screen.queryByText('Protected Content')).not.toBeInTheDocument();
    });

    it('should redirect to custom path when redirectTo is specified', async () => {
      mockUseAuth.mockReturnValue({
        user: null,
        loading: false,
        isAuthenticated: false,
        permissions: [],
        role: null,
        login: jest.fn(),
        register: jest.fn(),
        logout: jest.fn(),
        refreshToken: jest.fn(),
      });

      render(
        <RouteGuard redirectTo="/custom-login">
          <div>Protected Content</div>
        </RouteGuard>
