          {/* Complexity Range */}
          <div className="space-y-2">
            <Label>Complexity Range: {filters.minComplexity} - {filters.maxComplexity}</Label>
            <div className="flex space-x-2">
              <Input
                type="range"
                min="0"
                max="20"
                value={filters.minComplexity}
                onChange={(e) => setFilters({...filters, minComplexity: parseInt(e.target.value)})}
                className="flex-1"
              />
              <Input
                type="range"
                min="0"
                max="20"
                value={filters.maxComplexity}
                onChange={(e) => setFilters({...filters, maxComplexity: parseInt(e.target.value)})}
                className="flex-1"
              />
            </div>
          </div>
        </div>

        {/* Legend */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
          {/* Node Types Legend */}
          <div className="space-y-2">
            <Label>Node Types</Label>
            <div className="grid grid-cols-2 gap-2">
              {['layer', 'module', 'file', 'class', 'function'].map(type => (
                <div key={type} className="flex items-center space-x-2 p-2 bg-gray-50 rounded">
                  <span>{getNodeTypeIcon(type)}</span>
                  <span className="text-sm capitalize">{type}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Drift Legend */}
          <div className="space-y-2">
            <Label>Architectural Drift</Label>
            <div className="space-y-1">
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-green-500 rounded-full"></div>
                <span className="text-sm">No Drift</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-yellow-500 rounded-full"></div>
                <span className="text-sm">Low Risk Drift</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-orange-500 rounded-full"></div>
                <span className="text-sm">Medium Risk Drift</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-red-500 rounded-full"></div>
                <span className="text-sm">High Risk Drift</span>
              </div>
            </div>
          </div>

          {/* Link Types Legend */}
          <div className="space-y-2">
            <Label>Dependencies</Label>
            <div className="space-y-1">
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-green-500 rounded-full"></div>
                <span className="text-sm">Normal Dependency</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-blue-500 rounded-full"></div>
                <span className="text-sm">Inheritance</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-orange-500 rounded-full"></div>
                <span className="text-sm">Function Call</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-red-500 rounded-full"></div>
                <span className="text-sm">Cross-Layer Import</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-gray-500 rounded-full"></div>
                <span className="text-sm">Containment</span>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="space-y-2">
            <Label>Actions</Label>
            <div className="flex space-x-2">
              <Button variant="outline" size="sm" onClick={resetView}>
                <ZoomOut className="h-4 w-4 mr-2" />
                Reset View
              </Button>
              <Button variant="outline" size="sm" onClick={applyForceLayout}>
                <RefreshCw className="h-4 w-4 mr-2" />
                Re-layout
              </Button>
            </div>
          </div>
        </div>

        {/* Graph Container */}
        <div 
          ref={graphRef}
          className="w-full h-[600px] border border-gray-200 rounded-lg bg-white relative"
        >
          {isLoading ? (
            <div className="absolute inset-0 flex items-center justify-center bg-gray-50">
              <div className="text-center">
                <Loader2 className="h-12 w-12 animate-spin text-blue-600 mx-auto mb-4" />
                <p className="text-lg font-medium text-gray-700">Loading architecture graph...</p>
                <p className="mt-2 text-sm text-gray-500">Fetching data from server</p>
              </div>
            </div>
          ) : error ? (
            <div className="absolute inset-0 flex items-center justify-center bg-gray-50">
              <div className="text-center max-w-md px-4">
                <AlertTriangle className="h-12 w-12 mx-auto mb-4 text-red-600" />
                <h3 className="text-lg font-semibold text-gray-900 mb-2">Failed to Load Architecture Graph</h3>
                <p className="text-sm text-gray-600 mb-4">
                  {ErrorHandler.getUserMessage(ErrorHandler.handleError(error))}
                </p>
                <Button onClick={() => refetch()} variant="default">
                  <RefreshCw className="h-4 w-4 mr-2" />
                  Retry
                </Button>
              </div>
            </div>
          ) : (
            <div className="w-full h-full relative">
              {/* Simple SVG-based graph visualization placeholder */}
              <svg className="w-full h-full">
                {/* Links */}
                {filteredLinks.map((link, index) => {
                  const sourceNode = filteredNodes.find(n => n.id === link.source);
                  const targetNode = filteredNodes.find(n => n.id === link.target);
                  
                  if (!sourceNode || !targetNode) return null;

                  // Use position from API data if available, otherwise use deterministic layout
                  const sourceIdx = filteredNodes.findIndex(n => n.id === link.source);
                  const targetIdx = filteredNodes.findIndex(n => n.id === link.target);
                  
                  // Get positions from API data or calculate deterministic positions
                  const sourcePos = nodes.find(n => n.id === link.source)?.position;
                  const targetPos = nodes.find(n => n.id === link.target)?.position;
                  
                  const x1 = sourcePos?.x ?? ((sourceIdx * 137) % 700) + 50;
                  const y1 = sourcePos?.y ?? ((sourceIdx * 211) % 500) + 50;
                  const x2 = targetPos?.x ?? ((targetIdx * 137) % 700) + 50;
                  const y2 = targetPos?.y ?? ((targetIdx * 211) % 500) + 50;

                  return (
                    <line
                      key={index}
                      x1={x1}
                      y1={y1}
                      x2={x2}
                      y2={y2}
                      stroke={getLinkColor(link)}
                      strokeWidth={link.weight * 2}
                      opacity="0.6"
                    />
                  );
                })}

                {/* Nodes */}
                {filteredNodes.map((node, nodeIndex) => {
                  // Use position from API data if available, otherwise use deterministic layout
                  const apiNode = nodes.find(n => n.id === node.id);
                  const nodePos = apiNode?.position;
                  
                  const x = nodePos?.x ?? ((nodeIndex * 137) % 700) + 50;
                  const y = nodePos?.y ?? ((nodeIndex * 211) % 500) + 50;

                  return (
                    <g key={node.id} transform={`translate(${x}, ${y})`}>
                      {/* Drift indicator */}
                      {node.isDrift && (
                        <circle
                          r={getNodeSize(node) + 10}
                          fill="none"
                          stroke={getDriftSeverity(node) === 'high' ? '#ef4444' : getDriftSeverity(node) === 'medium' ? '#f59e0b' : '#eab308'}
                          strokeWidth="2"
                          opacity="0.8"
                          className="animate-pulse"
                        />
                      )}
                      
                      {/* Node */}
                      <circle
                        r={getNodeSize(node) / 10}
                        fill={getNodeTypeColor(node)}
                        opacity="0.8"
                        className="cursor-pointer hover:opacity-100 transition-opacity"
                        onClick={() => handleNodeClick({ id: node.id })}
                      />
                      
                      {/* Node label */}
                      <text
                        x="0"
                        y={getNodeSize(node) / 5}
                        textAnchor="middle"
                        fontSize="10"
                        fill="#333"
                        className="pointer-events-none"
                      >
                        {node.name}
                      </text>
                      
                      {/* Complexity indicator */}
                      {node.complexity && (
                        <text
                          x="0"
                          y={getNodeSize(node) / 2.5}
                          textAnchor="middle"
                          fontSize="8"
                          fill={node.complexity > 10 ? "#ef4444" : "#6b7280"}
                          className="pointer-events-none"
                        >
                          C:{node.complexity}
                        </text>
                      )}
                    </g>
                  );
                })}
              </svg>

              {/* Controls Overlay */}
              <div className="absolute top-2 right-2 flex space-x-2">
                <Button variant="outline" size="sm" className="bg-white">
                  <ZoomIn className="h-4 w-4" />
                </Button>
                <Button variant="outline" size="sm" className="bg-white">
                  <ZoomOut className="h-4 w-4" />
                </Button>
              </div>

              {/* Statistics Overlay */}
              <div className="absolute bottom-2 left-2 bg-white p-2 rounded border">
                <div className="text-xs text-gray-600">
                  <div>Nodes: {filteredNodes.length}</div>
                  <div>Links: {filteredLinks.length}</div>
                  <div>Drift Nodes: {filteredNodes.filter(n => n.isDrift).length}</div>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Statistics Overlay */}
        <div className="mt-4 grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-gray-50 p-4 rounded-lg">
            <h4 className="font-semibold mb-2">Total Nodes</h4>
            <p className="text-2xl font-bold">{filteredNodes.length}</p>
          </div>
          <div className="bg-gray-50 p-4 rounded-lg">
            <h4 className="font-semibold mb-2">Total Links</h4>
            <p className="text-2xl font-bold">{filteredLinks.length}</p>
          </div>
          <div className="bg-gray-50 p-4 rounded-lg">
            <h4 className="font-semibold mb-2">Drift Nodes</h4>
            <p className="text-2xl font-bold text-red-600">{filteredNodes.filter(n => n.isDrift).length}</p>
          </div>
          <div className="bg-gray-50 p-4 rounded-lg">
            <h4 className="font-semibold mb-2">High Complexity</h4>
            <p className="text-2xl font-bold text-orange-600">{filteredNodes.filter(n => n.complexity && n.complexity > 10).length}</p>
          </div>
        </div>

        {/* Selected Node Details */}
        {selectedNode && (
          <div className="mt-4 p-4 bg-gray-50 rounded-lg">
            <h3 className="font-semibold mb-2">Selected Component</h3>
            {(() => {
              const node = filteredNodes.find(n => n.id === selectedNode);
              if (!node) return null;
              
              return (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <span className="text-sm text-gray-600">Name</span>
                    <div className="font-medium">{node.name}</div>
                  </div>
                  <div>
                    <span className="text-sm text-gray-600">Type</span>
                    <div className="font-medium capitalize">{node.type}</div>
                  </div>
                  <div>
                    <span className="text-sm text-gray-600">Layer</span>
                    <div className="font-medium">{node.layer || 'Unknown'}</div>
                  </div>
                  {node.complexity && (
                    <div>
                      <span className="text-sm text-gray-600">Complexity</span>
                      <div className="font-medium">{node.complexity}</div>
                    </div>
                  )}
                  <div>
                    <span className="text-sm text-gray-600">Architectural Drift</span>
                    <div className={`font-medium ${node.isDrift ? 'text-red-600' : 'text-green-600'}`}>
                      {node.isDrift ? 'Yes' : 'No'}
                    </div>
                  </div>
                  <div>
                    <span className="text-sm text-gray-600">Drift Severity</span>
                    <div className="font-medium">
                      <Badge variant={getDriftSeverity(node) === 'high' ? 'destructive' : getDriftSeverity(node) === 'medium' ? 'default' : 'secondary'}>
                        {getDriftSeverity(node)}
                      </Badge>
                    </div>
                  </div>
                </div>
              );
            })()}
          </div>
        )}
          </>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

/**
 * Architecture Evolution Timeline using D3.js
 */
import { useEffect, useRef } from 'react';
import * as d3 from 'd3';

interface TimelineDataPoint {
    date: Date;
    coupling: number;
    complexity: number;
    coverage: number;
    loc: number;
}

interface TimelineEvent {
    date: Date;
    label: string;
    type: 'release' | 'refactor' | 'migration';
}

interface ArchitectureTimelineProps {
    data: TimelineDataPoint[];
    events?: TimelineEvent[];
    width?: number;
    height?: number;
}

export default function ArchitectureTimeline({
    data,
    events = [],
    width = 1000,
    height = 400,
}: ArchitectureTimelineProps) {
    const svgRef = useRef<SVGSVGElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!svgRef.current || data.length === 0) return;

        // Clear previous content
        d3.select(svgRef.current).selectAll('*').remove();

        const margin = { top: 20, right: 120, bottom: 60, left: 60 };
        const innerWidth = width - margin.left - margin.right;
        const innerHeight = height - margin.top - margin.bottom;

        const svg = d3
            .select(svgRef.current)
            .attr('width', width)
            .attr('height', height)
            .attr('viewBox', `0 0 ${width} ${height}`)
            .attr('preserveAspectRatio', 'xMidYMid meet');

        const g = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`);

        // Scales
        const xScale = d3
            .scaleTime()
            .domain(d3.extent(data, (d) => d.date) as [Date, Date])
            .range([0, innerWidth]);

        const yScale = d3
            .scaleLinear()
            .domain([0, d3.max(data, (d) => Math.max(d.complexity, d.coupling, d.coverage, d.loc / 100)) || 100])
            .nice()
            .range([innerHeight, 0]);

        // Axes
        const xAxis = d3.axisBottom(xScale).ticks(6).tickFormat(d3.timeFormat('%b %Y') as any);
        const yAxis = d3.axisLeft(yScale);

        g.append('g')
            .attr('class', 'x-axis')
            .attr('transform', `translate(0,${innerHeight})`)
            .call(xAxis)
            .selectAll('text')
            .style('fill', 'currentColor');

        g.append('g').attr('class', 'y-axis').call(yAxis).selectAll('text').style('fill', 'currentColor');

        // Grid lines
        g.append('g')
            .attr('class', 'grid')
            .attr('opacity', 0.1)
            .call(d3.axisLeft(yScale).tickSize(-innerWidth).tickFormat('' as any));

        // Line generators
        const lineGenerators = {
            coupling: d3
                .line<TimelineDataPoint>()
                .x((d) => xScale(d.date))
                .y((d) => yScale(d.coupling))
                .curve(d3.curveMonotoneX),
            complexity: d3
                .line<TimelineDataPoint>()
                .x((d) => xScale(d.date))
                .y((d) => yScale(d.complexity))
                .curve(d3.curveMonotoneX),
            coverage: d3
                .line<TimelineDataPoint>()
                .x((d) => xScale(d.date))
                .y((d) => yScale(d.coverage))
                .curve(d3.curveMonotoneX),
            loc: d3
                .line<TimelineDataPoint>()
                .x((d) => xScale(d.date))
                .y((d) => yScale(d.loc / 100))
                .curve(d3.curveMonotoneX),
        };

        const metrics = [
            { key: 'coupling', color: '#ef4444', label: 'Coupling Score' },
            { key: 'complexity', color: '#f59e0b', label: 'Complexity' },
            { key: 'coverage', color: '#10b981', label: 'Test Coverage' },
            { key: 'loc', color: '#3b82f6', label: 'LOC (÷100)' },
        ];

        // Draw lines
        metrics.forEach((metric) => {
            g.append('path')
                .datum(data)
                .attr('class', `line-${metric.key}`)
                .attr('fill', 'none')
                .attr('stroke', metric.color)
                .attr('stroke-width', 2)
                .attr('d', lineGenerators[metric.key as keyof typeof lineGenerators]);
        });

        // Add dots
        metrics.forEach((metric) => {
            g.selectAll(`.dot-${metric.key}`)
                .data(data)
                .enter()
                .append('circle')
                .attr('class', `dot-${metric.key}`)
                .attr('cx', (d) => xScale(d.date))
                .attr('cy', (d) => yScale(d[metric.key as keyof TimelineDataPoint] as number || 0))
                .attr('r', 3)
                .attr('fill', metric.color)
                .style('cursor', 'pointer')
                .on('mouseover', function (_event, d: any) {
                    d3.select(this).attr('r', 5);

                    // Tooltip
                    const tooltip = g
                        .append('g')
                        .attr('class', 'tooltip')
                        .attr('transform', `translate(${xScale(d.date)},${yScale(d[metric.key]) - 40})`);

                    tooltip
                        .append('rect')
                        .attr('x', -60)
                        .attr('y', -25)
                        .attr('width', 120)
                        .attr('height', 30)
                        .attr('fill', 'rgba(0,0,0,0.8)')
                        .attr('rx', 4);

                    tooltip
                        .append('text')
                        .attr('text-anchor', 'middle')
                        .attr('fill', 'white')
                        .attr('font-size', '12px')
                        .text(`${metric.label}: ${d[metric.key]}`);
                })
                .on('mouseout', function () {
                    d3.select(this).attr('r', 3);
                    g.selectAll('.tooltip').remove();
                });
        });

        // Event markers
        events.forEach((event) => {
            const x = xScale(event.date);

            g.append('line')
                .attr('x1', x)
                .attr('x2', x)
                .attr('y1', 0)
                .attr('y2', innerHeight)
                .attr('stroke', event.type === 'release' ? '#8b5cf6' : '#6366f1')
                .attr('stroke-width', 2)
                .attr('stroke-dasharray', '4,4')
                .attr('opacity', 0.5);

            g.append('text')
                .attr('x', x)
                .attr('y', -5)
                .attr('text-anchor', 'middle')
                .attr('font-size', '10px')
                .attr('fill', 'currentColor')
                .text(event.label);
        });

        // Legend
        const legend = g
            .append('g')
            .attr('class', 'legend')
            .attr('transform', `translate(${innerWidth + 10}, 0)`);

        metrics.forEach((metric, i) => {
            const legendRow = legend.append('g').attr('transform', `translate(0, ${i * 20})`);

            legendRow.append('line').attr('x1', 0).attr('x2', 20).attr('stroke', metric.color).attr('stroke-width', 2);

            legendRow
                .append('text')
                .attr('x', 25)
                .attr('y', 4)
                .attr('font-size', '12px')
                .attr('fill', 'currentColor')
                .text(metric.label);
        });

        // Brush for date range selection
        const brush = d3
            .brushX()
            .extent([
                [0, 0],
                [innerWidth, innerHeight],
            ])
            .on('end', (event) => {
                if (event.selection) {
                    const [x0, x1] = event.selection;
                    const dateRange = [xScale.invert(x0), xScale.invert(x1)];
                    console.log('Selected date range:', dateRange);
                }
            });

        g.append('g').attr('class', 'brush').call(brush);
    }, [data, events, width, height]);

    return (
        <div ref={containerRef} className="w-full overflow-x-auto">
            <svg ref={svgRef} className="text-gray-700 dark:text-gray-300" />
        </div>
    );
}

/**
 * Graph Virtualization Utilities
 * 
 * Provides level-of-detail rendering and virtualization for large graphs (>1000 nodes)
 * Ensures rendering completes within 5 seconds
 * 
 * Requirements: 1.8, 3.7
 */

export interface VirtualizedNode {
  id: string;
  name: string;
  type: string;
  size: number;
  x?: number;
  y?: number;
  visible: boolean;
  lod: 'high' | 'medium' | 'low';
  [key: string]: any;
}

export interface VirtualizedLink {
  source: string | VirtualizedNode;
  target: string | VirtualizedNode;
  visible: boolean;
  [key: string]: any;
}

export interface ViewportBounds {
  minX: number;
  maxX: number;
  minY: number;
  maxY: number;
}

export interface VirtualizationConfig {
  nodeThreshold: number; // Threshold for enabling virtualization
  viewportPadding: number; // Extra space around viewport
  lodDistances: {
    high: number; // Distance for high detail
    medium: number; // Distance for medium detail
    low: number; // Distance for low detail
  };
}

const DEFAULT_CONFIG: VirtualizationConfig = {
  nodeThreshold: 1000,
  viewportPadding: 200,
  lodDistances: {
    high: 500,
    medium: 1000,
    low: 2000
  }
};

/**
 * Determines if virtualization should be enabled based on graph size
 */
export function shouldEnableVirtualization(
  nodeCount: number,
  config: VirtualizationConfig = DEFAULT_CONFIG
): boolean {
  return nodeCount > config.nodeThreshold;
}

/**
 * Calculates viewport bounds based on camera position and zoom
 */
export function calculateViewportBounds(
  cameraX: number,
  cameraY: number,
  zoom: number,
  width: number,
  height: number,
  padding: number = DEFAULT_CONFIG.viewportPadding
): ViewportBounds {
  const halfWidth = (width / zoom) / 2 + padding;
  const halfHeight = (height / zoom) / 2 + padding;

  return {
    minX: cameraX - halfWidth,
    maxX: cameraX + halfWidth,
    minY: cameraY - halfHeight,
    maxY: cameraY + halfHeight
  };
}

/**
 * Checks if a node is within the viewport bounds
 */
export function isNodeInViewport(
  node: VirtualizedNode,
  bounds: ViewportBounds
): boolean {
  if (node.x === undefined || node.y === undefined) return false;

  return (
    node.x >= bounds.minX &&
    node.x <= bounds.maxX &&
    node.y >= bounds.minY &&
    node.y <= bounds.maxY
  );
}

/**
 * Calculates distance from camera center to node
 */
export function calculateNodeDistance(
  node: VirtualizedNode,
  cameraX: number,
  cameraY: number
): number {
  if (node.x === undefined || node.y === undefined) return Infinity;

  const dx = node.x - cameraX;
  const dy = node.y - cameraY;
  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * Determines level of detail for a node based on distance from camera
 */
export function calculateNodeLOD(
  distance: number,
  config: VirtualizationConfig = DEFAULT_CONFIG
): 'high' | 'medium' | 'low' {
  if (distance < config.lodDistances.high) return 'high';
  if (distance < config.lodDistances.medium) return 'medium';
  return 'low';
}

/**
 * Virtualizes nodes based on viewport and LOD
 */
export function virtualizeNodes<T extends VirtualizedNode>(
  nodes: T[],
  cameraX: number,
  cameraY: number,
  zoom: number,
  width: number,
  height: number,
  config: VirtualizationConfig = DEFAULT_CONFIG
): T[] {
  // If below threshold, return all nodes
  if (!shouldEnableVirtualization(nodes.length, config)) {
    return nodes.map(node => ({
      ...node,
      visible: true,
      lod: 'high' as const
    }));
  }

  const bounds = calculateViewportBounds(cameraX, cameraY, zoom, width, height, config.viewportPadding);

  return nodes.map(node => {
    const inViewport = isNodeInViewport(node, bounds);
    const distance = calculateNodeDistance(node, cameraX, cameraY);
    const lod = calculateNodeLOD(distance, config);

    return {
      ...node,
      visible: inViewport,
      lod
    };
  });
}

/**
 * Virtualizes links based on node visibility
 */
export function virtualizeLinks<T extends VirtualizedLink>(
  links: T[],
  visibleNodeIds: Set<string>
): T[] {
  return links.map(link => {
    const sourceId = typeof link.source === 'string' ? link.source : link.source.id;
    const targetId = typeof link.target === 'string' ? link.target : link.target.id;

    const visible = visibleNodeIds.has(sourceId) && visibleNodeIds.has(targetId);

    return {
      ...link,
      visible
    };
  });
}

/**
 * Clusters nodes for simplified rendering at low LOD
 */
export interface NodeCluster {
  id: string;
  nodes: string[];
  x: number;
  y: number;
  size: number;
  type: string;
}

export function clusterNodes(
  nodes: VirtualizedNode[],
  clusterDistance: number = 100
): NodeCluster[] {
  const clusters: NodeCluster[] = [];
  const processed = new Set<string>();

  nodes.forEach(node => {
    if (processed.has(node.id) || !node.x || !node.y) return;

    // Find nearby nodes
    const nearbyNodes = nodes.filter(other => {
      if (processed.has(other.id) || !other.x || !other.y) return false;
      
      const dx = node.x! - other.x!;
      const dy = node.y! - other.y!;
      const distance = Math.sqrt(dx * dx + dy * dy);
      
      return distance < clusterDistance;
    });

    if (nearbyNodes.length >= 2) {
      // Create cluster
      const clusterNodes = nearbyNodes.map(n => n.id);
      const avgX = nearbyNodes.reduce((sum, n) => sum + (n.x || 0), 0) / nearbyNodes.length;
      const avgY = nearbyNodes.reduce((sum, n) => sum + (n.y || 0), 0) / nearbyNodes.length;
      const totalSize = nearbyNodes.reduce((sum, n) => sum + n.size, 0);

      clusters.push({
        id: `cluster-${clusters.length}`,
        nodes: clusterNodes,
        x: avgX,
        y: avgY,
        size: totalSize,
        type: 'cluster'
      });

      nearbyNodes.forEach(n => processed.add(n.id));
    }
  });

  return clusters;
}

/**
 * Simplifies graph for performance by removing low-importance nodes
 */
export function simplifyGraph<T extends VirtualizedNode>(
  nodes: T[],
  links: VirtualizedLink[],
  maxNodes: number = 500
): { nodes: T[]; links: VirtualizedLink[] } {
  if (nodes.length <= maxNodes) {
    return { nodes, links };
  }

  // Calculate node importance (degree centrality)
  const nodeDegrees = new Map<string, number>();
  nodes.forEach(node => nodeDegrees.set(node.id, 0));

  links.forEach(link => {
    const sourceId = typeof link.source === 'string' ? link.source : link.source.id;
    const targetId = typeof link.target === 'string' ? link.target : link.target.id;

    nodeDegrees.set(sourceId, (nodeDegrees.get(sourceId) || 0) + 1);
    nodeDegrees.set(targetId, (nodeDegrees.get(targetId) || 0) + 1);
  });

  // Sort nodes by importance
  const sortedNodes = [...nodes].sort((a, b) => {
    const degreeA = nodeDegrees.get(a.id) || 0;
    const degreeB = nodeDegrees.get(b.id) || 0;
    return degreeB - degreeA;
  });

  // Keep top N nodes
  const keptNodes = sortedNodes.slice(0, maxNodes);
  const keptNodeIds = new Set(keptNodes.map(n => n.id));

  // Filter links to only include kept nodes
  const keptLinks = links.filter(link => {
    const sourceId = typeof link.source === 'string' ? link.source : link.source.id;
    const targetId = typeof link.target === 'string' ? link.target : link.target.id;
    return keptNodeIds.has(sourceId) && keptNodeIds.has(targetId);
  });

  return {
    nodes: keptNodes,
    links: keptLinks
  };
}

/**
 * Performance monitoring for rendering
 */
export class RenderPerformanceMonitor {
  private startTime: number = 0;
  private frameCount: number = 0;
  private fps: number = 0;
  private lastFpsUpdate: number = 0;

  startFrame() {
    this.startTime = performance.now();
  }

  endFrame() {
    const endTime = performance.now();
    const frameDuration = endTime - this.startTime;

    this.frameCount++;

    // Update FPS every second
    if (endTime - this.lastFpsUpdate >= 1000) {
      this.fps = this.frameCount;
      this.frameCount = 0;
      this.lastFpsUpdate = endTime;
    }

    return {
      frameDuration,
      fps: this.fps
    };
  }

  getFPS(): number {
    return this.fps;
  }

  isPerformanceGood(): boolean {
    return this.fps >= 30; // Target 30 FPS minimum
  }
}

/**
 * Adaptive LOD controller that adjusts quality based on performance
 */
export class AdaptiveLODController {
  private monitor: RenderPerformanceMonitor;
  private config: VirtualizationConfig;
  private performanceHistory: number[] = [];
  private readonly historySize = 10;

  constructor(config: VirtualizationConfig = DEFAULT_CONFIG) {
    this.monitor = new RenderPerformanceMonitor();
    this.config = { ...config };
  }

  startFrame() {
    this.monitor.startFrame();
  }

  endFrame() {
    const metrics = this.monitor.endFrame();
    
    // Track performance history
    this.performanceHistory.push(metrics.fps);
    if (this.performanceHistory.length > this.historySize) {
      this.performanceHistory.shift();
    }

    // Adjust LOD distances based on performance
    this.adjustLODDistances();

    return metrics;
  }

  private adjustLODDistances() {
    if (this.performanceHistory.length < this.historySize) return;

    const avgFPS = this.performanceHistory.reduce((a, b) => a + b, 0) / this.performanceHistory.length;

    if (avgFPS < 20) {
      // Performance is poor, reduce LOD distances
      this.config.lodDistances.high *= 0.9;
      this.config.lodDistances.medium *= 0.9;
      this.config.lodDistances.low *= 0.9;
    } else if (avgFPS > 50) {
      // Performance is good, increase LOD distances
      this.config.lodDistances.high *= 1.05;
      this.config.lodDistances.medium *= 1.05;
      this.config.lodDistances.low *= 1.05;
    }

    // Clamp values
    this.config.lodDistances.high = Math.max(200, Math.min(1000, this.config.lodDistances.high));
    this.config.lodDistances.medium = Math.max(500, Math.min(2000, this.config.lodDistances.medium));
    this.config.lodDistances.low = Math.max(1000, Math.min(4000, this.config.lodDistances.low));
  }

  getConfig(): VirtualizationConfig {
    return { ...this.config };
  }

  getFPS(): number {
    return this.monitor.getFPS();
  }
}

