          fc.constantFrom('/api/v1/auth/login', '/api/v1/auth/me', '/api/v1/auth/logout'),
          (backendUrl, endpoint) => {
            // Set environment variable
            process.env.NEXT_PUBLIC_API_URL = backendUrl;
            
            // Construct URL
            const fullUrl = getAuthUrl(endpoint);
            
            // Properties that should always hold
            expect(fullUrl).toContain(endpoint);
            expect(fullUrl).toMatch(/^https?:\/\//); // Valid HTTP(S) URL
            expect(fullUrl).not.toContain('//api'); // No double slashes
            expect(fullUrl).not.toContain('undefined');
            expect(fullUrl).not.toContain('null');
            
            // URL should be parseable
            expect(() => new URL(fullUrl)).not.toThrow();
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should always produce consistent URLs for the same inputs', () => {
      fc.assert(
        fc.property(
          fc.webUrl({ withFragments: false, withQueryParameters: false }),
          fc.constantFrom('/api/v1/auth/login', '/api/v1/auth/me'),
          (backendUrl, endpoint) => {
            process.env.NEXT_PUBLIC_API_URL = backendUrl;
            
            const url1 = getAuthUrl(endpoint);
            const url2 = getAuthUrl(endpoint);
            
            // Idempotency: same inputs should produce same outputs
            expect(url1).toBe(url2);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should handle various URL formats correctly', () => {
      fc.assert(
        fc.property(
          fc.webUrl({ withFragments: false, withQueryParameters: false }),
          fc.boolean(), // with or without trailing slash
          (baseUrl, withTrailingSlash) => {
            const backendUrl = withTrailingSlash ? `${baseUrl}/` : baseUrl;
            process.env.NEXT_PUBLIC_API_URL = backendUrl;
            
            const loginUrl = getLoginUrl();
            const userUrl = getUserDetailsUrl();
            
            // Should not have double slashes (except in protocol)
            expect(loginUrl.replace(/^https?:\/\//, '')).not.toContain('//');
            expect(userUrl.replace(/^https?:\/\//, '')).not.toContain('//');
            
            // Should end with correct endpoints
            expect(loginUrl).toMatch(/\/api\/v1\/auth\/login$/);
            expect(userUrl).toMatch(/\/api\/v1\/auth\/me$/);
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  /**
   * Property 2: Environment Variable Configuration
   * 
   * For any NextAuth configuration loading, the system should correctly read
   * and apply NEXT_PUBLIC_API_URL, NEXTAUTH_URL, and NEXTAUTH_SECRET environment
   * variables to the authentication configuration.
   * 
   * Validates: Requirements 2.1, 2.2, 2.3
   */
  describe('Property 2: Environment Variable Configuration', () => {
    it('should always validate environment configuration consistently', () => {
      fc.assert(
        fc.property(
          fc.option(fc.string({ minLength: 32 }), { nil: undefined }), // NEXTAUTH_SECRET
          fc.option(fc.webUrl(), { nil: undefined }), // NEXTAUTH_URL
          (secret, url) => {
            process.env.NEXTAUTH_SECRET = secret;
            process.env.NEXTAUTH_URL = url;
            
            const result = validateEnvironmentConfig();
            
            // Properties that should always hold
            expect(typeof result.valid).toBe('boolean');
            expect(Array.isArray(result.errors)).toBe(true);
            
            // If valid, should have no errors
            if (result.valid) {
              expect(result.errors).toHaveLength(0);
            }
            
            // If invalid, should have at least one error
            if (!result.valid) {
              expect(result.errors.length).toBeGreaterThan(0);
            }
            
            // Errors should be strings
            result.errors.forEach(error => {
              expect(typeof error).toBe('string');
              expect(error.length).toBeGreaterThan(0);
            });
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should always prefer NEXT_PUBLIC_API_URL over BACKEND_URL', () => {
      fc.assert(
        fc.property(
          fc.webUrl(),
          fc.webUrl(),
          (publicUrl, backendUrl) => {
            process.env.NEXT_PUBLIC_API_URL = publicUrl;
            process.env.BACKEND_URL = backendUrl;
            
            const result = getBackendUrl();
            
            // Should always return NEXT_PUBLIC_API_URL when both are set
            expect(result).toBe(publicUrl);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should always return a valid URL even with missing env vars', () => {
      fc.assert(
        fc.property(
          fc.boolean(),
          fc.boolean(),
          (hasPublicUrl, hasBackendUrl) => {
            process.env.NEXT_PUBLIC_API_URL = hasPublicUrl ? 'http://api.example.com' : '';
            process.env.BACKEND_URL = hasBackendUrl ? 'http://backend.example.com' : '';
            
            const result = getBackendUrl();
            
            // Should always return a valid URL
            expect(result).toBeTruthy();
            expect(result).toMatch(/^https?:\/\//);
            expect(() => new URL(result)).not.toThrow();
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  /**
   * Property 4: Authentication Response Handling
   * 
   * For any backend authentication response (success or failure), the frontend
   * should properly parse the response and establish the correct session state
   * or error state.
   * 
   * Validates: Requirements 3.2, 3.3
   */
  describe('Property 4: Authentication Response Handling', () => {
    it('should always handle successful authentication responses correctly', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.emailAddress(),
          fc.string({ minLength: 8 }),
          fc.uuid(),
          fc.string({ minLength: 20 }),
          fc.string({ minLength: 20 }),
          fc.constantFrom('user', 'admin', 'viewer'),
          async (email, password, userId, accessToken, refreshToken, role) => {
            const mockAuthResponse = {
              access_token: accessToken,
              refresh_token: refreshToken,
            };
            
            const mockUserResponse = {
              id: userId,
              email: email,
              full_name: 'Test User',
              role: role,
              is_active: true,
            };
            
            (global.fetch as jest.Mock)
              .mockResolvedValueOnce({
                ok: true,
                json: async () => mockAuthResponse,
              })
              .mockResolvedValueOnce({
                ok: true,
                json: async () => mockUserResponse,
              });
            
            const user = await authenticateUser({ email, password });
            
            // Properties that should always hold for successful auth
            expect(user.id).toBe(userId);
            expect(user.email).toBe(email);
            expect(user.accessToken).toBe(accessToken);
            expect(user.refreshToken).toBe(refreshToken);
            expect(user.role).toBe(role);
            expect(typeof user.name).toBe('string');
            expect(user.name.length).toBeGreaterThan(0);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should always throw appropriate errors for failed authentication', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.emailAddress(),
          fc.string({ minLength: 8 }),
          fc.integer({ min: 400, max: 599 }),
          fc.string(),
          async (email, password, statusCode, errorMessage) => {
            (global.fetch as jest.Mock).mockResolvedValueOnce({
              ok: false,
              status: statusCode,
              json: async () => ({ detail: errorMessage }),
            });
            
            await expect(authenticateUser({ email, password })).rejects.toMatchObject({
              type: expect.stringMatching(/^(credentials|server|network)$/),
              message: expect.any(String),
            });
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  /**
   * Property 5: Error Handling and Messaging
   * 
   * For any authentication error (configuration, network, or credentials),
   * the system should provide clear, specific error messages and handle
   * the error gracefully without crashing.
   * 
   * Validates: Requirements 1.4, 3.4, 4.2, 4.3
   */
  describe('Property 5: Error Handling and Messaging', () => {
    it('should always create valid error objects', () => {
      fc.assert(
        fc.property(
          fc.constantFrom('configuration', 'network', 'credentials', 'server', 'validation'),
          fc.string({ minLength: 1 }),
          fc.option(fc.integer({ min: 100, max: 599 }), { nil: undefined }),
          fc.option(fc.string(), { nil: undefined }),
          (type, message, statusCode, details) => {
            const error = createAuthError(type, message, statusCode, details);
            
            // Properties that should always hold
            expect(error.type).toBe(type);
            expect(error.message).toBe(message);
            expect(error.statusCode).toBe(statusCode);
            expect(error.details).toBe(details);
            expect(error instanceof Error).toBe(true);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should always return user-friendly error messages', () => {
      fc.assert(
        fc.property(
          fc.constantFrom('configuration', 'network', 'credentials', 'server', 'validation'),
          fc.string({ minLength: 1 }),
          (type, message) => {
            const error = createAuthError(type, message);
            const friendlyMessage = getUserFriendlyErrorMessage(error);
            
            // Properties that should always hold
            expect(typeof friendlyMessage).toBe('string');
            expect(friendlyMessage.length).toBeGreaterThan(0);
            expect(friendlyMessage).not.toContain('undefined');
            expect(friendlyMessage).not.toContain('null');
            
            // Should not expose technical details (except for validation)
            if (type !== 'validation') {
              expect(friendlyMessage).not.toBe(message);
            }
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should always handle any error type gracefully', () => {
      fc.assert(
        fc.property(
          fc.oneof(
            fc.constant(new Error('Test error')),
            fc.constant(createAuthError('network', 'Network error')),
            fc.constant('string error'),
            fc.constant(null),
            fc.constant(undefined),
            fc.constant({ custom: 'error' })
          ),
          (error) => {
            const handled = handleAuthError(error);
            
            // Should always return a valid AuthError
            expect(handled.type).toMatch(/^(configuration|network|credentials|server|validation)$/);
            expect(typeof handled.message).toBe('string');
            expect(handled.message.length).toBeGreaterThan(0);
            expect(handled instanceof Error).toBe(true);
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  /**
   * Property 6: Development Logging
   * 
   * For any authentication operation when NODE_ENV is set to development,
   * the system should provide detailed logging and debugging information.
   * 
   * Validates: Requirements 4.1, 4.4
   */
  describe('Property 6: Development Logging', () => {
    it('should log in development mode but not in production', () => {
      fc.assert(
        fc.property(
          fc.constantFrom('development', 'production', 'test'),
          fc.webUrl(),
          (nodeEnv, backendUrl) => {
            process.env.NODE_ENV = nodeEnv;
            process.env.NEXT_PUBLIC_API_URL = backendUrl;
            
            const consoleSpy = jest.spyOn(console, 'log').mockImplementation();
            
            getBackendUrl();
            
            if (nodeEnv === 'development') {
              // Should log in development
              expect(consoleSpy).toHaveBeenCalled();
            } else {
              // Should not log in production/test
              expect(consoleSpy).not.toHaveBeenCalled();
            }
            
            consoleSpy.mockRestore();
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  /**
   * Additional Property: Email Validation Consistency
   * 
   * Email validation should be consistent and follow standard email format rules.
   */
  describe('Additional Property: Email Validation', () => {
    it('should consistently validate email formats', () => {
      fc.assert(
        fc.property(
          fc.emailAddress(),
          (email) => {
            const isValid = isValidEmail(email);
            
            // Valid emails should always pass
            expect(isValid).toBe(true);
            
            // Should be idempotent
            expect(isValidEmail(email)).toBe(isValid);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should reject invalid email formats', () => {
      fc.assert(
        fc.property(
          fc.oneof(
            fc.constant(''),
            fc.constant('invalid'),
            fc.constant('@example.com'),
            fc.constant('user@'),
            fc.string().filter(s => !s.includes('@'))
          ),
          (invalidEmail) => {
            const isValid = isValidEmail(invalidEmail);
            
            // Invalid emails should always fail
            expect(isValid).toBe(false);
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  /**
   * Additional Property: Password Validation Consistency
   * 
   * Password validation should consistently enforce security requirements.
   */
  describe('Additional Property: Password Validation', () => {
    it('should consistently validate password strength', () => {
      fc.assert(
        fc.property(
          fc.string({ minLength: 8 })
            .filter(s => /[A-Z]/.test(s) && /[a-z]/.test(s) && /[0-9]/.test(s)),
          (password) => {
            const result = isValidPassword(password);
            
            // Strong passwords should pass
            expect(result.valid).toBe(true);
            expect(result.errors).toHaveLength(0);
            
            // Should be idempotent
            const result2 = isValidPassword(password);
            expect(result2.valid).toBe(result.valid);
            expect(result2.errors).toEqual(result.errors);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should always return consistent error messages for weak passwords', () => {
      fc.assert(
        fc.property(
          fc.string({ maxLength: 7 }),
          (weakPassword) => {
            const result = isValidPassword(weakPassword);
            
            // Weak passwords should fail
            expect(result.valid).toBe(false);
            expect(result.errors.length).toBeGreaterThan(0);
            
            // All errors should be strings
            result.errors.forEach(error => {
              expect(typeof error).toBe('string');
              expect(error.length).toBeGreaterThan(0);
            });
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  /**
   * Additional Property: Credentials Validation Consistency
   * 
   * Credentials validation should consistently check both email and password.
   */
  describe('Additional Property: Credentials Validation', () => {
    it('should consistently validate complete credentials', () => {
      fc.assert(
        fc.property(
          fc.emailAddress(),
          fc.string({ minLength: 1 }),
          (email, password) => {
            const result = validateCredentials({ email, password });
            
            // Properties that should always hold
            expect(typeof result.valid).toBe('boolean');
            expect(Array.isArray(result.errors)).toBe(true);
            
            // If valid, no errors
            if (result.valid) {
              expect(result.errors).toHaveLength(0);
            }
            
            // If invalid, at least one error
            if (!result.valid) {
              expect(result.errors.length).toBeGreaterThan(0);
            }
            
            // Should be idempotent
            const result2 = validateCredentials({ email, password });
            expect(result2.valid).toBe(result.valid);
            expect(result2.errors).toEqual(result.errors);
          }
        ),
        { numRuns: 100 }
      );
    });
  });
});

/**
 * Unit Tests for Authentication Service
 * 
 * Tests URL construction, error handling, validation, and authentication operations
 */

import {
  getBackendUrl,
  validateEnvironmentConfig,
  getAuthUrl,
  getLoginUrl,
  getUserDetailsUrl,
  authenticateUser,
  createAuthError,
  getUserFriendlyErrorMessage,
  handleAuthError,
  isValidEmail,
  isValidPassword,
  validateCredentials,
  type LoginCredentials,
  type AuthError,
} from '../auth';

// Mock fetch globally
global.fetch = jest.fn();

describe('Authentication Service', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    // Reset environment variables
    process.env.NEXT_PUBLIC_API_URL = '';
    process.env.BACKEND_URL = '';
    process.env.NEXTAUTH_SECRET = '';
    process.env.NEXTAUTH_URL = '';
    process.env.NODE_ENV = 'test';
  });

  describe('Configuration', () => {
    describe('getBackendUrl', () => {
      it('should return NEXT_PUBLIC_API_URL when set', () => {
        process.env.NEXT_PUBLIC_API_URL = 'http://api.example.com';
        expect(getBackendUrl()).toBe('http://api.example.com');
      });

      it('should return BACKEND_URL when NEXT_PUBLIC_API_URL is not set', () => {
        process.env.BACKEND_URL = 'http://backend.example.com';
        expect(getBackendUrl()).toBe('http://backend.example.com');
      });

      it('should return default localhost URL when no env vars are set', () => {
        expect(getBackendUrl()).toBe('http://localhost:8000');
      });

      it('should prefer NEXT_PUBLIC_API_URL over BACKEND_URL', () => {
        process.env.NEXT_PUBLIC_API_URL = 'http://api.example.com';
        process.env.BACKEND_URL = 'http://backend.example.com';
        expect(getBackendUrl()).toBe('http://api.example.com');
      });
    });

    describe('validateEnvironmentConfig', () => {
      it('should return valid when all required env vars are set', () => {
        process.env.NEXTAUTH_SECRET = 'a'.repeat(32);
        process.env.NEXTAUTH_URL = 'http://localhost:6066';
        
        const result = validateEnvironmentConfig();
        expect(result.valid).toBe(true);
        expect(result.errors).toHaveLength(0);
      });

      it('should return error when NEXTAUTH_SECRET is missing', () => {
        process.env.NEXTAUTH_URL = 'http://localhost:6066';
        
        const result = validateEnvironmentConfig();
        expect(result.valid).toBe(false);
        expect(result.errors).toContain('NEXTAUTH_SECRET is not configured');
      });

      it('should return error when NEXTAUTH_SECRET is too short', () => {
        process.env.NEXTAUTH_SECRET = 'short';
        process.env.NEXTAUTH_URL = 'http://localhost:6066';
        
        const result = validateEnvironmentConfig();
        expect(result.valid).toBe(false);
        expect(result.errors).toContain('NEXTAUTH_SECRET must be at least 32 characters long');
      });

      it('should return error when NEXTAUTH_URL is missing', () => {
        process.env.NEXTAUTH_SECRET = 'a'.repeat(32);
        
        const result = validateEnvironmentConfig();
        expect(result.valid).toBe(false);
        expect(result.errors).toContain('NEXTAUTH_URL is not configured');
      });

      it('should return multiple errors when multiple configs are invalid', () => {
        const result = validateEnvironmentConfig();
        expect(result.valid).toBe(false);
        expect(result.errors.length).toBeGreaterThan(1);
      });
    });
  });

  describe('URL Construction', () => {
    describe('getAuthUrl', () => {
      it('should construct URL with backend URL and endpoint', () => {
        process.env.NEXT_PUBLIC_API_URL = 'http://api.example.com';
        expect(getAuthUrl('/api/v1/auth/login')).toBe('http://api.example.com/api/v1/auth/login');
      });

      it('should handle backend URL with trailing slash', () => {
        process.env.NEXT_PUBLIC_API_URL = 'http://api.example.com/';
        expect(getAuthUrl('/api/v1/auth/login')).toBe('http://api.example.com/api/v1/auth/login');
      });

      it('should handle endpoint without leading slash', () => {
        process.env.NEXT_PUBLIC_API_URL = 'http://api.example.com';
        expect(getAuthUrl('api/v1/auth/login')).toBe('http://api.example.com/api/v1/auth/login');
      });

      it('should use default backend URL when not configured', () => {
        expect(getAuthUrl('/api/v1/auth/login')).toBe('http://localhost:8000/api/v1/auth/login');
      });
    });

    describe('getLoginUrl', () => {
      it('should return correct login endpoint URL', () => {
        process.env.NEXT_PUBLIC_API_URL = 'http://api.example.com';
        expect(getLoginUrl()).toBe('http://api.example.com/api/v1/auth/login');
      });
    });

    describe('getUserDetailsUrl', () => {
      it('should return correct user details endpoint URL', () => {
        process.env.NEXT_PUBLIC_API_URL = 'http://api.example.com';
        expect(getUserDetailsUrl()).toBe('http://api.example.com/api/v1/auth/me');
      });
    });
  });

  describe('Authentication Operations', () => {
    const mockCredentials: LoginCredentials = {
      email: 'test@example.com',
      password: 'Password123',
    };

    const mockAuthResponse = {
      access_token: 'mock-access-token',
      refresh_token: 'mock-refresh-token',
    };

    const mockUserResponse = {
      id: '123',
      email: 'test@example.com',
      full_name: 'Test User',
      role: 'user',
      is_active: true,
    };

    describe('authenticateUser', () => {
      it('should successfully authenticate user with valid credentials', async () => {
        (global.fetch as jest.Mock)
          .mockResolvedValueOnce({
            ok: true,
            json: async () => mockAuthResponse,
          })
          .mockResolvedValueOnce({
            ok: true,
            json: async () => mockUserResponse,
          });

        const user = await authenticateUser(mockCredentials);

        expect(user).toEqual({
          id: '123',
          username: 'test@example.com',
          email: 'test@example.com',
          name: 'Test User',
          full_name: 'Test User',
          role: 'user',
          is_active: true,
          accessToken: 'mock-access-token',
          refreshToken: 'mock-refresh-token',
        });

        expect(global.fetch).toHaveBeenCalledTimes(2);
      });

      it('should throw validation error when email is missing', async () => {
        await expect(
          authenticateUser({ email: '', password: 'password' })
        ).rejects.toMatchObject({
          type: 'validation',
          message: 'Email and password are required',
        });
      });

      it('should throw validation error when password is missing', async () => {
        await expect(
          authenticateUser({ email: 'test@example.com', password: '' })
        ).rejects.toMatchObject({
          type: 'validation',
          message: 'Email and password are required',
        });
      });

      it('should throw credentials error on 401 response', async () => {
        (global.fetch as jest.Mock).mockResolvedValueOnce({
          ok: false,
          status: 401,
          json: async () => ({ detail: 'Invalid credentials' }),
        });

        await expect(authenticateUser(mockCredentials)).rejects.toMatchObject({
          type: 'credentials',
          message: 'Invalid credentials',
          statusCode: 401,
        });
      });

      it('should throw server error on 500 response', async () => {
        (global.fetch as jest.Mock).mockResolvedValueOnce({
          ok: false,
          status: 500,
          json: async () => ({ detail: 'Internal server error' }),
        });

        await expect(authenticateUser(mockCredentials)).rejects.toMatchObject({
          type: 'server',
          message: 'Internal server error',
          statusCode: 500,
        });
      });

      it('should throw server error when access_token is missing', async () => {
        (global.fetch as jest.Mock).mockResolvedValueOnce({
          ok: true,
          json: async () => ({ refresh_token: 'token' }), // Missing access_token
        });

        await expect(authenticateUser(mockCredentials)).rejects.toMatchObject({
          type: 'server',
          message: 'Invalid response from authentication server',
        });
      });

      it('should throw server error when user details fetch fails', async () => {
        (global.fetch as jest.Mock)
          .mockResolvedValueOnce({
            ok: true,
            json: async () => mockAuthResponse,
          })
          .mockResolvedValueOnce({
            ok: false,
            status: 500,
          });

        await expect(authenticateUser(mockCredentials)).rejects.toMatchObject({
          type: 'server',
          message: 'Failed to fetch user details',
          statusCode: 500,
        });
      });

      it('should throw network error on fetch failure', async () => {
        (global.fetch as jest.Mock).mockRejectedValueOnce(new Error('Network error'));

        await expect(authenticateUser(mockCredentials)).rejects.toMatchObject({
          type: 'network',
          message: 'Network error',
        });
      });

      it('should use correct authorization header for user details request', async () => {
        (global.fetch as jest.Mock)
          .mockResolvedValueOnce({
            ok: true,
            json: async () => mockAuthResponse,
          })
          .mockResolvedValueOnce({
            ok: true,
            json: async () => mockUserResponse,
          });

        await authenticateUser(mockCredentials);

        const secondCall = (global.fetch as jest.Mock).mock.calls[1];
        expect(secondCall[1].headers.Authorization).toBe('Bearer mock-access-token');
      });
    });
  });

  describe('Error Handling', () => {
    describe('createAuthError', () => {
      it('should create error with all properties', () => {
        const error = createAuthError('credentials', 'Invalid password', 401, 'Additional details');
        
        expect(error.type).toBe('credentials');
        expect(error.message).toBe('Invalid password');
        expect(error.statusCode).toBe(401);
        expect(error.details).toBe('Additional details');
        expect(error instanceof Error).toBe(true);
      });

      it('should create error without optional properties', () => {
        const error = createAuthError('network', 'Connection failed');
        
        expect(error.type).toBe('network');
        expect(error.message).toBe('Connection failed');
        expect(error.statusCode).toBeUndefined();
        expect(error.details).toBeUndefined();
      });
    });

    describe('getUserFriendlyErrorMessage', () => {
      it('should return friendly message for configuration error', () => {
        const error = createAuthError('configuration', 'Config missing');
        expect(getUserFriendlyErrorMessage(error)).toBe(
          'Authentication is not properly configured. Please contact support.'
        );
      });

      it('should return friendly message for network error', () => {
        const error = createAuthError('network', 'Connection failed');
        expect(getUserFriendlyErrorMessage(error)).toBe(
          'Unable to connect to the authentication server. Please check your connection and try again.'
        );
      });

      it('should return friendly message for credentials error', () => {
        const error = createAuthError('credentials', 'Invalid password');
        expect(getUserFriendlyErrorMessage(error)).toBe(
          'Invalid email or password. Please try again.'
        );
      });

      it('should return friendly message for server error', () => {
        const error = createAuthError('server', 'Internal error');
        expect(getUserFriendlyErrorMessage(error)).toBe(
          'The authentication server encountered an error. Please try again later.'
        );
      });

      it('should return original message for validation error', () => {
        const error = createAuthError('validation', 'Email is required');
        expect(getUserFriendlyErrorMessage(error)).toBe('Email is required');
      });
    });

    describe('handleAuthError', () => {
      it('should handle AuthError correctly', () => {
        const originalError = createAuthError('credentials', 'Invalid password', 401);
        const handled = handleAuthError(originalError);
        
        expect(handled).toEqual(originalError);
      });

      it('should convert regular Error to AuthError', () => {
        const originalError = new Error('Something went wrong');
        const handled = handleAuthError(originalError);
        
        expect(handled.type).toBe('network');
        expect(handled.message).toBe('Something went wrong');
      });

      it('should handle unknown error types', () => {
        const handled = handleAuthError('string error');
        
        expect(handled.type).toBe('network');
        expect(handled.message).toBe('An unexpected error occurred');
      });
    });
  });

  describe('Validation', () => {
    describe('isValidEmail', () => {
      it('should validate correct email addresses', () => {
        expect(isValidEmail('test@example.com')).toBe(true);
        expect(isValidEmail('user.name@example.co.uk')).toBe(true);
        expect(isValidEmail('user+tag@example.com')).toBe(true);
      });

      it('should reject invalid email addresses', () => {
        expect(isValidEmail('invalid')).toBe(false);
        expect(isValidEmail('invalid@')).toBe(false);
        expect(isValidEmail('@example.com')).toBe(false);
        expect(isValidEmail('invalid@example')).toBe(false);
        expect(isValidEmail('')).toBe(false);
      });
    });

    describe('isValidPassword', () => {
      it('should validate strong passwords', () => {
        const result = isValidPassword('Password123');
        expect(result.valid).toBe(true);
        expect(result.errors).toHaveLength(0);
      });

      it('should reject password that is too short', () => {
        const result = isValidPassword('Pass1');
        expect(result.valid).toBe(false);
        expect(result.errors).toContain('Password must be at least 8 characters long');
      });

      it('should reject password without uppercase letter', () => {
        const result = isValidPassword('password123');
        expect(result.valid).toBe(false);
        expect(result.errors).toContain('Password must contain at least one uppercase letter');
      });

      it('should reject password without lowercase letter', () => {
        const result = isValidPassword('PASSWORD123');
        expect(result.valid).toBe(false);
        expect(result.errors).toContain('Password must contain at least one lowercase letter');
      });

      it('should reject password without number', () => {
        const result = isValidPassword('PasswordABC');
        expect(result.valid).toBe(false);
        expect(result.errors).toContain('Password must contain at least one number');
      });

      it('should return multiple errors for weak password', () => {
        const result = isValidPassword('pass');
        expect(result.valid).toBe(false);
        expect(result.errors.length).toBeGreaterThan(1);
      });
    });

    describe('validateCredentials', () => {
      it('should validate correct credentials', () => {
        const result = validateCredentials({
          email: 'test@example.com',
          password: 'password',
        });
        expect(result.valid).toBe(true);
        expect(result.errors).toHaveLength(0);
      });

      it('should reject missing email', () => {
        const result = validateCredentials({
          email: '',
          password: 'password',
        });
        expect(result.valid).toBe(false);
        expect(result.errors).toContain('Email is required');
      });

      it('should reject invalid email format', () => {
        const result = validateCredentials({
          email: 'invalid-email',
          password: 'password',
        });
        expect(result.valid).toBe(false);
        expect(result.errors).toContain('Invalid email format');
      });

      it('should reject missing password', () => {
        const result = validateCredentials({
          email: 'test@example.com',
          password: '',
        });
        expect(result.valid).toBe(false);
        expect(result.errors).toContain('Password is required');
      });

      it('should return multiple errors for invalid credentials', () => {
        const result = validateCredentials({
          email: '',
          password: '',
        });
        expect(result.valid).toBe(false);
        expect(result.errors.length).toBeGreaterThan(1);
      });
    });
  });
});

