        throw error;
      });

      const retryHandler = ErrorHandler.createRetryHandler(fn, 3, 100);

      try {
        await retryHandler();
        fail('Should have thrown an error');
      } catch (error) {
        // Expected to throw
        expect(error).toBeDefined();
      }
      
      expect(fn).toHaveBeenCalledTimes(1);
    });

    it('should throw after max retries', async () => {
      const fn = jest.fn(async () => {
        const error: Partial<AxiosError> = {
          message: 'Network Error',
          code: 'ECONNREFUSED',
          isAxiosError: true,
          config: {} as any,
          toJSON: () => ({}),
          name: 'AxiosError',
        };
        throw error;
      });

      const retryHandler = ErrorHandler.createRetryHandler(fn, 2, 50);

      try {
        await retryHandler();
        fail('Should have thrown an error');
      } catch (error) {
        // Expected to throw after retries
        expect(error).toBeDefined();
      }
      
      expect(fn).toHaveBeenCalledTimes(3); // Initial + 2 retries
    });

    it('should use exponential backoff', async () => {
      const fn = jest.fn(async () => {
        const error: Partial<AxiosError> = {
          message: 'Network Error',
          code: 'ECONNREFUSED',
          isAxiosError: true,
          config: {} as any,
          toJSON: () => ({}),
          name: 'AxiosError',
        };
        throw error;
      });

      const startTime = Date.now();
      const retryHandler = ErrorHandler.createRetryHandler(fn, 2, 100);

      try {
        await retryHandler();
      } catch (error) {
        // Expected to fail
      }

      const duration = Date.now() - startTime;
      
      // Should wait at least 100ms + 200ms = 300ms
      expect(duration).toBeGreaterThanOrEqual(300);
    });
  });

  describe('Convenience functions', () => {
