/**
 * Architecture Component Inner
 * 
 * Inner component that has access to ReactFlow context for export functionality.
 */
function ArchitectureInner({
  data,
  onNodeClick,
  onExport,
}: ArchitectureProps) {
  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set());
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [isExporting, setIsExporting] = useState(false);
  const reactFlowWrapper = useRef<HTMLDivElement>(null);
  const { getNodes, getEdges, getViewport } = useReactFlow();
  
  const handleExportPNG = useCallback(async () => {
    if (!reactFlowWrapper.current) return;
    
    setIsExporting(true);
    try {
      const flowElement = reactFlowWrapper.current.querySelector('.react-flow');
      if (!flowElement) {
        console.error('React Flow element not found');
        return;
      }
      
      const dataUrl = await toPng(flowElement as HTMLElement, {
        backgroundColor: '#ffffff',
        quality: 1,
        pixelRatio: 2,
      });
      
      const link = document.createElement('a');
      link.download = `architecture-${Date.now()}.png`;
      link.href = dataUrl;
      link.click();
    } catch (error) {
      console.error('Failed to export PNG:', error);
    } finally {
      setIsExporting(false);
    }
  }, [getNodes, getEdges, getViewport]);

  const handleExportSVG = useCallback(async () => {
    if (!reactFlowWrapper.current) return;
    
    setIsExporting(true);
    try {
      const flowElement = reactFlowWrapper.current.querySelector('.react-flow');
      if (!flowElement) {
        console.error('React Flow element not found');
        return;
      }
      
      const dataUrl = await toSvg(flowElement as HTMLElement, {
        backgroundColor: '#ffffff',
      });
      
      const link = document.createElement('a');
      link.download = `architecture-${Date.now()}.svg`;
      link.href = dataUrl;
      link.click();
    } catch (error) {
      console.error('Failed to export SVG:', error);
    } finally {
      setIsExporting(false);
    }
  }, [getNodes, getEdges, getViewport]);
  const architectureData = useMemo(
    () => data || generateSampleData(),
    [data]
  );

  // Convert architecture data to ReactFlow format
  const { nodes: initialNodes, edges: initialEdges } = useMemo(
    () => convertToFlowElements(architectureData, expandedNodes, selectedNodeId),
    [architectureData, expandedNodes, selectedNodeId]
  );

  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);

  // Handle new connections
  const onConnect = useCallback(
    (params: FlowConnection) => setEdges((eds) => addEdge(params, eds)),
    [setEdges]
  );

  // Handle node clicks
  const handleNodeClick = useCallback(
    (_event: React.MouseEvent, node: FlowNode) => {
      // Find the original node data
      const findNode = (n: ArchitectureNode): ArchitectureNode | null => {
        if (n.id === node.id) return n;
        for (const child of n.children) {
          const found = findNode(child);
          if (found) return found;
        }
        return null;
      };

      const originalNode = findNode(architectureData);
      if (originalNode) {
        // Toggle selection for dependency path highlighting
        setSelectedNodeId((prev) => (prev === node.id ? null : node.id));
        
        // Toggle expansion if node has children
        if (originalNode.children.length > 0) {
          setExpandedNodes((prev) => {
            const next = new Set(prev);
            if (next.has(node.id)) {
              next.delete(node.id);
            } else {
              next.add(node.id);
            }
            return next;
          });
        }

        // Call external click handler
        if (onNodeClick) {
          onNodeClick(originalNode);
        }
      }
    },
    [architectureData, onNodeClick]
  );

  // Update nodes and edges when expanded nodes or selected node change
  React.useEffect(() => {
    const { nodes: newNodes, edges: newEdges } = convertToFlowElements(
      architectureData,
      expandedNodes,
      selectedNodeId
    );
    setNodes(newNodes);
    setEdges(newEdges);
  }, [expandedNodes, selectedNodeId, architectureData, setNodes, setEdges]);

  return (
    <div ref={reactFlowWrapper} className="w-full h-screen bg-background">
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        onNodeClick={handleNodeClick}
        nodeTypes={nodeTypes}
        fitView
        attributionPosition="bottom-right"
        minZoom={0.1}
        maxZoom={2}
      >
        <Background variant={BackgroundVariant.Dots} gap={16} size={1} />
        <Controls />
        <MiniMap
          nodeColor={(node) => {
            const type = node.data?.type;
            switch (type) {
              case 'service':
                return '#3b82f6';
              case 'component':
                return '#22c55e';
              case 'module':
                return '#a855f7';
              case 'database':
                return '#f97316';
              case 'external':
                return '#6b7280';
              default:
                return '#94a3b8';
            }
          }}
          maskColor="rgba(0, 0, 0, 0.1)"
        />
        <Panel position="top-left" className="bg-background/80 backdrop-blur-sm p-4 rounded-lg shadow-lg">
          <h2 className="text-lg font-semibold mb-2">Architecture Visualization</h2>
          {selectedNodeId && (
            <div className="mb-3 p-2 bg-blue-50 dark:bg-blue-950/50 rounded border border-blue-200 dark:border-blue-800">
              <p className="text-xs text-blue-700 dark:text-blue-300">
                Showing dependency paths for selected node
              </p>
              <button
                onClick={() => setSelectedNodeId(null)}
                className="text-xs text-blue-600 dark:text-blue-400 hover:underline mt-1"
              >
                Clear selection
              </button>
            </div>
          )}
          <div className="text-sm space-y-1">
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-blue-500"></div>
              <span>Service</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-green-500"></div>
              <span>Component</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-purple-500"></div>
              <span>Module</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-orange-500"></div>
              <span>Database</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-gray-500"></div>
              <span>External</span>
            </div>
          </div>
        </Panel>
        <Panel position="top-right" className="bg-background/80 backdrop-blur-sm p-4 rounded-lg shadow-lg">
          <h3 className="text-sm font-semibold mb-2">Export</h3>
          <div className="flex flex-col gap-2">
            <button
              onClick={handleExportPNG}
              disabled={isExporting}
              className="px-3 py-2 text-sm bg-blue-600 text-white rounded hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors"
              title="Export as PNG image"
            >
              {isExporting ? 'Exporting...' : 'Export PNG'}
            </button>
            <button
              onClick={handleExportSVG}
              disabled={isExporting}
              className="px-3 py-2 text-sm bg-purple-600 text-white rounded hover:bg-purple-700 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors"
              title="Export as SVG vector"
            >
              {isExporting ? 'Exporting...' : 'Export SVG'}
            </button>
          </div>
        </Panel>
      </ReactFlow>
    </div>
  );
}

/**
 * Architecture Component
 * 
 * Main component wrapper that provides ReactFlow context.
 * Supports node interaction, dependency visualization, metrics display, and export.
 * 
 * Requirements: 4.1, 4.2, 4.3, 4.4, 4.5
 */
export default function Architecture(props: ArchitectureProps) {
  return (
    <ReactFlowProvider>
      <ArchitectureInner {...props} />
    </ReactFlowProvider>
  );
}

/**
 * Dashboard Page Component
 * 
 * Features:
 * - Display system overview and key metrics
 * - Lazy data loading mechanism (fetch on component mount, not on import)
 * - 30-second auto-refresh (configurable)
 * - Wrapped with ErrorBoundary
 * - Clean up timers to prevent memory leaks
 * 
 * Requirements: 1.1, 1.4
 */

import React, { Component } from 'react';
import { ErrorBoundary } from '../components/ErrorBoundary';
import { LoadingState } from '../components/LoadingState';
import { getApiClient } from '../lib/api-client';
import '../styles/responsive.css';

export interface DashboardProps {
  /** Data refresh interval (milliseconds), default 30 seconds */
  refreshInterval?: number;
}

export interface SystemMetrics {
  activeUsers: number;
  totalProjects: number;
  pendingPRs: number;
  queuedTasks: number;
  systemHealth: 'healthy' | 'degraded' | 'down';
  lastUpdate: Date;
}

export interface DashboardState {
  metrics: SystemMetrics | null;
  loading: boolean;
  error: Error | null;
  lastUpdate: Date | null;
}

/**
 * Dashboard Class Component
 * Implements lazy loading, scheduled refresh, and resource cleanup
 */
export class DashboardComponent extends Component<DashboardProps, DashboardState> {
  private refreshTimer: NodeJS.Timeout | null = null;
  private mounted = false;
  private abortController: AbortController | null = null;
  private pendingRequests: Set<Promise<void>> = new Set();

  static defaultProps: Partial<DashboardProps> = {
    refreshInterval: 30000, // Default 30 seconds
  };

  constructor(props: DashboardProps) {
    super(props);
    this.state = {
      metrics: null,
      loading: true,
      error: null,
      lastUpdate: null,
    };
  }

  /**
   * Start lazy data loading after component mount
   */
  async componentDidMount(): Promise<void> {
    this.mounted = true;
    
    // Initial data load
    await this.fetchMetrics();

    // Setup scheduled refresh
    if (this.props.refreshInterval && this.props.refreshInterval > 0) {
      this.refreshTimer = setInterval(() => {
        this.fetchMetrics();
      }, this.props.refreshInterval);
    }
  }

  /**
   * Clean up all resources on component unmount
   * Prevent memory leaks
   */
  componentWillUnmount(): void {
    this.mounted = false;
    
    // Clean up timer
    if (this.refreshTimer) {
      clearInterval(this.refreshTimer);
      this.refreshTimer = null;
    }

    // Cancel all pending requests
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }

    // Clear pending request references
    this.pendingRequests.clear();
  }

  /**
   * Fetch Dashboard metrics data
   * Ensure data update response within 500ms
   */
  fetchMetrics = async (): Promise<void> => {
    // Skip update if component is unmounted
    if (!this.mounted) {
      return;
    }

    // Record start time to track response performance
    const startTime = performance.now();

    // Create new AbortController for this request
    this.abortController = new AbortController();

    const requestPromise = (async () => {
      try {
        // Show loading state only on first load
        if (!this.state.metrics) {
          this.setState({ loading: true, error: null });
        }

        const apiClient = getApiClient();
        const metrics = await apiClient.get<SystemMetrics>('/dashboard/metrics');

        // Calculate response time
        const responseTime = performance.now() - startTime;

        // Ensure component is still mounted before updating state
        if (this.mounted) {
          this.setState({
            metrics,
            loading: false,
            error: null,
            lastUpdate: new Date(),
          });

          // Log response time in development to verify performance
          if (process.env.NODE_ENV === 'development') {
            console.log(`Dashboard data refresh completed in ${responseTime.toFixed(2)}ms`);
            if (responseTime > 500) {
              console.warn(`Dashboard refresh exceeded 500ms target: ${responseTime.toFixed(2)}ms`);
            }
          }
        }
      } catch (error) {
        // If it's an abort error, don't update state
        if (error instanceof Error && error.name === 'AbortError') {
          return;
        }

        // Ensure component is still mounted before updating state
        if (this.mounted) {
          this.setState({
            loading: false,
            error: error instanceof Error ? error : new Error('Failed to fetch metrics'),
          });
        }
      }
    })();

    // Track pending requests
    this.pendingRequests.add(requestPromise);

    try {
      await requestPromise;
    } finally {
      // Clean up this request reference
      this.pendingRequests.delete(requestPromise);
    }
  };

  /**
   * Manual data refresh
   */
  handleRefresh = (): void => {
    this.fetchMetrics();
  };

  /**
   * Get system health status color
   */
  getHealthColor(health: SystemMetrics['systemHealth']): string {
    switch (health) {
      case 'healthy':
        return '#22c55e'; // green
      case 'degraded':
        return '#f59e0b'; // amber
      case 'down':
        return '#ef4444'; // red
      default:
        return '#6b7280'; // gray
    }
  }

  /**
   * Get system health status text
   */
  getHealthText(health: SystemMetrics['systemHealth']): string {
    switch (health) {
      case 'healthy':
        return 'Healthy';
      case 'degraded':
        return 'Degraded';
      case 'down':
        return 'Down';
      default:
        return 'Unknown';
    }
  }

  render(): React.ReactNode {
    const { loading, error, metrics, lastUpdate } = this.state;

    // Loading state
    if (loading && !metrics) {
      return (
        <LoadingState
          variant="spinner"
          size="large"
          text="Loading dashboard..."
          fullscreen={false}
        />
      );
    }

    // Error state
    if (error && !metrics) {
      return (
        <div style={styles.errorContainer}>
          <div style={styles.errorIcon}>⚠️</div>
          <h2 style={styles.errorTitle}>Failed to Load Dashboard</h2>
          <p style={styles.errorMessage}>{error.message}</p>
          <button onClick={this.handleRefresh} style={styles.retryButton}>
            Retry
          </button>
        </div>
      );
    }

    // Main content
    return (
      <div style={styles.container}>
        <div style={styles.header}>
          <h1 style={styles.title}>Dashboard</h1>
          <div style={styles.headerActions}>
            {lastUpdate && (
              <span style={styles.lastUpdate}>
                Last updated: {lastUpdate.toLocaleTimeString()}
              </span>
            )}
            <button onClick={this.handleRefresh} style={styles.refreshButton}>
              🔄 Refresh
            </button>
          </div>
        </div>

        {metrics && (
          <div style={styles.metricsGrid}>
            {/* Active Users */}
            <div style={styles.metricCard}>
              <div style={styles.metricIcon}>👥</div>
              <div style={styles.metricContent}>
                <div style={styles.metricLabel}>Active Users</div>
                <div style={styles.metricValue}>{metrics.activeUsers}</div>
              </div>
            </div>

            {/* Total Projects */}
            <div style={styles.metricCard}>
              <div style={styles.metricIcon}>📁</div>
              <div style={styles.metricContent}>
                <div style={styles.metricLabel}>Total Projects</div>
                <div style={styles.metricValue}>{metrics.totalProjects}</div>
              </div>
            </div>

            {/* Pending PRs */}
            <div style={styles.metricCard}>
              <div style={styles.metricIcon}>🔀</div>
              <div style={styles.metricContent}>
                <div style={styles.metricLabel}>Pending PRs</div>
                <div style={styles.metricValue}>{metrics.pendingPRs}</div>
              </div>
            </div>

            {/* Queued Tasks */}
            <div style={styles.metricCard}>
              <div style={styles.metricIcon}>📋</div>
              <div style={styles.metricContent}>
                <div style={styles.metricLabel}>Queued Tasks</div>
                <div style={styles.metricValue}>{metrics.queuedTasks}</div>
              </div>
            </div>

            {/* System Health */}
            <div style={styles.metricCard}>
              <div style={styles.metricIcon}>💚</div>
              <div style={styles.metricContent}>
                <div style={styles.metricLabel}>System Health</div>
                <div
                  style={{
                    ...styles.metricValue,
                    color: this.getHealthColor(metrics.systemHealth),
                  }}
                >
                  {this.getHealthText(metrics.systemHealth)}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Display background refresh error (does not affect existing data display) */}
        {error && metrics && (
          <div style={styles.backgroundErrorBanner}>
            ⚠️ Failed to refresh data: {error.message}
          </div>
        )}
      </div>
    );
  }
}

/**
 * Dashboard component - wrapped with ErrorBoundary
 */
export const Dashboard: React.FC<DashboardProps> = (props) => {
  return (
    <ErrorBoundary>
      <DashboardComponent {...props} />
    </ErrorBoundary>
  );
};

