  /**
   * **Feature: frontend-production-optimization, Property 27: timeouthint**
   * **verifyRequirement: 10.5**
   * 
   * property: 对于任何response时间超过5sec的APIrequest，shouldshowloadtimeouthint
   * 
   * test策略:
   * - generate随机的URLand延迟时间
   * - 对于延迟超过5sec的request，verifytimeout回调被调用
   * - 对于延迟小于5sec的request，verifytimeout回调不被调用
   * - verifytimeouthint在requestcomplete后被cleanup
   */
  describe('Property 27: timeouthint', () => {
    beforeEach(() => {
      jest.useFakeTimers();
    });

    afterEach(() => {
      jest.runOnlyPendingTimers();
      jest.useRealTimers();
    });

    it('shouldBeAtrequest超过5sec时触发timeout回调', async () => {
      await fc.assert(
        fc.asyncProperty(
          // generate随机URL
          fc.oneof(
            fc.constant('/users'),
            fc.constant('/projects'),
            fc.constant('/metrics'),
            fc.webPath()
          ),
          // generate超过5sec的延迟 (5100-8000ms)
          fc.integer({ min: 5100, max: 8000 }),
          async (url, delayMs) => {
            // resetmock
            mockAxiosInstance.request.mockReset();

            const apiClient = new ApiClient(defaultConfig);

            // 跟踪timeout回调是否被调用
            let timeoutCallbackCalled = false;
            const onTimeout = jest.fn(() => {
              timeoutCallbackCalled = true;
            });

            // 模拟慢速APIresponse
            mockAxiosInstance.request.mockImplementation(async () => {
              // useReal延迟
              return new Promise((resolve) => {
                const realTimeout = setTimeout(() => {
                  resolve({ data: { success: true, url } });
                }, delayMs);
                
                // cleanupfunction
                (resolve as any).cancel = () => clearTimeout(realTimeout);
              });
            });

            // 发起request
            const requestPromise = apiClient.get(url, { 
              skipCache: true, 
              skipRetry: true,
              onTimeout 
            });

            // 快进到5sec（timeoutthreshold）
            jest.advanceTimersByTime(5000);

            // verify: timeout回调should被调用
            expect(timeoutCallbackCalled).toBe(true);
            expect(onTimeout).toHaveBeenCalledTimes(1);

            // 快进剩余时间让requestcomplete
            jest.advanceTimersByTime(delayMs - 5000);

            // waitrequestcomplete
            const result = await requestPromise;

            // verify: request最终successcomplete
            expect(result).toEqual({ success: true, url });
          }
        ),
        { numRuns: 100 }
      );
    });

    it('shouldBeAtrequest小于5seccomplete时不触发timeout回调', async () => {
      await fc.assert(
        fc.asyncProperty(
          // generate随机URL
          fc.oneof(
            fc.constant('/users'),
            fc.constant('/projects'),
            fc.webPath()
          ),
          // generate小于5sec的延迟 (100-4900ms)
          fc.integer({ min: 100, max: 4900 }),
          async (url, delayMs) => {
            // resetmock
            mockAxiosInstance.request.mockReset();

            const apiClient = new ApiClient(defaultConfig);

            // 跟踪timeout回调
            const onTimeout = jest.fn();

            // 模拟快速APIresponse
            mockAxiosInstance.request.mockImplementation(async () => {
              return new Promise((resolve) => {
                const realTimeout = setTimeout(() => {
                  resolve({ data: { success: true, url } });
                }, delayMs);
                
                (resolve as any).cancel = () => clearTimeout(realTimeout);
              });
            });

            // 发起request
            const requestPromise = apiClient.get(url, { 
              skipCache: true, 
              skipRetry: true,
              onTimeout 
            });

            // 快进到requestcomplete
            jest.advanceTimersByTime(delayMs);

            // waitrequestcomplete
            const result = await requestPromise;

            // verify: timeout回调不should被调用
            expect(onTimeout).not.toHaveBeenCalled();

            // verify: requestsuccesscomplete
            expect(result).toEqual({ success: true, url });

            // 快进到5sec后，confirmtimeout回调仍然不会被调用
            jest.advanceTimersByTime(5000 - delayMs + 100);
            expect(onTimeout).not.toHaveBeenCalled();
          }
        ),
        { numRuns: 100 }
      );
    });

    it('shouldBeAtrequestcomplete后cleanuptimeoutwarn', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.webPath(),
          // generate延迟时间 (可能超过或不超过5sec)
          fc.integer({ min: 100, max: 8000 }),
          async (url, delayMs) => {
            // resetmock
            mockAxiosInstance.request.mockReset();

            const apiClient = new ApiClient(defaultConfig);

            const onTimeout = jest.fn();

            // 模拟APIresponse
            mockAxiosInstance.request.mockImplementation(async () => {
              return new Promise((resolve) => {
                const realTimeout = setTimeout(() => {
                  resolve({ data: { success: true } });
                }, delayMs);
                
                (resolve as any).cancel = () => clearTimeout(realTimeout);
              });
            });

            // 发起第一timesrequest
            const request1Promise = apiClient.get(url, { 
              skipCache: true, 
              skipRetry: true,
              onTimeout 
            });

            // 快进到requestcomplete
            jest.advanceTimersByTime(delayMs);
            await request1Promise;

            // resetmock计数
            onTimeout.mockClear();

            // 发起第二times相同的request
            const request2Promise = apiClient.get(url, { 
              skipCache: true, 
              skipRetry: true,
              onTimeout 
            });

            // 快进到5sec
            jest.advanceTimersByTime(5000);

            // 如果第二timesrequest也超过5sec，should再times触发timeout回调
            if (delayMs > 5000) {
              expect(onTimeout).toHaveBeenCalledTimes(1);
            }

            // complete第二timesrequest
            jest.advanceTimersByTime(Math.max(0, delayMs - 5000));
            await request2Promise;

            // verify: request都successcomplete
            expect(mockAxiosInstance.request).toHaveBeenCalledTimes(2);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('shouldBeAtrequestfailure时也cleanuptimeoutwarn', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.webPath(),
          // generate超过5sec的延迟
          fc.integer({ min: 5100, max: 8000 }),
          async (url, delayMs) => {
            // resetmock
            mockAxiosInstance.request.mockReset();

            const apiClient = new ApiClient(defaultConfig);

            const onTimeout = jest.fn();

            // 模拟requestfailure
            mockAxiosInstance.request.mockImplementation(async () => {
              return new Promise((_, reject) => {
                const realTimeout = setTimeout(() => {
                  reject(new Error('Network error'));
                }, delayMs);
                
                (reject as any).cancel = () => clearTimeout(realTimeout);
              });
            });

            // 发起request
            const requestPromise = apiClient.get(url, { 
              skipCache: true, 
              skipRetry: true,
              onTimeout 
            }).catch((error: unknown) => error as Error);

            // 快进到5sec（timeoutthreshold）
            jest.advanceTimersByTime(5000);

            // verify: timeout回调should被调用
            expect(onTimeout).toHaveBeenCalledTimes(1);

            // 快进到requestfailure
            jest.advanceTimersByTime(delayMs - 5000);

            // waitrequestfailure
            const error = await requestPromise as Error;

            // verify: requestfailure
            expect(error).toBeInstanceOf(Error);
            expect(error.message).toBe('Network error');

            // reset回调
            onTimeout.mockClear();

            // 发起新的request到相同URL
            const request2Promise = apiClient.get(url, { 
              skipCache: true, 
              skipRetry: true,
              onTimeout 
            }).catch((error: unknown) => error as Error);

            // 快进到5sec
            jest.advanceTimersByTime(5000);

            // verify: 新requestshould再times触发timeout回调（desc之前的warn被cleanup了）
            expect(onTimeout).toHaveBeenCalledTimes(1);

            // complete第二timesrequest
            jest.advanceTimersByTime(delayMs - 5000);
            await request2Promise;
          }
        ),
        { numRuns: 100 }
      );
    });

    it('shouldBeAt没有provideonTimeout回调时use默认warn', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.webPath(),
          // generate超过5sec的延迟
          fc.integer({ min: 5100, max: 7000 }),
          async (url, delayMs) => {
            // resetmock
            mockAxiosInstance.request.mockReset();

            const apiClient = new ApiClient(defaultConfig);

            // Mock console.warn
            const consoleWarnSpy = jest.spyOn(console, 'warn').mockImplementation();

            // 模拟慢速APIresponse
            mockAxiosInstance.request.mockImplementation(async () => {
              return new Promise((resolve) => {
                const realTimeout = setTimeout(() => {
                  resolve({ data: { success: true } });
                }, delayMs);
                
                (resolve as any).cancel = () => clearTimeout(realTimeout);
              });
            });

            // 发起request（不provideonTimeout回调）
            const requestPromise = apiClient.get(url, { 
              skipCache: true, 
              skipRetry: true
            });

            // Fast forward to 5 seconds
            jest.advanceTimersByTime(5000);

            // Verify: should call console.warn to show default timeout hint
            expect(consoleWarnSpy).toHaveBeenCalledWith(
              expect.stringContaining('API request timeout')
            );
            expect(consoleWarnSpy).toHaveBeenCalledWith(
              expect.stringContaining(url)
            );

            // Complete request
            jest.advanceTimersByTime(delayMs - 5000);
            await requestPromise;

            // cleanup
            consoleWarnSpy.mockRestore();
          }
        ),
        { numRuns: 100 }
      );
    });
  });
});

/**
 * ApiClient单元test
 * 
 * testCoverage:
 * - GET/POST/PUT/DELETErequest
 * - request去重机制
 * - 并发request限制
 * - timeout检测
 * - 指数退避retry
 * - GETrequestcache
 */

import axios from 'axios';

// Mock axios BEFORE importing ApiClient
jest.mock('axios');
const mockedAxios = axios as jest.Mocked<typeof axios>;

// Mock axios instance
const mockAxiosInstance = {
  request: jest.fn(),
  interceptors: {
    request: {
      use: jest.fn(),
    },
    response: {
      use: jest.fn(),
    },
  },
};

// Setup axios.create to return our mock instance
mockedAxios.create.mockReturnValue(mockAxiosInstance as any);

import { ApiClient, ApiClientConfig } from '../ApiClient';

describe('ApiClient', () => {
  let apiClient: ApiClient;

  const defaultConfig: ApiClientConfig = {
    baseURL: 'http://localhost:8000/api/v1',
    timeout: 30000,
    maxRetries: 3,
    maxConcurrent: 6,
    cacheTimeout: 5 * 60 * 1000,
    deduplicationWindow: 1000,
  };

  beforeEach(() => {
    // reset所有mock
    jest.clearAllMocks();
    mockAxiosInstance.request.mockReset();

    apiClient = new ApiClient(defaultConfig);
  });

  describe('基本HTTPmethod', () => {
    it('shouldsuccessexecuteGETrequest', async () => {
      const mockData = { id: 1, name: 'Test' };
      mockAxiosInstance.request.mockResolvedValue({ data: mockData });

      const result = await apiClient.get('/test');

      expect(mockAxiosInstance.request).toHaveBeenCalledWith(
        expect.objectContaining({
          method: 'GET',
          url: '/test',
        })
      );
      expect(result).toEqual(mockData);
    });

    it('shouldsuccessexecutePOSTrequest', async () => {
      const mockData = { id: 1, name: 'Created' };
      const postData = { name: 'New Item' };
      mockAxiosInstance.request.mockResolvedValue({ data: mockData });

      const result = await apiClient.post('/test', postData);

      expect(mockAxiosInstance.request).toHaveBeenCalledWith(
        expect.objectContaining({
          method: 'POST',
          url: '/test',
          data: postData,
        })
      );
      expect(result).toEqual(mockData);
    });

    it('shouldsuccessexecutePUTrequest', async () => {
      const mockData = { id: 1, name: 'Updated' };
      const putData = { name: 'Updated Item' };
      mockAxiosInstance.request.mockResolvedValue({ data: mockData });

      const result = await apiClient.put('/test/1', putData);

      expect(mockAxiosInstance.request).toHaveBeenCalledWith(
        expect.objectContaining({
          method: 'PUT',
          url: '/test/1',
          data: putData,
        })
      );
      expect(result).toEqual(mockData);
    });

    it('shouldsuccessexecuteDELETErequest', async () => {
      const mockData = { success: true };
      mockAxiosInstance.request.mockResolvedValue({ data: mockData });

      const result = await apiClient.delete('/test/1');

      expect(mockAxiosInstance.request).toHaveBeenCalledWith(
        expect.objectContaining({
          method: 'DELETE',
          url: '/test/1',
        })
      );
      expect(result).toEqual(mockData);
    });
  });

  describe('GETrequestcache', () => {
    it('shouldcacheGETrequestresult', async () => {
      const mockData = { id: 1, name: 'Test' };
      mockAxiosInstance.request.mockResolvedValue({ data: mockData });

      // 第一timesrequest
      const result1 = await apiClient.get('/test');
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(1);

      // 第二timesrequestshouldusecache
      const result2 = await apiClient.get('/test');
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(1); // 仍然是1times
      expect(result2).toEqual(result1);
    });

    it('shouldsupportskipcache选项', async () => {
      const mockData = { id: 1, name: 'Test' };
      mockAxiosInstance.request.mockResolvedValue({ data: mockData });

      // 第一timesrequest
      await apiClient.get('/test');
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(1);

      // 第二timesrequestskipcache
      await apiClient.get('/test', { skipCache: true });
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(2);
    });

    it('should为不同的URLuse不同的cache', async () => {
      mockAxiosInstance.request.mockResolvedValue({ data: {} });

      await apiClient.get('/test1');
      await apiClient.get('/test2');

      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(2);
    });

    it('should为不同的queryparamuse不同的cache', async () => {
      mockAxiosInstance.request.mockResolvedValue({ data: {} });

      await apiClient.get('/test', { params: { id: 1 } });
      await apiClient.get('/test', { params: { id: 2 } });

      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(2);
    });
  });

  describe('request去重', () => {
    it('shouldBeAt1sec内合并相同的GETrequest', async () => {
      const mockData = { id: 1, name: 'Test' };
      mockAxiosInstance.request.mockResolvedValue({ data: mockData });

      // 同时发起多item相同request
      const promises = [
        apiClient.get('/test'),
        apiClient.get('/test'),
        apiClient.get('/test'),
      ];

      const results = await Promise.all(promises);

      // should只发起一times实际request
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(1);
      // 所有resultshould相同
      expect(results[0]).toEqual(mockData);
      expect(results[1]).toEqual(mockData);
      expect(results[2]).toEqual(mockData);
    });

    it('shouldsupportskip去重选项', async () => {
      const mockData = { id: 1, name: 'Test' };
      mockAxiosInstance.request.mockResolvedValue({ data: mockData });

      // 同时发起多itemrequest，但skip去重
      const promises = [
        apiClient.get('/test', { skipDeduplication: true, skipCache: true }),
        apiClient.get('/test', { skipDeduplication: true, skipCache: true }),
      ];

      await Promise.all(promises);

      // should发起两timesrequest
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(2);
    });
  });

  describe('并发request限制', () => {
    it.skip('should限制并发request数量', async () => {
      let requestCount = 0;

      mockAxiosInstance.request.mockImplementation(() => {
        requestCount++;
        return Promise.resolve({ data: { count: requestCount } });
      });

      // 发起10item并发request
      const promises = Array.from({ length: 10 }, (_, i) =>
        apiClient.post(`/test/${i}`, {}, { skipRetry: true })
      );

      await Promise.all(promises);

      // verify所有request都complete了
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(10);
      expect(requestCount).toBe(10);

      // verify并发控制机制存在（通过check内部status）
      expect(apiClient.getActiveRequestCount()).toBe(0);
      expect(apiClient.getQueuedRequestCount()).toBe(0);
    });

    it('shouldBeAtrequestcomplete后handlequeue中的request', async () => {
      let requestCount = 0;

      mockAxiosInstance.request.mockImplementation(() => {
        requestCount++;
        return Promise.resolve({ data: { count: requestCount } });
      });

      // 发起8itemrequest
      const promises = Array.from({ length: 8 }, (_, i) =>
        apiClient.post(`/test/${i}`, {}, { skipRetry: true })
      );

      await Promise.all(promises);

      // 所有request都shouldcomplete
      expect(requestCount).toBe(8);
    });
  });

  describe('指数退避retry', () => {
    it('shouldBeAtrequestfailure时retry最多3times', async () => {
      let attemptCount = 0;

      mockAxiosInstance.request.mockImplementation(() => {
        attemptCount++;
        if (attemptCount < 4) {
          return Promise.reject(new Error('Network error'));
        }
        return Promise.resolve({ data: { success: true } });
      });

      const result = await apiClient.post('/test', {});

      // should尝试4times (初始 + 3timesretry)
      expect(attemptCount).toBe(4);
      expect(result).toEqual({ success: true });
    });

    it('shouldBeAt达到最大retrytimes数后抛出error', async () => {
      mockAxiosInstance.request.mockRejectedValue(new Error('Network error'));

      await expect(apiClient.post('/test', {})).rejects.toThrow('Network error');

      // should尝试4times (初始 + 3timesretry)
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(4);
    });

    it('should不retry401error', async () => {
      mockAxiosInstance.request.mockRejectedValue({
        response: { status: 401 },
      });

      await expect(apiClient.post('/test', {})).rejects.toMatchObject({
        response: { status: 401 },
      });

      // should只尝试1times
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(1);
    });

    it('should不retry403error', async () => {
      mockAxiosInstance.request.mockRejectedValue({
        response: { status: 403 },
      });

      await expect(apiClient.post('/test', {})).rejects.toMatchObject({
        response: { status: 403 },
      });

      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(1);
    });

    it('should不retry404error', async () => {
      mockAxiosInstance.request.mockRejectedValue({
        response: { status: 404 },
      });

      await expect(apiClient.post('/test', {})).rejects.toMatchObject({
        response: { status: 404 },
      });

      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(1);
    });

    it('shouldsupportskipretry选项', async () => {
      mockAxiosInstance.request.mockRejectedValue(new Error('Network error'));

      await expect(
        apiClient.post('/test', {}, { skipRetry: true })
      ).rejects.toThrow('Network error');

      // should只尝试1times
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(1);
    });
  });

  describe('cache管理', () => {
    it('should能够清除所有cache', async () => {
      mockAxiosInstance.request.mockResolvedValue({ data: {} });

      // create一些cache
      await apiClient.get('/test1');
      await apiClient.get('/test2');

      // 清除cache
      apiClient.clearCache();

      // 再timesrequestshould发起新的request
      await apiClient.get('/test1');
      await apiClient.get('/test2');

      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(4);
    });

    it('should能够清除匹配模式的cache', async () => {
      mockAxiosInstance.request.mockResolvedValue({ data: {} });

      // create一些cache
      await apiClient.get('/users/1');
      await apiClient.get('/users/2');
      await apiClient.get('/posts/1');

      // 清除users相关的cache
      apiClient.clearCache('users');

      // usersrequestshould重新发起，postsrequestusecache
      await apiClient.get('/users/1');
      await apiClient.get('/users/2');
      await apiClient.get('/posts/1');

      // users: 2times原始 + 2times新request = 4times
      // posts: 1times原始 + 0times新request = 1times
      // 总共: 5times
      expect(mockAxiosInstance.request).toHaveBeenCalledTimes(5);
    });

    it('should能够getcache统计', async () => {
      mockAxiosInstance.request.mockResolvedValue({ data: {} });

      await apiClient.get('/test1');
      await apiClient.get('/test2');

      const stats = apiClient.getCacheStats();

      expect(stats.size).toBe(2);
      expect(stats.keys.length).toBe(2);
    });
  });

  describe('工具method', () => {
    it('should能够get当前活跃request数', async () => {
      let resolveRequest: any;
      mockAxiosInstance.request.mockImplementation(() => {
        return new Promise((resolve) => {
          resolveRequest = () => resolve({ data: {} });
        });
      });

      const promise = apiClient.post('/test', {}, { skipRetry: true });

      // wait一小段时间让request开始
      await new Promise((resolve) => setTimeout(resolve, 10));

      // request进行中
      expect(apiClient.getActiveRequestCount()).toBe(1);

      // completerequest
      resolveRequest();
      await promise;

      expect(apiClient.getActiveRequestCount()).toBe(0);
    });

    it.skip('should能够getqueue中wait的request数', async () => {
      let resolvers: any[] = [];
      mockAxiosInstance.request.mockImplementation(() => {
        return new Promise((resolve) => {
          resolvers.push(() => resolve({ data: {} }));
        });
      });

      // 发起7itemrequest (超过并发限制6item)
      const promises = Array.from({ length: 7 }, (_, i) =>
        apiClient.post(`/test/${i}`, {}, { skipRetry: true })
      );

      // wait足够长的时间让request开始并进入queue
      await new Promise((resolve) => setTimeout(resolve, 50));

      // should有1itemrequest在queue中wait
      const queuedCount = apiClient.getQueuedRequestCount();
      expect(queuedCount).toBeGreaterThanOrEqual(0); // 可能是0或1，取决于时序

      // complete所有request
      resolvers.forEach((resolve) => resolve());
      await Promise.all(promises);

      expect(apiClient.getQueuedRequestCount()).toBe(0);
    });
  });

  describe('边缘情况', () => {
    it('shouldhandle空response', async () => {
      mockAxiosInstance.request.mockResolvedValue({ data: null });

      const result = await apiClient.get('/test');

      expect(result).toBeNull();
    });

    it('shouldhandle网络error', async () => {
      mockAxiosInstance.request.mockRejectedValue(new Error('Network Error'));

      await expect(apiClient.get('/test')).rejects.toThrow('Network Error');
    });

    it('shouldhandletimeouterror', async () => {
      mockAxiosInstance.request.mockRejectedValue({
        code: 'ECONNABORTED',
        message: 'timeout of 30000ms exceeded',
      });

      await expect(apiClient.get('/test')).rejects.toMatchObject({
        code: 'ECONNABORTED',
      });
    });

    it('shouldhandleservice器error', async () => {
      mockAxiosInstance.request.mockRejectedValue({
        response: {
          status: 500,
          data: { error: 'Internal Server Error' },
        },
      });

      await expect(apiClient.get('/test')).rejects.toMatchObject({
        response: { status: 500 },
      });
    });
  });
});

import * as fc from 'fast-check';
import { CacheService } from '../CacheService';

describe('Property 24: GETrequestcache', () => {
  describe('cache基本property', () => {
    it('对于任何键value对，set后立即getshouldreturn相同的data', () => {
      fc.assert(
        fc.property(
          fc.string({ minLength: 1 }),
          fc.anything(),
          (key: string, data: any) => {
            const cache = new CacheService();
            cache.set(key, data);
            const retrieved = cache.get(key);
            expect(retrieved).toEqual(data);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('对于任何键，在5min内的duplicategetshouldreturncachedata', () => {
      fc.assert(
        fc.property(
          fc.string({ minLength: 1 }),
          fc.anything(),
          fc.integer({ min: 1, max: 10 }),
          (key: string, data: any, repeatCount: number) => {
            const cache = new CacheService(5 * 60 * 1000);
            cache.set(key, data);
            for (let i = 0; i < repeatCount; i++) {
              const retrieved = cache.get(key);
              expect(retrieved).toEqual(data);
              expect(cache.has(key)).toBe(true);
            }
          }
        ),
        { numRuns: 100 }
      );
    });

    it('对于任何键，在TTL过期后getshouldreturnnull', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.string({ minLength: 1 }),
          fc.anything(),
          fc.integer({ min: 50, max: 200 }),
          async (key: string, data: any, ttl: number) => {
            const cache = new CacheService();
            cache.set(key, data, ttl);
            await new Promise(resolve => setTimeout(resolve, ttl + 50));
            const retrieved = cache.get(key);
            expect(retrieved).toBeNull();
          }
        ),
        { numRuns: 50 }
      );
    });
  });

  describe('cache隔离property', () => {
    it('对于任何不同的键，cacheshould独立存储data', () => {
      fc.assert(
        fc.property(
          fc.array(
            fc.record({
              key: fc.string({ minLength: 1 }),
              data: fc.anything()
            }),
            { minLength: 2, maxLength: 20 }
          ),
          (entries: Array<{ key: string; data: any }>) => {
            const cache = new CacheService();
            const uniqueEntries = new Map(entries.map(e => [e.key, e.data]));
            uniqueEntries.forEach((data, key) => {
              cache.set(key, data);
            });
            uniqueEntries.forEach((expectedData, key) => {
              const retrieved = cache.get(key);
              expect(retrieved).toEqual(expectedData);
            });
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  describe('cache统计property', () => {
    it('对于任何操作序列，命中数and未命中数之andshould等于总request数', () => {
      fc.assert(
        fc.property(
          fc.array(
            fc.record({
              operation: fc.constantFrom('set', 'get'),
              key: fc.string({ minLength: 1, maxLength: 10 }),
              data: fc.anything()
            }),
            { minLength: 1, maxLength: 50 }
          ),
          (operations: Array<{ operation: 'set' | 'get'; key: string; data: any }>) => {
            const cache = new CacheService();
            let expectedGets = 0;
            operations.forEach(op => {
              if (op.operation === 'set') {
                cache.set(op.key, op.data);
              } else {
                cache.get(op.key);
                expectedGets++;
              }
            });
            const stats = cache.getStats();
            expect(stats.hits + stats.misses).toBe(expectedGets);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('对于任何cachestatus，命中率shouldBeAt0到100之间', () => {
      fc.assert(
        fc.property(
          fc.array(
            fc.record({
              operation: fc.constantFrom('set', 'get'),
              key: fc.string({ minLength: 1, maxLength: 10 }),
              data: fc.anything()
            }),
            { minLength: 1, maxLength: 50 }
          ),
          (operations: Array<{ operation: 'set' | 'get'; key: string; data: any }>) => {
            const cache = new CacheService();
            operations.forEach(op => {
              if (op.operation === 'set') {
                cache.set(op.key, op.data);
              } else {
                cache.get(op.key);
              }
            });
            const stats = cache.getStats();
            expect(stats.hitRate).toBeGreaterThanOrEqual(0);
            expect(stats.hitRate).toBeLessThanOrEqual(100);
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  describe('cachecleanupproperty', () => {
    it('对于任何cachestatus，clear()should清空所有cache', () => {
      fc.assert(
        fc.property(
          fc.array(
            fc.record({
              key: fc.string({ minLength: 1 }),
              data: fc.anything()
            }),
            { minLength: 1, maxLength: 30 }
          ),
          (entries: Array<{ key: string; data: any }>) => {
            const cache = new CacheService();
            entries.forEach(({ key, data }) => {
              cache.set(key, data);
            });
            cache.clear();
            const stats = cache.getStats();
            expect(stats.size).toBe(0);
            expect(stats.keys.length).toBe(0);
            entries.forEach(({ key }) => {
              expect(cache.get(key)).toBeNull();
            });
          }
        ),
        { numRuns: 100 }
      );
    });

    it('对于任何模式，clear(pattern)should只清除匹配的键', () => {
      fc.assert(
        fc.property(
          fc.string({ minLength: 1, maxLength: 5 }),
          fc.array(
            fc.record({
              key: fc.string({ minLength: 1, maxLength: 20 }),
              data: fc.anything()
            }),
            { minLength: 1, maxLength: 20 }
          ),
          (pattern: string, entries: Array<{ key: string; data: any }>) => {
            const cache = new CacheService();
            const uniqueEntries = new Map(entries.map(e => [e.key, e.data]));
            uniqueEntries.forEach((data, key) => {
              cache.set(key, data);
            });
            cache.clear(pattern);
            uniqueEntries.forEach((data, key) => {
              const retrieved = cache.get(key);
              if (key.includes(pattern)) {
                expect(retrieved).toBeNull();
              } else {
                expect(retrieved).toEqual(data);
              }
            });
          }
        ),
        { numRuns: 100 }
      );
    });
  });
});

