                if (expectedExpanded) {
                  parentNode.children.forEach((child) => {
                    expect(screen.getByTestId(`node-${child.id}`)).toBeInTheDocument();
                  });
                } else {
                  parentNode.children.forEach((child) => {
                    expect(
                      screen.queryByTestId(`node-${child.id}`)
                    ).not.toBeInTheDocument();
                  });
                }
              },
              { timeout: 3000 }
            );
          } finally {
            unmount();
            cleanup();
          }
        }
      ),
      { numRuns: 50 }
    );
  }, 60000);
