          // waitrendercomplete
          await new Promise(resolve => setTimeout(resolve, 100));

          // getrender的project列表
          const projectElements = container.querySelectorAll('[data-testid="virtual-list"] > div, .projects-virtual-list > div > div');
          const renderedProjects: Project[] = [];

