          // check所有图片元素
          const images = container!.querySelectorAll('img');
          
          images.forEach(img => {
            const width = img.getBoundingClientRect().width;
            
            // 图片宽度不should超过视口宽度
            expect(width).toBeLessThanOrEqual(viewportWidth);
          });

          unmount!();
