  it('Dashboardshould正确应用response式CSSclass', async () => {
    await fc.assert(
      fc.asyncProperty(
        viewportWidthArbitrary(),
        async (viewportWidth) => {
          setViewportWidth(viewportWidth);

          let container: HTMLElement;
